import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface SerialLog {
  id: string;
  timestamp: Date;
  type: 'in' | 'out' | 'info' | 'error';
  text: string;
}

export type ConnectionStatus = 'disconnected' | 'connecting' | 'connected' | 'error';

export interface SerialOptions {
  baudRate: number;
  bufferSize?: number;
}

import { useState, useCallback, useRef, useEffect } from 'react';
import { SerialLog, ConnectionStatus, SerialOptions } from '../types';

export const useSerial = () => {
  const [status, setStatus] = useState<ConnectionStatus>('disconnected');
  const [logs, setLogs] = useState<SerialLog[]>([]);
  const [port, setPort] = useState<SerialPort | null>(null);
  const [error, setError] = useState<string | null>(null);

  const readerRef = useRef<ReadableStreamDefaultReader<string> | null>(null);
  const writerRef = useRef<WritableStreamDefaultWriter<string> | null>(null);

  const addLog = useCallback((text: string, type: SerialLog['type']) => {
    const newLog: SerialLog = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date(),
      type,
      text
    };
    setLogs(prev => [...prev.slice(-999), newLog]); // Keep last 1000 logs
  }, []);

  const disconnect = useCallback(async () => {
    if (readerRef.current) {
      await readerRef.current.cancel();
      readerRef.current = null;
    }
    if (writerRef.current) {
      await writerRef.current.releaseLock();
      writerRef.current = null;
    }
    if (port) {
      try {
        await port.close();
      } catch (e) {
        console.error("Error closing port:", e);
      }
      setPort(null);
    }
    setStatus('disconnected');
    addLog('Disconnected from port.', 'info');
  }, [port, addLog]);

  const connect = useCallback(async (options: SerialOptions) => {
    if (!('serial' in navigator)) {
      setError('Web Serial API is not supported in this browser.');
      return;
    }

    try {
      setStatus('connecting');
      const selectedPort = await (navigator as any).serial.requestPort();
      await selectedPort.open({ baudRate: options.baudRate });

      setPort(selectedPort);
      setStatus('connected');
      addLog(`Connected at ${options.baudRate} baud.`, 'info');

      // Setup Read Stream
      const textDecoder = new TextDecoderStream();
      const readableStreamClosed = selectedPort.readable.pipeTo(textDecoder.writable);
      const reader = textDecoder.readable.getReader();
      readerRef.current = reader;

      // Setup Write Stream
      const textEncoder = new TextEncoderStream();
      const writableStreamClosed = textEncoder.readable.pipeTo(selectedPort.writable);
      const writer = textEncoder.writable.getWriter();
      writerRef.current = writer;

      // Read loop
      (async () => {
        try {
          while (true) {
            const { value, done } = await reader.read();
            if (done) break;
            if (value) {
              addLog(value, 'in');
            }
          }
        } catch (err) {
          console.error('Read error:', err);
          addLog(`Read error: ${err}`, 'error');
          setStatus('error');
        } finally {
          reader.releaseLock();
        }
      })();

    } catch (err: any) {
      console.error('Connection failed:', err);
      setError(err.message || 'Failed to connect to the serial port.');
      setStatus('disconnected');
      addLog(`Connection failed: ${err.message}`, 'error');
    }
  }, [addLog]);

  const sendData = useCallback(async (data: string) => {
    if (!writerRef.current) return;
    try {
      await writerRef.current.write(data);
      addLog(data, 'out');
    } catch (err: any) {
      addLog(`Write error: ${err.message}`, 'error');
    }
  }, [addLog]);

  const clearLogs = useCallback(() => {
    setLogs([]);
  }, []);

  return {
    status,
    logs,
    connect,
    disconnect,
    sendData,
    clearLogs,
    error
  };
};

import React, { useEffect, useRef } from 'react';
import { SerialLog } from '../types';

interface TerminalProps {
  logs: SerialLog[];
}

const Terminal: React.FC<TerminalProps> = ({ logs }) => {
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [logs]);

  const getLogStyle = (type: SerialLog['type']) => {
    switch (type) {
      case 'in': return 'text-emerald-400';
      case 'out': return 'text-sky-400';
      case 'error': return 'text-rose-500 font-bold';
      case 'info': return 'text-slate-400 italic';
      default: return 'text-slate-200';
    }
  };

  const formatTimestamp = (date: Date) => {
    return date.toLocaleTimeString([], { hour12: false, hour: '2-digit', minute: '2-digit', second: '2-digit', fractionalSecondDigits: 3 });
  };

  return (
    <div 
      ref={scrollRef}
      className="flex-grow bg-slate-900/50 rounded-xl border border-slate-700 p-4 overflow-y-auto font-mono text-sm leading-relaxed"
    >
      {logs.length === 0 ? (
        <div className="h-full flex flex-col items-center justify-center text-slate-500 space-y-2 opacity-50">
          <svg className="w-12 h-12" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M8 9l3 3-3 3m5 0h3M5 20h14a2 2 0 002-2V6a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
          </svg>
          <p>Waiting for connection...</p>
        </div>
      ) : (
        logs.map((log) => (
          <div key={log.id} className="group flex gap-3 py-0.5 hover:bg-slate-800/30 rounded px-1 transition-colors">
            <span className="text-slate-600 select-none whitespace-nowrap opacity-50 group-hover:opacity-100">
              [{formatTimestamp(log.timestamp)}]
            </span>
            <span className={`whitespace-pre-wrap break-all ${getLogStyle(log.type)}`}>
              {log.type === 'out' ? `→ ${log.text}` : log.text}
            </span>
          </div>
        ))
      )}
    </div>
  );
};

export default Terminal;

