          <button
            type="submit"
            disabled={status !== 'connected' || !inputText}
            className="bg-sky-600 hover:bg-sky-500 text-white px-6 py-2 rounded-lg text-sm font-medium transition-colors disabled:opacity-50 disabled:bg-slate-700"
