          </div>
        </div>

        <div className="flex items-start gap-3 p-4 bg-slate-800/50 rounded-xl border border-slate-700">
          <div className="p-2 bg-amber-500/10 rounded-lg text-amber-400">
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg>
          </div>
          <div>
            <h4 className="text-slate-200 font-semibold mb-1">Privacy Focused</h4>
            <p className="leading-relaxed">All data is processed locally. Your serial communication never leaves your machine.</p>
          </div>
        </div>
      </footer>

      {error && (
        <div className="fixed bottom-6 right-6 max-w-sm bg-rose-500 text-white p-4 rounded-xl shadow-2xl flex gap-3 items-center">
          <svg className="w-6 h-6 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
          <span className="text-sm font-medium">{error}</span>
        </div>
      )}
    </div>
  );
};

