import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { useSerial } from './hooks/useSerial';
import Terminal from './components/Terminal';
import { Learner } from './types';
import { supabase } from './lib/supabase';

const App: React.FC = () => {
  const { status, logs, connect, disconnect, clearError, error } = useSerial();
  const [baudRate, setBaudRate] = useState(9600);

  // Database State
  const [learners, setLearners] = useState<Learner[]>([]);
  const [loading, setLoading] = useState(true);
  const [dbError, setDbError] = useState<string | null>(null);
  const [fetchedCount, setFetchedCount] = useState(0);

  // Registration State
  const [selectedLearnerId, setSelectedLearnerId] = useState<string | null>(null);
  const [activeRfid, setActiveRfid] = useState<string>('');
  const [searchQuery, setSearchQuery] = useState('');

  // Local UID Mappings (Persistence for Read-Only DB environments)
  const [uidMappings, setUidMappings] = useState<Record<string, string>>(() => {
    const saved = localStorage.getItem('rfid_mappings');
    return saved ? JSON.parse(saved) : {};
  });

  /**
   * Fetches all learners from Supabase using pagination to bypass 
   * the default 1000-row limit of PostgREST.
   */
  const fetchLearners = useCallback(async () => {
    try {
      setLoading(true);
      setDbError(null);
      let allData: Learner[] = [];
      let from = 0;
      const step = 1000;
      let hasMore = true;

      while (hasMore) {
        const { data, error: fetchErr } = await supabase
          .from('learners')
          .select('*')
          .range(from, from + step - 1);

        if (fetchErr) throw fetchErr;

        if (data && data.length > 0) {
          allData = [...allData, ...data];
          setFetchedCount(allData.length);
          if (data.length < step) {
            hasMore = false;
          } else {
            from += step;
          }
        } else {
          hasMore = false;
        }
      }

      setLearners(allData);
    } catch (err: any) {
      console.error('Database fetch error:', err);
      setDbError(err.message || 'Failed to fetch learners from database.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchLearners();
  }, [fetchLearners]);

  // Sync mappings to localStorage
  useEffect(() => {
    localStorage.setItem('rfid_mappings', JSON.stringify(uidMappings));
  }, [uidMappings]);

  // Capture RFID from Serial Logs (Arduino output)
  useEffect(() => {
    const lastLog = logs[logs.length - 1];
    if (lastLog && lastLog.type === 'in') {
      const cleanedRfid = lastLog.text.trim();
      // Most RFID UIDs are 4-10 characters long
      if (cleanedRfid.length >= 4) { 
        setActiveRfid(cleanedRfid);
      }
    }
  }, [logs]);

  // Link UID to Learner (Local Save)
  const handleLink = () => {
    if (!selectedLearnerId || !activeRfid) return;

    // Check if this UID is already assigned to a DIFFERENT learner
    const existingEntry = Object.entries(uidMappings).find(([id, uid]) => uid === activeRfid && id !== selectedLearnerId);
    if (existingEntry) {
      const [learnerId] = existingEntry;
      const otherLearner = learners.find(l => l.id === learnerId);
      alert(`Tag ${activeRfid} is already assigned to ${otherLearner?.firstName || 'another learner'}.`);
      return;
    }

    setUidMappings(prev => ({
      ...prev,
      [selectedLearnerId]: activeRfid
    }));

    // Clear the active buffer but keep selection for visual confirmation if needed
    setActiveRfid('');
    setSelectedLearnerId(null);
  };

  const removeMapping = (id: string) => {
    if (confirm("Permanently unlink this RFID card?")) {
      const newMappings = { ...uidMappings };
      delete newMappings[id];
      setUidMappings(newMappings);
    }
  };

  const filteredLearners = useMemo(() => {
    const query = searchQuery.toLowerCase();
    return learners.filter(l => {
      const fullName = `${l.firstName} ${l.middleName || ''} ${l.lastName}`.toLowerCase();
      const lrn = l.lrn?.toLowerCase() || '';
      const rfid = uidMappings[l.id]?.toLowerCase() || '';
      return fullName.includes(query) || lrn.includes(query) || rfid.includes(query);
    });
  }, [learners, searchQuery, uidMappings]);

  const selectedLearner = useMemo(() => 
    learners.find(l => l.id === selectedLearnerId), 
  [learners, selectedLearnerId]);

  return (
    <div className="min-h-screen bg-[#020617] text-slate-200 flex flex-col p-4 md:p-8">
      {/* Dynamic Header */}
      <header className="max-w-7xl mx-auto w-full flex flex-col md:flex-row justify-between items-center mb-10 gap-6">
