import { useState, useCallback, useRef, useEffect } from 'react';
import { SerialLog, ConnectionStatus, SerialOptions, SerialPort } from '../types';

export const useSerial = () => {
  const [status, setStatus] = useState<ConnectionStatus>('disconnected');
  const [logs, setLogs] = useState<SerialLog[]>([]);
  const [port, setPort] = useState<SerialPort | null>(null);
  const [error, setError] = useState<string | null>(null);

  const readerRef = useRef<ReadableStreamDefaultReader<string> | null>(null);
  const writerRef = useRef<WritableStreamDefaultWriter<string> | null>(null);
  const portRef = useRef<any>(null);

  const addLog = useCallback((text: string, type: SerialLog['type']) => {
    const newLog: SerialLog = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date(),
      type,
      text
    };
    setLogs(prev => [...prev.slice(-999), newLog]);
  }, []);

  const disconnect = useCallback(async () => {
    setStatus('disconnected');

    try {
      if (readerRef.current) {
        await readerRef.current.cancel();
        readerRef.current = null;
      }
      if (writerRef.current) {
        await writerRef.current.close();
        writerRef.current = null;
      }
      if (portRef.current) {
        await portRef.current.close();
        portRef.current = null;
      }
    } catch (e) {
      console.error("Cleanup error:", e);
    }

    setPort(null);
    addLog('Disconnected from port.', 'info');
  }, [addLog]);

  // Handle unmount cleanup
  useEffect(() => {
    return () => {
      if (status === 'connected') {
        disconnect();
      }
    };
  }, [status, disconnect]);

  const connect = useCallback(async (options: SerialOptions) => {
    if (!('serial' in navigator)) {
      setError('Web Serial API is not supported in this browser.');
      return;
    }

    try {
      setError(null);
      setStatus('connecting');

      // 1. Request port from user
      const selectedPort = await (navigator as any).serial.requestPort();

      // 2. Try to open the port
      try {
        await selectedPort.open({ baudRate: options.baudRate });
      } catch (openErr: any) {
        if (openErr.name === 'NetworkError' || openErr.message.includes('busy')) {
          throw new Error('Serial Port is BUSY. Please close Arduino IDE Serial Monitor or other apps using this port.');
        }
        throw openErr;
      }

      portRef.current = selectedPort;
      setPort(selectedPort);
      setStatus('connected');
      addLog(`Connected at ${options.baudRate} baud.`, 'info');

      // Setup Streams
      const textDecoder = new TextDecoderStream();
      const readableStreamClosed = selectedPort.readable.pipeTo(textDecoder.writable);
      const reader = textDecoder.readable.getReader();
      readerRef.current = reader;

      const textEncoder = new TextEncoderStream();
      const writableStreamClosed = textEncoder.readable.pipeTo(selectedPort.writable);
      const writer = textEncoder.writable.getWriter();
      writerRef.current = writer;

      // Read loop
      (async () => {
        try {
          while (true) {
            const { value, done } = await reader.read();
            if (done) break;
            if (value) {
              // Only add non-empty strings to logs to avoid clutter
              const trimmed = value.trim();
              if (trimmed) addLog(trimmed, 'in');
            }
          }
        } catch (err: any) {
          if (status === 'connected') {
            console.error('Read error:', err);
            addLog(`Read error: ${err.message}`, 'error');
            setStatus('error');
          }
        } finally {
          reader.releaseLock();
        }
      })();

    } catch (err: any) {
      console.error('Connection failed:', err);
      const msg = err.message || 'Failed to connect to the serial port.';
      setError(msg);
      setStatus('disconnected');
      addLog(`Connection failed: ${msg}`, 'error');
    }
  }, [addLog, status]);

  const sendData = useCallback(async (data: string) => {
    if (!writerRef.current) return;
    try {
      await writerRef.current.write(data);
      addLog(data, 'out');
    } catch (err: any) {
      addLog(`Write error: ${err.message}`, 'error');
    }
  }, [addLog]);

  const clearLogs = useCallback(() => {
    setLogs([]);
  }, []);

  const clearError = useCallback(() => {
    setError(null);
  }, []);

  return {
    status,
    logs,
    connect,
    disconnect,
    sendData,
    clearLogs,
    clearError,
    error
  };
};

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { useSerial } from './hooks/useSerial';
import Terminal from './components/Terminal';
import { Learner } from './types';
import { supabase } from './lib/supabase';

interface AttendanceRecord {
  learnerId: string;
  type: 'IN' | 'OUT';
  timestamp: string;
}

const App: React.FC = () => {
  const { status, logs, connect, disconnect, clearError, error } = useSerial();
  const [baudRate, setBaudRate] = useState(9600);

  // App Modes
  const [isStandbyMode, setIsStandbyMode] = useState(false);

  // Database State
  const [learners, setLearners] = useState<Learner[]>([]);
  const [loading, setLoading] = useState(true);
  const [dbError, setDbError] = useState<string | null>(null);
  const [fetchedCount, setFetchedCount] = useState(0);

  // Registration State
  const [selectedLearnerId, setSelectedLearnerId] = useState<string | null>(null);
  const [activeRfid, setActiveRfid] = useState<string>('');
  const [searchQuery, setSearchQuery] = useState('');

  // Attendance Display State
  const [lastScanResult, setLastScanResult] = useState<{
    learner: Learner;
    type: 'IN' | 'OUT';
    time: string;
  } | null>(null);
  const [unknownTag, setUnknownTag] = useState<string | null>(null);

  // Local Mappings & Attendance Logs
  const [uidMappings, setUidMappings] = useState<Record<string, string>>(() => {
    const saved = localStorage.getItem('rfid_mappings');
    return saved ? JSON.parse(saved) : {};
  });

  const [attendanceLogs, setAttendanceLogs] = useState<AttendanceRecord[]>(() => {
    const saved = localStorage.getItem('attendance_logs');
    return saved ? JSON.parse(saved) : [];
  });

  // Fetch all learners from Supabase
  const fetchLearners = useCallback(async () => {
    try {
      setLoading(true);
      setDbError(null);
      let allData: Learner[] = [];
      let from = 0;
      const step = 1000;
      let hasMore = true;

      while (hasMore) {
        const { data, error: fetchErr } = await supabase
          .from('learners')
          .select('*')
          .range(from, from + step - 1);

        if (fetchErr) throw fetchErr;

        if (data && data.length > 0) {
          allData = [...allData, ...data];
          setFetchedCount(allData.length);
          if (data.length < step) {
            hasMore = false;
          } else {
            from += step;
          }
        } else {
          hasMore = false;
        }
      }
      setLearners(allData);
    } catch (err: any) {
      setDbError(err.message || 'Failed to fetch learners from database.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchLearners();
  }, [fetchLearners]);

  // Persist local data
  useEffect(() => {
    localStorage.setItem('rfid_mappings', JSON.stringify(uidMappings));
  }, [uidMappings]);

  useEffect(() => {
    localStorage.setItem('attendance_logs', JSON.stringify(attendanceLogs));
  }, [attendanceLogs]);

  // Auto-clear standby notifications
  useEffect(() => {
    if (lastScanResult || unknownTag) {
      const timer = setTimeout(() => {
        setLastScanResult(null);
        setUnknownTag(null);
      }, 5000);
      return () => clearTimeout(timer);
    }
  }, [lastScanResult, unknownTag]);

  // Handle Incoming Serial Data
  useEffect(() => {
    const lastLog = logs[logs.length - 1];
    if (lastLog && lastLog.type === 'in') {
      const scannedUid = lastLog.text.trim();
      if (scannedUid.length < 4) return;

      if (isStandbyMode) {
        // Attendance Mode Logic
        const learnerId = Object.keys(uidMappings).find(key => uidMappings[key] === scannedUid);
        const learner = learners.find(l => l.id === learnerId);

        if (learner) {
          // Determine In/Out
          const studentLogs = attendanceLogs.filter(log => log.learnerId === learner.id);
          const lastRecord = studentLogs[studentLogs.length - 1];
          const nextType = lastRecord?.type === 'IN' ? 'OUT' : 'IN';

          const newRecord: AttendanceRecord = {
            learnerId: learner.id,
            type: nextType,
            timestamp: new Date().toISOString()
          };

          setAttendanceLogs(prev => [...prev, newRecord]);
          setLastScanResult({
            learner,
            type: nextType,
            time: new Date().toLocaleTimeString()
          });
          setUnknownTag(null);
        } else {
          setUnknownTag(scannedUid);
          setLastScanResult(null);
        }
      } else {
        // Registration Mode Logic
        setActiveRfid(scannedUid);
      }
    }
  }, [logs, isStandbyMode, uidMappings, learners, attendanceLogs]);

  const handleLink = () => {
    if (!selectedLearnerId || !activeRfid) return;
    setUidMappings(prev => ({ ...prev, [selectedLearnerId]: activeRfid }));
    setActiveRfid('');
    setSelectedLearnerId(null);
  };

  const filteredLearners = useMemo(() => {
    const query = searchQuery.toLowerCase();
    return learners.filter(l => {
      const fullName = `${l.firstName} ${l.lastName}`.toLowerCase();
      const rfid = uidMappings[l.id]?.toLowerCase() || '';
      return fullName.includes(query) || l.lrn?.includes(query) || rfid.includes(query);
    });
  }, [learners, searchQuery, uidMappings]);

  // Render Standby Mode UI
  if (isStandbyMode) {
    return (
      <div className="fixed inset-0 bg-[#020617] text-white flex flex-col items-center justify-center p-10 z-[100]">
        <button 
          onClick={() => setIsStandbyMode(false)}
          className="absolute top-10 left-10 bg-slate-900 border border-slate-800 text-slate-400 px-6 py-3 rounded-2xl font-black text-xs tracking-widest hover:text-white transition-colors"
        >
          ← EXIT KIOSK
        </button>

        <div className="w-full max-w-4xl text-center">
          {!lastScanResult && !unknownTag ? (
            <div className="space-y-12 animate-in fade-in zoom-in duration-500">
              <div className="w-48 h-48 bg-indigo-600/20 rounded-[48px] border-2 border-indigo-500/30 flex items-center justify-center mx-auto shadow-[0_0_80px_rgba(79,70,229,0.2)]">
                <svg className="w-24 h-24 text-indigo-500 animate-pulse" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M12 12h4.01M16 20h4M4 12h4m12 0h.01M5 8h2a1 1 0 001-1V5a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1zm12 0h2a1 1 0 001-1V5a1 1 0 00-1-1h-2a1 1 0 00-1 1v2a1 1 0 001 1zM5 17h2a1 1 0 001-1v-2a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1z" /></svg>
              </div>
              <div className="space-y-4">
                <h2 className="text-6xl font-black tracking-tighter uppercase italic">Ready to Scan</h2>
                <p className="text-xl font-bold text-slate-500 tracking-[0.3em] uppercase">Please tap your Student ID Card</p>
              </div>
            </div>
          ) : lastScanResult ? (
            <div className="space-y-8 animate-in slide-in-from-bottom-10 duration-500">
              <div className={`text-[120px] font-black leading-none tracking-tighter uppercase italic ${lastScanResult.type === 'IN' ? 'text-emerald-400' : 'text-amber-400'}`}>
                Time {lastScanResult.type}
              </div>
              <div className="space-y-2">
                <h3 className="text-4xl font-black text-white">{lastScanResult.learner.firstName} {lastScanResult.learner.lastName}</h3>
                <p className="text-xl font-bold text-slate-500 uppercase tracking-widest">Recorded at {lastScanResult.time}</p>
              </div>
              <div className={`inline-block px-10 py-4 rounded-[32px] border-4 font-black text-2xl tracking-widest ${lastScanResult.type === 'IN' ? 'border-emerald-500/30 bg-emerald-500/10 text-emerald-400' : 'border-amber-500/30 bg-amber-500/10 text-amber-400'}`}>
                SUCCESSFUL
              </div>
            </div>
          ) : (
            <div className="space-y-8 animate-in shake duration-500">
              <div className="text-[120px] font-black leading-none tracking-tighter uppercase italic text-rose-500">
                Unknown
              </div>
              <div className="space-y-2">
                <h3 className="text-4xl font-black text-white">Tag ID: {unknownTag}</h3>
                <p className="text-xl font-bold text-slate-500 uppercase tracking-widest">Card not registered in system</p>
              </div>
              <div className="inline-block px-10 py-4 rounded-[32px] border-4 border-rose-500/30 bg-rose-500/10 text-rose-500 font-black text-2xl tracking-widest">
                ACCESS DENIED
              </div>
            </div>
          )}
        </div>

        <div className="absolute bottom-10 flex gap-10 text-[10px] font-black text-slate-600 tracking-[0.4em] uppercase">
          <span>Reader: {status}</span>
          <span>•</span>
          <span>Database: {learners.length} Students</span>
        </div>
      </div>
    );
  }

  // Registration Mode UI
  return (
    <div className="min-h-screen bg-[#020617] text-slate-200 flex flex-col p-4 md:p-8">
      <header className="max-w-7xl mx-auto w-full flex flex-col md:flex-row justify-between items-center mb-10 gap-6">
        <div className="flex items-center gap-4">
          <div className="w-14 h-14 bg-indigo-600 rounded-[22px] flex items-center justify-center shadow-2xl rotate-3">
             <svg className="w-8 h-8 text-white -rotate-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
          </div>
          <div>
            <h1 className="text-3xl font-black text-white tracking-tighter uppercase italic leading-none">Registrar</h1>
            <div className="flex items-center gap-3 mt-1.5">
              <span className="text-indigo-400 text-[10px] font-black tracking-[0.2em] uppercase">System Console</span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <button 
            onClick={() => setIsStandbyMode(true)}
            className="px-6 py-2.5 bg-slate-900 border border-indigo-500/30 text-indigo-400 rounded-xl text-xs font-black tracking-widest hover:bg-indigo-600 hover:text-white transition-all shadow-xl shadow-indigo-600/10"
          >
            LAUNCH ATTENDANCE KIOSK
          </button>

          <div className="flex items-center gap-4 bg-slate-900/60 p-2 rounded-[22px] border border-slate-800">
            <select 
              value={baudRate}
              onChange={(e) => setBaudRate(Number(e.target.value))}
              className="bg-slate-950 text-xs font-bold border-none rounded-xl px-4 py-2 cursor-pointer"
            >
              <option value={9600}>9600 Baud</option>
              <option value={115200}>115200 Baud</option>
            </select>
            <button
              onClick={status === 'connected' ? disconnect : () => connect({ baudRate })}
              className={`px-6 py-2 rounded-xl text-xs font-black tracking-widest ${status === 'connected' ? 'bg-rose-500/10 text-rose-500 border border-rose-500/20' : 'bg-indigo-600 text-white shadow-lg'}`}
