      <main className="max-w-7xl mx-auto w-full grid grid-cols-1 lg:grid-cols-12 gap-8 mb-12">
        <div className="lg:col-span-4 space-y-6">
          <section className="bg-slate-900/40 rounded-[32px] border border-slate-800 p-8 shadow-2xl relative overflow-hidden">
            <h2 className="text-xs font-black text-indigo-400 mb-8 uppercase tracking-[0.3em]">Link Card</h2>
            <div className="space-y-8">
              <div className="space-y-3">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Active Scan</label>
                <div className={`p-6 rounded-2xl border-2 ${activeRfid ? 'bg-indigo-950/20 border-indigo-500/50' : 'bg-slate-950/50 border-slate-800'}`}>
                  {activeRfid ? <code className="text-2xl font-black text-white font-mono">{activeRfid}</code> : <p className="text-[11px] font-black text-slate-600 animate-pulse">WAITING FOR CARD...</p>}
                </div>
              </div>

              <div className="space-y-3">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Target Student</label>
                <div className={`p-6 rounded-2xl border-2 ${selectedLearnerId ? 'bg-indigo-950/20 border-indigo-500/30' : 'bg-slate-950/50 border-slate-800 border-dashed'}`}>
                  {selectedLearnerId ? (
                    <div className="flex items-center gap-4">
                      <div className="w-12 h-12 bg-indigo-500 rounded-xl flex items-center justify-center font-black">{learners.find(l => l.id === selectedLearnerId)?.firstName?.charAt(0)}</div>
                      <div>
                        <div className="font-black text-white text-sm">{learners.find(l => l.id === selectedLearnerId)?.firstName} {learners.find(l => l.id === selectedLearnerId)?.lastName}</div>
                        <div className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">LRN: {learners.find(l => l.id === selectedLearnerId)?.lrn}</div>
                      </div>
                    </div>
                  ) : <p className="text-[11px] font-black text-slate-600">CHOOSE FROM LIST</p>}
                </div>
              </div>

              <button
                disabled={!activeRfid || !selectedLearnerId}
                onClick={handleLink}
                className="w-full bg-indigo-600 hover:bg-indigo-500 disabled:opacity-20 text-white font-black py-5 rounded-[22px] shadow-2xl uppercase tracking-[0.3em] text-[11px] active:scale-95"
              >
                Link RFID to Student
              </button>
            </div>
          </section>

          <section className="bg-slate-900/40 rounded-[32px] border border-slate-800 p-6 overflow-hidden">
            <h2 className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-4">Live Serial Feed</h2>
            <div className="h-40 rounded-2xl overflow-hidden border border-slate-800 bg-black/40">
              <Terminal logs={logs.slice(-20)} />
            </div>
          </section>
        </div>

        <div className="lg:col-span-8 space-y-6">
          <div className="relative">
            <svg className="w-5 h-5 absolute left-5 top-1/2 -translate-y-1/2 text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
            <input
              type="text"
              placeholder="Search by Name, LRN or Card UID..."
              value={searchQuery}
              onChange={e => setSearchQuery(e.target.value)}
              className="w-full bg-slate-900 border border-slate-800 rounded-[28px] pl-14 pr-8 py-5 text-sm font-medium focus:border-indigo-500/50 outline-none transition-all shadow-xl"
            />
          </div>

          <div className="bg-slate-900/40 rounded-[40px] border border-slate-800 overflow-hidden shadow-2xl backdrop-blur-md">
            {loading && fetchedCount === 0 ? (
              <div className="p-32 text-center text-xs font-black text-slate-500 tracking-[0.3em] uppercase animate-pulse">Synchronizing Data...</div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                  <thead>
                    <tr className="bg-slate-950/40 border-b border-slate-800">
                      <th className="p-6 text-[10px] font-black text-slate-500 uppercase tracking-widest">Student Information</th>
                      <th className="p-6 text-[10px] font-black text-slate-500 uppercase tracking-widest text-center">RFID Tag</th>
                      <th className="p-6 text-[10px] font-black text-slate-500 uppercase tracking-widest text-right">Action</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-800/50">
                    {filteredLearners.map(learner => {
                      const isLinked = !!uidMappings[learner.id];
                      const isSelected = selectedLearnerId === learner.id;
                      return (
                        <tr key={learner.id} className={`transition-all ${isSelected ? 'bg-indigo-600/10' : 'hover:bg-slate-800/20'}`}>
                          <td className="p-6">
                            <div className="text-[15px] font-black text-white">{learner.lastName}, {learner.firstName}</div>
                            <div className="text-[10px] font-bold text-slate-500 mt-1">LRN: {learner.lrn}</div>
                          </td>
                          <td className="p-6 text-center">
                            {isLinked ? (
                              <span className="inline-flex items-center px-4 py-1.5 rounded-full bg-emerald-500/10 text-emerald-400 text-[10px] font-black border border-emerald-500/20">
                                UID: {uidMappings[learner.id]}
                              </span>
                            ) : (
                              <span className="text-slate-700 text-[10px] font-black uppercase">No Card Linked</span>
                            )}
                          </td>
                          <td className="p-6 text-right">
                            <button onClick={() => setSelectedLearnerId(isSelected ? null : learner.id)} className={`px-6 py-2 rounded-2xl text-[10px] font-black transition-all ${isSelected ? 'bg-indigo-500 text-white shadow-xl shadow-indigo-500/30' : 'bg-slate-800 text-slate-400 hover:text-white'}`}>
                              {isSelected ? 'SELECTED' : 'SELECT'}
                            </button>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      </main>

      <footer className="max-w-7xl mx-auto w-full mt-auto pt-8 border-t border-slate-900/50 flex justify-between items-center text-[10px] font-black text-slate-700 uppercase tracking-[0.3em]">
        <div className="flex gap-10">
          <span>ACTIVE CARDS: {Object.keys(uidMappings).length}</span>
          <span>TOTAL STUDENTS: {learners.length}</span>
        </div>
        <span>SYSTEM_READY</span>
      </footer>
    </div>
  );
};

