import { useState, useCallback, useRef, useEffect } from 'react';
import { SerialLog, ConnectionStatus, SerialOptions, SerialPort } from '../types';

export const useSerial = () => {
  const [status, setStatus] = useState<ConnectionStatus>('disconnected');
  const [logs, setLogs] = useState<SerialLog[]>([]);
  const [port, setPort] = useState<SerialPort | null>(null);
  const [error, setError] = useState<string | null>(null);

  const readerRef = useRef<ReadableStreamDefaultReader<string> | null>(null);
  const writerRef = useRef<WritableStreamDefaultWriter<string> | null>(null);
  const portRef = useRef<any>(null);

  const addLog = useCallback((text: string, type: SerialLog['type']) => {
    const newLog: SerialLog = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date(),
      type,
      text
    };
    setLogs(prev => [...prev.slice(-999), newLog]);
  }, []);

  const disconnect = useCallback(async () => {
    setStatus('disconnected');

    try {
      if (readerRef.current) {
        await readerRef.current.cancel();
        readerRef.current = null;
      }
      if (writerRef.current) {
        await writerRef.current.close();
        writerRef.current = null;
      }
      if (portRef.current) {
        await portRef.current.close();
        portRef.current = null;
      }
    } catch (e) {
      console.error("Cleanup error:", e);
    }

    setPort(null);
    addLog('Disconnected from port.', 'info');
  }, [addLog]);

  useEffect(() => {
    return () => {
      if (status === 'connected') {
        disconnect();
      }
    };
  }, [status, disconnect]);

  const connect = useCallback(async (options: SerialOptions) => {
    if (!('serial' in navigator)) {
      setError('Web Serial API is not supported in this browser.');
      return;
    }

    try {
      setError(null);
      setStatus('connecting');

      const selectedPort = await (navigator as any).serial.requestPort();

      try {
        await selectedPort.open({ baudRate: options.baudRate });
      } catch (openErr: any) {
        if (openErr.name === 'NetworkError' || openErr.message.includes('busy')) {
          throw new Error('Serial Port is BUSY. Please close Arduino IDE Serial Monitor or other apps.');
        }
        throw openErr;
      }

      portRef.current = selectedPort;
      setPort(selectedPort);
      setStatus('connected');
      addLog(`Connected at ${options.baudRate} baud.`, 'info');

      const textDecoder = new TextDecoderStream();
      selectedPort.readable.pipeTo(textDecoder.writable);
      const reader = textDecoder.readable.getReader();
      readerRef.current = reader;

      const textEncoder = new TextEncoderStream();
      textEncoder.readable.pipeTo(selectedPort.writable);
      const writer = textEncoder.writable.getWriter();
      writerRef.current = writer;

      // Line-buffered reading loop
      (async () => {
        let buffer = '';
        try {
          while (true) {
            const { value, done } = await reader.read();
            if (done) break;

            buffer += value;
            // Split by lines and handle fragments
            const lines = buffer.split(/\r?\n/);
            buffer = lines.pop() || ''; 

            for (const line of lines) {
              const trimmed = line.trim();
              if (trimmed) {
                addLog(trimmed, 'in');
              }
            }
          }
        } catch (err: any) {
          if (status === 'connected') {
            console.error('Read error:', err);
            addLog(`Read error: ${err.message}`, 'error');
            setStatus('error');
          }
        } finally {
          reader.releaseLock();
        }
      })();

    } catch (err: any) {
      console.error('Connection failed:', err);
      const msg = err.message || 'Failed to connect to the serial port.';
      setError(msg);
      setStatus('disconnected');
      addLog(`Connection failed: ${msg}`, 'error');
    }
  }, [addLog, status]);

  const sendData = useCallback(async (data: string) => {
    if (!writerRef.current) return;
    try {
      await writerRef.current.write(data);
      addLog(data, 'out');
    } catch (err: any) {
      addLog(`Write error: ${err.message}`, 'error');
    }
  }, [addLog]);

  const clearLogs = useCallback(() => setLogs([]), []);
  const clearError = useCallback(() => setError(null), []);

  return {
    status,
    logs,
    connect,
    disconnect,
    sendData,
    clearLogs,
    clearError,
    error
  };
};

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { useSerial } from './hooks/useSerial';
import Terminal from './components/Terminal';
import { Learner } from './types';
import { supabase } from './lib/supabase';

interface AttendanceRecord {
  learnerId: string;
  type: 'IN' | 'OUT';
  timestamp: string;
}

const App: React.FC = () => {
  const { status, logs, connect, disconnect, clearError, error } = useSerial();
  const [baudRate, setBaudRate] = useState(9600);
  const [isStandbyMode, setIsStandbyMode] = useState(false);

  // Database & UI State
  const [learners, setLearners] = useState<Learner[]>([]);
  const [loading, setLoading] = useState(true);
  const [dbError, setDbError] = useState<string | null>(null);
  const [fetchedCount, setFetchedCount] = useState(0);

  // Registration State
  const [selectedLearnerId, setSelectedLearnerId] = useState<string | null>(null);
  const [activeRfid, setActiveRfid] = useState<string>('');
  const [searchQuery, setSearchQuery] = useState('');

  // Kiosk Attendance Display
  const [lastScanResult, setLastScanResult] = useState<{
    learner: Learner;
    type: 'IN' | 'OUT';
    time: string;
    date: string;
  } | null>(null);
  const [unknownTag, setUnknownTag] = useState<string | null>(null);

  // Persistent Storage
  const [uidMappings, setUidMappings] = useState<Record<string, string>>(() => {
    const saved = localStorage.getItem('rfid_mappings');
    return saved ? JSON.parse(saved) : {};
  });

  const [attendanceLogs, setAttendanceLogs] = useState<AttendanceRecord[]>(() => {
    const saved = localStorage.getItem('attendance_logs');
    return saved ? JSON.parse(saved) : [];
  });

  // Data Fetching
  const fetchLearners = useCallback(async () => {
    try {
      setLoading(true);
      setDbError(null);
      let allData: Learner[] = [];
      let from = 0;
      const step = 1000;
      let hasMore = true;

      while (hasMore) {
        const { data, error: fetchErr } = await supabase
          .from('learners')
          .select('*')
          .range(from, from + step - 1);

        if (fetchErr) throw fetchErr;

        if (data && data.length > 0) {
          allData = [...allData, ...data];
          setFetchedCount(allData.length);
          hasMore = data.length === step;
          from += step;
        } else {
          hasMore = false;
        }
      }
      setLearners(allData);
    } catch (err: any) {
      setDbError(err.message || 'Database error occurred.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { fetchLearners(); }, [fetchLearners]);

  useEffect(() => {
    localStorage.setItem('rfid_mappings', JSON.stringify(uidMappings));
  }, [uidMappings]);

  useEffect(() => {
    localStorage.setItem('attendance_logs', JSON.stringify(attendanceLogs));
  }, [attendanceLogs]);

  // Kiosk Auto-Reset Timer (5s)
  useEffect(() => {
    if (lastScanResult || unknownTag) {
      const timer = setTimeout(() => {
        setLastScanResult(null);
        setUnknownTag(null);
      }, 5000);
      return () => clearTimeout(timer);
    }
  }, [lastScanResult, unknownTag]);

  // Serial Monitor Observer
  useEffect(() => {
    const lastLog = logs[logs.length - 1];
    if (lastLog && lastLog.type === 'in') {
      const scannedUid = lastLog.text.trim().toUpperCase();
      if (scannedUid.length < 4) return;

      if (isStandbyMode) {
        // Attendance Logic
        const learnerId = Object.keys(uidMappings).find(
          id => uidMappings[id].toUpperCase() === scannedUid
        );
        const learner = learners.find(l => l.id === learnerId);

        if (learner) {
          const studentHistory = attendanceLogs.filter(log => log.learnerId === learner.id);
          const lastRecord = studentHistory[studentHistory.length - 1];
          const nextType = lastRecord?.type === 'IN' ? 'OUT' : 'IN';

          const newRecord: AttendanceRecord = {
            learnerId: learner.id,
            type: nextType,
            timestamp: new Date().toISOString()
          };

          setAttendanceLogs(prev => [...prev, newRecord]);
          setLastScanResult({
            learner,
            type: nextType,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
            date: new Date().toLocaleDateString(undefined, { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })
          });
          setUnknownTag(null);
        } else {
          setUnknownTag(scannedUid);
          setLastScanResult(null);
        }
      } else {
        // Registration Mode Logic
        setActiveRfid(scannedUid);
      }
    }
  }, [logs, isStandbyMode, uidMappings, learners, attendanceLogs]);

  const handleLink = () => {
    if (!selectedLearnerId || !activeRfid) return;
    setUidMappings(prev => ({ ...prev, [selectedLearnerId]: activeRfid }));
    setActiveRfid('');
    setSelectedLearnerId(null);
  };

  const filteredLearners = useMemo(() => {
    const query = searchQuery.toLowerCase();
    return learners.filter(l => {
      const fullName = `${l.firstName} ${l.lastName}`.toLowerCase();
      const rfid = uidMappings[l.id]?.toLowerCase() || '';
      return fullName.includes(query) || l.lrn?.includes(query) || rfid.includes(query);
    });
  }, [learners, searchQuery, uidMappings]);

  // STANDBY KIOSK MODE
  if (isStandbyMode) {
    return (
      <div className="fixed inset-0 bg-[#020617] text-white flex flex-col items-center justify-center p-12 z-[100] transition-colors duration-1000 overflow-hidden">
        {/* Animated Background Orbs */}
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-indigo-500/10 blur-[120px] rounded-full animate-pulse" />
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-blue-500/5 blur-[120px] rounded-full animate-pulse" />

        <button 
          onClick={() => setIsStandbyMode(false)}
          className="absolute top-12 left-12 group flex items-center gap-3 bg-slate-900/50 border border-slate-800 text-slate-500 px-8 py-4 rounded-3xl font-black text-xs tracking-[0.3em] hover:text-white hover:border-indigo-500/50 transition-all backdrop-blur-xl"
        >
          <svg className="w-5 h-5 group-hover:-translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
          EXIT KIOSK
        </button>

        <div className="w-full max-w-5xl text-center relative z-10">
          {!lastScanResult && !unknownTag ? (
            <div className="space-y-16 animate-in fade-in zoom-in duration-700">
              <div className="relative mx-auto w-64 h-64">
                <div className="absolute inset-0 bg-indigo-600/20 rounded-[64px] animate-ping" />
                <div className="relative w-full h-full bg-slate-900 border-2 border-indigo-500/30 rounded-[64px] flex items-center justify-center shadow-[0_0_100px_rgba(79,70,229,0.15)]">
                  <svg className="w-32 h-32 text-indigo-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M12 12h4.01M16 20h4M4 12h4m12 0h.01M5 8h2a1 1 0 001-1V5a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1zm12 0h2a1 1 0 001-1V5a1 1 0 00-1-1h-2a1 1 0 00-1 1v2a1 1 0 001 1zM5 17h2a1 1 0 001-1v-2a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1z" /></svg>
                </div>
              </div>
              <div className="space-y-6">
                <h2 className="text-8xl font-black tracking-tighter uppercase italic leading-none">Scanning Standby</h2>
                <p className="text-2xl font-bold text-slate-500 tracking-[0.4em] uppercase opacity-70">Tap Student ID Card to Log Attendance</p>
              </div>
            </div>
          ) : lastScanResult ? (
            <div className="space-y-10 animate-in slide-in-from-bottom-20 duration-500">
              <div className={`text-[160px] font-black leading-none tracking-tighter uppercase italic drop-shadow-2xl ${lastScanResult.type === 'IN' ? 'text-emerald-400' : 'text-amber-400'}`}>
                {lastScanResult.type === 'IN' ? 'Time In' : 'Time Out'}
              </div>
              <div className="space-y-4">
                <h3 className="text-6xl font-black text-white tracking-tight">{lastScanResult.learner.firstName} {lastScanResult.learner.lastName}</h3>
                <div className="flex flex-col gap-2">
                  <p className="text-3xl font-bold text-indigo-400/80 uppercase tracking-[0.2em]">{lastScanResult.time}</p>
                  <p className="text-xl font-bold text-slate-500 uppercase tracking-widest">{lastScanResult.date}</p>
                </div>
              </div>
              <div className={`mt-10 inline-flex items-center gap-4 px-12 py-6 rounded-[40px] border-4 font-black text-3xl tracking-[0.3em] ${lastScanResult.type === 'IN' ? 'border-emerald-500/20 bg-emerald-500/5 text-emerald-400' : 'border-amber-500/20 bg-amber-500/5 text-amber-400'}`}>
                <span className="w-4 h-4 rounded-full bg-current animate-pulse" />
                VERIFIED
              </div>
            </div>
          ) : (
            <div className="space-y-10 animate-in shake duration-500">
               <div className="text-[140px] font-black leading-none tracking-tighter uppercase italic text-rose-500 drop-shadow-2xl">
                Unknown
              </div>
              <div className="space-y-4">
                <h3 className="text-5xl font-black text-white">UID: {unknownTag}</h3>
                <p className="text-2xl font-bold text-slate-500 uppercase tracking-widest">Tag is not registered in the directory</p>
              </div>
              <div className="inline-flex items-center gap-4 px-12 py-6 rounded-[40px] border-4 border-rose-500/20 bg-rose-500/5 text-rose-500 font-black text-3xl tracking-[0.3em]">
                <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                ACCESS DENIED
              </div>
            </div>
          )}
        </div>

        <div className="absolute bottom-12 flex gap-12 text-[12px] font-black text-slate-700 tracking-[0.5em] uppercase">
          <div className="flex items-center gap-3">
            <span className={`w-2 h-2 rounded-full ${status === 'connected' ? 'bg-emerald-500' : 'bg-rose-500'}`} />
            READER: {status}
          </div>
          <span>•</span>
          <div className="flex items-center gap-3">
            <span className="w-2 h-2 rounded-full bg-indigo-500" />
            RECORDS: {learners.length} STUDENTS
          </div>
        </div>
      </div>
    );
  }

  // REGISTRATION MODE UI
  return (
    <div className="min-h-screen bg-[#020617] text-slate-200 flex flex-col p-6 md:p-10">
      <header className="max-w-7xl mx-auto w-full flex flex-col md:flex-row justify-between items-center mb-12 gap-8">
        <div className="flex items-center gap-6">
          <div className="w-16 h-16 bg-indigo-600 rounded-[28px] flex items-center justify-center shadow-2xl shadow-indigo-600/20 rotate-3 transform hover:rotate-0 transition-transform cursor-pointer">
             <svg className="w-10 h-10 text-white -rotate-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
          </div>
          <div>
            <h1 className="text-4xl font-black text-white tracking-tighter uppercase italic leading-none">Registrar</h1>
            <div className="flex items-center gap-4 mt-2">
              <span className="flex items-center gap-2 text-indigo-400 text-[11px] font-black tracking-[0.3em] uppercase">
                <span className="w-2 h-2 bg-indigo-500 rounded-full animate-pulse" />
                Live Control Console
              </span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <button 
            onClick={() => setIsStandbyMode(true)}
            className="group px-8 py-4 bg-slate-900 border border-indigo-500/30 text-indigo-400 rounded-2xl text-[11px] font-black tracking-[0.2em] hover:bg-indigo-600 hover:text-white transition-all shadow-2xl flex items-center gap-3"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>
            LAUNCH KIOSK
          </button>

          <div className="flex items-center gap-4 bg-slate-900/60 p-3 rounded-3xl border border-slate-800 shadow-xl">
            <select 
              value={baudRate}
              onChange={(e) => setBaudRate(Number(e.target.value))}
              className="bg-slate-950 text-xs font-bold border-none rounded-xl px-4 py-2 cursor-pointer outline-none hover:bg-slate-900 transition-colors"
            >
              <option value={9600}>9600 Baud</option>
              <option value={115200}>115200 Baud</option>
            </select>
            <button
              onClick={status === 'connected' ? disconnect : () => connect({ baudRate })}
              className={`px-8 py-2.5 rounded-xl text-[11px] font-black tracking-widest transition-all ${status === 'connected' ? 'bg-rose-500/10 text-rose-500 border border-rose-500/20' : 'bg-indigo-600 text-white shadow-xl shadow-indigo-600/30'}`}
            >
              {status === 'connected' ? 'TERMINATE' : 'INITIATE'}
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto w-full grid grid-cols-1 lg:grid-cols-12 gap-10 mb-12">
        <div className="lg:col-span-4 space-y-8">
          <section className="bg-slate-900/40 rounded-[40px] border border-slate-800 p-10 shadow-2xl relative overflow-hidden backdrop-blur-xl">
            <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-500/5 blur-[50px] rounded-full" />
            <h2 className="text-xs font-black text-indigo-400 mb-10 uppercase tracking-[0.4em] flex items-center gap-3">
              <span className="w-1 h-5 bg-indigo-500 rounded-full" />
              Establish Link
            </h2>
            <div className="space-y-10">
              <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] ml-1">Active UID Capture</label>
                <div className={`p-8 rounded-3xl border-2 transition-all duration-500 ${activeRfid ? 'bg-indigo-950/20 border-indigo-500/50 shadow-[inset_0_0_20px_rgba(99,102,241,0.1)]' : 'bg-slate-950/50 border-slate-800'}`}>
                  {activeRfid ? (
                    <div className="flex flex-col">
                      <span className="text-[10px] font-black text-indigo-400 mb-1 tracking-widest uppercase">ID DETECTED</span>
                      <code className="text-3xl font-black text-white font-mono tracking-tighter">{activeRfid}</code>
                    </div>
                  ) : (
                    <div className="text-center py-2">
                      <p className="text-[11px] font-black text-slate-600 tracking-[0.2em] animate-pulse">WAITING FOR CARD...</p>
                    </div>
                  )}
                </div>
              </div>

              <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] ml-1">Assigned Target</label>
                <div className={`p-8 rounded-3xl border-2 transition-all duration-500 ${selectedLearnerId ? 'bg-indigo-950/20 border-indigo-500/30' : 'bg-slate-950/50 border-slate-800 border-dashed'}`}>
                  {selectedLearnerId ? (
                    <div className="flex items-center gap-5">
                      <div className="w-14 h-14 bg-indigo-500 rounded-2xl flex items-center justify-center font-black text-xl text-white shadow-xl shadow-indigo-500/20">
                        {learners.find(l => l.id === selectedLearnerId)?.lastName?.charAt(0)}
                      </div>
                      <div>
                        <div className="font-black text-white text-lg leading-none">{learners.find(l => l.id === selectedLearnerId)?.firstName} {learners.find(l => l.id === selectedLearnerId)?.lastName}</div>
                        <div className="text-[10px] text-slate-500 font-bold uppercase tracking-[0.2em] mt-2">LRN: {learners.find(l => l.id === selectedLearnerId)?.lrn}</div>
                      </div>
                    </div>
                  ) : <p className="text-[11px] font-black text-slate-600 text-center py-2 tracking-widest">SELECT FROM DIRECTORY</p>}
                </div>
              </div>

              <button
                disabled={!activeRfid || !selectedLearnerId}
                onClick={handleLink}
                className="w-full bg-indigo-600 hover:bg-indigo-500 disabled:opacity-10 text-white font-black py-6 rounded-[32px] shadow-2xl shadow-indigo-600/20 uppercase tracking-[0.4em] text-[11px] active:scale-95 transition-all"
              >
                PAIR DEVICE & SAVE
              </button>
            </div>
          </section>

          <section className="bg-slate-900/40 rounded-[40px] border border-slate-800 p-8 overflow-hidden backdrop-blur-md">
            <h2 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] mb-6">Serial Debug</h2>
            <div className="h-44 rounded-3xl overflow-hidden border border-slate-800 bg-black/40 shadow-inner">
              <Terminal logs={logs.slice(-30)} />
            </div>
          </section>
        </div>

        <div className="lg:col-span-8 space-y-8">
          <div className="relative group">
            <div className="absolute inset-0 bg-indigo-500/5 blur-3xl rounded-full transition-opacity opacity-0 group-hover:opacity-100" />
            <svg className="w-6 h-6 absolute left-6 top-1/2 -translate-y-1/2 text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
            <input
              type="text"
              placeholder="Filter by Student Name, LRN, or Card UID..."
              value={searchQuery}
              onChange={e => setSearchQuery(e.target.value)}
              className="w-full bg-slate-900 border border-slate-800 rounded-[36px] pl-16 pr-10 py-6 text-[15px] font-medium focus:border-indigo-500/50 outline-none transition-all shadow-2xl placeholder:text-slate-700"
            />
          </div>

          <div className="bg-slate-900/40 rounded-[48px] border border-slate-800 overflow-hidden shadow-2xl backdrop-blur-xl">
            {loading && fetchedCount === 0 ? (
              <div className="p-40 text-center flex flex-col items-center gap-6">
                <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin" />
                <p className="text-[11px] font-black text-slate-600 tracking-[0.4em] uppercase">Fetching Directory...</p>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                  <thead>
                    <tr className="bg-slate-950/40 border-b border-slate-800">
                      <th className="p-8 text-[11px] font-black text-slate-500 uppercase tracking-[0.3em]">Student Profile</th>
                      <th className="p-8 text-[11px] font-black text-slate-500 uppercase tracking-[0.3em] text-center">RFID Assignment</th>
                      <th className="p-8 text-[11px] font-black text-slate-500 uppercase tracking-[0.3em] text-right">Selection</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-800/50">
                    {filteredLearners.map(learner => {
                      const isLinked = !!uidMappings[learner.id];
                      const isSelected = selectedLearnerId === learner.id;
                      return (
                        <tr key={learner.id} className={`transition-all duration-300 ${isSelected ? 'bg-indigo-600/10' : 'hover:bg-slate-800/30'}`}>
                          <td className="p-8">
                            <div className="flex items-center gap-6">
                              <div className={`w-14 h-14 rounded-2xl flex items-center justify-center font-black text-lg border transition-all ${isLinked ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' : 'bg-slate-800/50 text-slate-500 border-slate-700'}`}>
                                {learner.lastName?.charAt(0)}
                              </div>
                              <div>
                                <div className="text-[16px] font-black text-white tracking-tight">{learner.lastName}, {learner.firstName}</div>
                                <div className="text-[10px] font-bold text-slate-500 mt-2 uppercase tracking-widest">LRN: {learner.lrn}</div>
                              </div>
                            </div>
                          </td>
                          <td className="p-8 text-center">
                            {isLinked ? (
                              <div className="inline-flex flex-col gap-1">
                                <span className="px-5 py-2 rounded-full bg-emerald-500/10 text-emerald-400 text-[11px] font-black border border-emerald-500/20 shadow-sm">
                                  {uidMappings[learner.id]}
                                </span>
                              </div>
                            ) : (
                              <span className="text-slate-800 text-[11px] font-black uppercase tracking-widest">UNREGISTERED</span>
                            )}
                          </td>
                          <td className="p-8 text-right">
                            <button 
                              onClick={() => setSelectedLearnerId(isSelected ? null : learner.id)} 
                              className={`px-8 py-3 rounded-2xl text-[11px] font-black transition-all transform active:scale-90 tracking-[0.1em] ${
                                isSelected 
                                ? 'bg-indigo-500 text-white shadow-xl shadow-indigo-500/30' 
                                : 'bg-slate-800/80 text-slate-400 hover:text-white hover:bg-slate-700'
                              }`}
                            >
                              {isSelected ? 'SELECTED' : 'SELECT'}
                            </button>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      </main>

      <footer className="max-w-7xl mx-auto w-full mt-auto pt-10 border-t border-slate-900/50 flex flex-col md:flex-row justify-between items-center gap-6 text-[11px] font-black text-slate-700 uppercase tracking-[0.4em]">
        <div className="flex gap-12">
          <div className="flex items-center gap-3">
            <span className="text-slate-800">MAPPED_TAGS:</span>
            <span className="text-indigo-400/50">{Object.keys(uidMappings).length} CARDS</span>
          </div>
          <div className="flex items-center gap-3">
            <span className="text-slate-800">POOL:</span>
            <span className="text-indigo-400/50">{learners.length} LEARNERS</span>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <span className="w-2 h-2 bg-emerald-500/20 rounded-full" />
          SYSTEM_STATE: OPERATIONAL
        </div>
      </footer>

      {dbError && (
        <div className="fixed bottom-12 right-12 bg-rose-500 text-white p-6 rounded-3xl shadow-2xl flex items-center gap-4 z-[200] animate-in slide-in-from-right-10">
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
          <span className="text-xs font-black uppercase tracking-widest">{dbError}</span>
          <button onClick={() => setDbError(null)} className="p-2 hover:bg-white/10 rounded-lg">×</button>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { useSerial } from './hooks/useSerial';
import Terminal from './components/Terminal';
import { Learner } from './types';
import { supabase } from './lib/supabase';

interface AttendanceRecord {
  learnerId: string;
  type: 'IN' | 'OUT';
  timestamp: string;
}

const App: React.FC = () => {
  const { status, logs, connect, disconnect, clearError, error } = useSerial();
  const [baudRate, setBaudRate] = useState(9600);
  const [isStandbyMode, setIsStandbyMode] = useState(false);

  // Database & UI State
  const [learners, setLearners] = useState<Learner[]>([]);
  const [loading, setLoading] = useState(true);
  const [dbError, setDbError] = useState<string | null>(null);
  const [conflictWarning, setConflictWarning] = useState<string | null>(null);
  const [fetchedCount, setFetchedCount] = useState(0);

  // Registration State
  const [selectedLearnerId, setSelectedLearnerId] = useState<string | null>(null);
  const [activeRfid, setActiveRfid] = useState<string>('');
  const [searchQuery, setSearchQuery] = useState('');

  // Kiosk Attendance Display
  const [lastScanResult, setLastScanResult] = useState<{
    learner: Learner;
    type: 'IN' | 'OUT';
    time: string;
    date: string;
    uid: string;
  } | null>(null);
  const [unknownTag, setUnknownTag] = useState<string | null>(null);

  // Persistent Storage
  const [uidMappings, setUidMappings] = useState<Record<string, string>>(() => {
    const saved = localStorage.getItem('rfid_mappings');
    return saved ? JSON.parse(saved) : {};
  });

  const [attendanceLogs, setAttendanceLogs] = useState<AttendanceRecord[]>(() => {
    const saved = localStorage.getItem('attendance_logs');
    return saved ? JSON.parse(saved) : [];
  });

  // Data Fetching
  const fetchLearners = useCallback(async () => {
    try {
      setLoading(true);
      setDbError(null);
      let allData: Learner[] = [];
      let from = 0;
      const step = 1000;
      let hasMore = true;

      while (hasMore) {
        const { data, error: fetchErr } = await supabase
          .from('learners')
          .select('*')
          .range(from, from + step - 1);

        if (fetchErr) throw fetchErr;

        if (data && data.length > 0) {
          allData = [...allData, ...data];
          setFetchedCount(allData.length);
          hasMore = data.length === step;
          from += step;
        } else {
          hasMore = false;
        }
      }
      setLearners(allData);
    } catch (err: any) {
      setDbError(err.message || 'Database error occurred.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { fetchLearners(); }, [fetchLearners]);

  useEffect(() => {
    localStorage.setItem('rfid_mappings', JSON.stringify(uidMappings));
  }, [uidMappings]);

  useEffect(() => {
    localStorage.setItem('attendance_logs', JSON.stringify(attendanceLogs));
  }, [attendanceLogs]);

  // Kiosk Auto-Reset Timer (5s)
  useEffect(() => {
    if (lastScanResult || unknownTag) {
      const timer = setTimeout(() => {
        setLastScanResult(null);
        setUnknownTag(null);
      }, 5000);
      return () => clearTimeout(timer);
    }
  }, [lastScanResult, unknownTag]);

  // Serial Monitor Observer
  useEffect(() => {
    const lastLog = logs[logs.length - 1];
    if (lastLog && lastLog.type === 'in') {
      const scannedUid = lastLog.text.trim().toUpperCase();
      if (scannedUid.length < 4) return;

      if (isStandbyMode) {
        // Attendance Logic
        const learnerId = Object.keys(uidMappings).find(
          id => uidMappings[id].toUpperCase() === scannedUid
        );
        const learner = learners.find(l => l.id === learnerId);

        if (learner) {
          const studentHistory = attendanceLogs.filter(log => log.learnerId === learner.id);
          const lastRecord = studentHistory[studentHistory.length - 1];
          const nextType = lastRecord?.type === 'IN' ? 'OUT' : 'IN';

          const newRecord: AttendanceRecord = {
            learnerId: learner.id,
            type: nextType,
            timestamp: new Date().toISOString()
          };

          setAttendanceLogs(prev => [...prev, newRecord]);
          setLastScanResult({
            learner,
            type: nextType,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
            date: new Date().toLocaleDateString(undefined, { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }),
            uid: scannedUid
          });
          setUnknownTag(null);
        } else {
          setUnknownTag(scannedUid);
          setLastScanResult(null);
        }
      } else {
        // Registration Mode Logic
        setActiveRfid(scannedUid);
        setConflictWarning(null); // Reset warning on new scan
      }
    }
  }, [logs, isStandbyMode, uidMappings, learners, attendanceLogs]);

  const handleLink = () => {
    if (!selectedLearnerId || !activeRfid) return;

    // Duplicate Check: See if this RFID is already linked to another student
    const existingOwnerId = Object.keys(uidMappings).find(
      id => uidMappings[id].toUpperCase() === activeRfid.toUpperCase()
    );

    if (existingOwnerId && existingOwnerId !== selectedLearnerId) {
      const owner = learners.find(l => l.id === existingOwnerId);
      setConflictWarning(`CONFLICT: This card is already assigned to ${owner ? owner.firstName + ' ' + owner.lastName : 'another student'}.`);
      return;
    }

    setUidMappings(prev => ({ ...prev, [selectedLearnerId]: activeRfid }));
    setActiveRfid('');
    setSelectedLearnerId(null);
    setConflictWarning(null);
  };

  const filteredLearners = useMemo(() => {
    const query = searchQuery.toLowerCase();
    return learners.filter(l => {
      const fullName = `${l.firstName} ${l.lastName}`.toLowerCase();
      const rfid = uidMappings[l.id]?.toLowerCase() || '';
      return fullName.includes(query) || l.lrn?.includes(query) || rfid.includes(query);
    });
  }, [learners, searchQuery, uidMappings]);

  // STANDBY KIOSK MODE
  if (isStandbyMode) {
    return (
      <div className="fixed inset-0 bg-[#020617] text-white flex flex-col items-center justify-center p-12 z-[100] transition-colors duration-1000 overflow-hidden">
        {/* Animated Background Orbs */}
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-indigo-500/10 blur-[120px] rounded-full animate-pulse" />
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-blue-500/5 blur-[120px] rounded-full animate-pulse" />

        <button 
          onClick={() => setIsStandbyMode(false)}
          className="absolute top-12 left-12 group flex items-center gap-3 bg-slate-900/50 border border-slate-800 text-slate-500 px-8 py-4 rounded-3xl font-black text-xs tracking-[0.3em] hover:text-white hover:border-indigo-500/50 transition-all backdrop-blur-xl"
        >
          <svg className="w-5 h-5 group-hover:-translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
          EXIT KIOSK
        </button>

        <div className="w-full max-w-5xl text-center relative z-10">
          {!lastScanResult && !unknownTag ? (
            <div className="space-y-16 animate-in fade-in zoom-in duration-700">
              <div className="relative mx-auto w-64 h-64">
                <div className="absolute inset-0 bg-indigo-600/20 rounded-[64px] animate-ping" />
                <div className="relative w-full h-full bg-slate-900 border-2 border-indigo-500/30 rounded-[64px] flex items-center justify-center shadow-[0_0_100px_rgba(79,70,229,0.15)]">
                  <svg className="w-32 h-32 text-indigo-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M12 12h4.01M16 20h4M4 12h4m12 0h.01M5 8h2a1 1 0 001-1V5a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1zm12 0h2a1 1 0 001-1V5a1 1 0 00-1-1h-2a1 1 0 00-1 1v2a1 1 0 001 1zM5 17h2a1 1 0 001-1v-2a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1z" /></svg>
                </div>
              </div>
              <div className="space-y-6">
                <h2 className="text-8xl font-black tracking-tighter uppercase italic leading-none">Scanning Standby</h2>
                <p className="text-2xl font-bold text-slate-500 tracking-[0.4em] uppercase opacity-70">Tap Student ID Card to Log Attendance</p>
              </div>
            </div>
          ) : lastScanResult ? (
            <div className="space-y-10 animate-in slide-in-from-bottom-20 duration-500">
              <div className={`text-[160px] font-black leading-none tracking-tighter uppercase italic drop-shadow-2xl ${lastScanResult.type === 'IN' ? 'text-emerald-400' : 'text-amber-400'}`}>
                {lastScanResult.type === 'IN' ? 'Time In' : 'Time Out'}
              </div>
              <div className="space-y-4">
                <h3 className="text-6xl font-black text-white tracking-tight">{lastScanResult.learner.firstName} {lastScanResult.learner.lastName}</h3>
                <div className="flex flex-col gap-2">
                  <p className="text-3xl font-bold text-indigo-400/80 uppercase tracking-[0.2em]">{lastScanResult.time}</p>
                  <p className="text-xl font-bold text-slate-500 uppercase tracking-widest">{lastScanResult.date}</p>
                  <code className="text-slate-600 font-mono text-sm mt-4 tracking-[0.5em]">{lastScanResult.uid}</code>
                </div>
              </div>
              <div className={`mt-10 inline-flex items-center gap-4 px-12 py-6 rounded-[40px] border-4 font-black text-3xl tracking-[0.3em] ${lastScanResult.type === 'IN' ? 'border-emerald-500/20 bg-emerald-500/5 text-emerald-400' : 'border-amber-500/20 bg-amber-500/5 text-amber-400'}`}>
                <span className="w-4 h-4 rounded-full bg-current animate-pulse" />
                VERIFIED
              </div>
            </div>
          ) : (
            <div className="space-y-10 animate-in shake duration-500">
               <div className="text-[140px] font-black leading-none tracking-tighter uppercase italic text-rose-500 drop-shadow-2xl">
                Unknown
              </div>
              <div className="space-y-4">
                <h3 className="text-5xl font-black text-white">UID: {unknownTag}</h3>
                <p className="text-2xl font-bold text-slate-500 uppercase tracking-widest">Tag is not registered in the directory</p>
              </div>
              <div className="inline-flex items-center gap-4 px-12 py-6 rounded-[40px] border-4 border-rose-500/20 bg-rose-500/5 text-rose-500 font-black text-3xl tracking-[0.3em]">
                <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                ACCESS DENIED
              </div>
            </div>
          )}
        </div>

        <div className="absolute bottom-12 flex gap-12 text-[12px] font-black text-slate-700 tracking-[0.5em] uppercase">
          <div className="flex items-center gap-3">
            <span className={`w-2 h-2 rounded-full ${status === 'connected' ? 'bg-emerald-500' : 'bg-rose-500'}`} />
            READER: {status}
          </div>
          <span>•</span>
          <div className="flex items-center gap-3">
            <span className="w-2 h-2 rounded-full bg-indigo-500" />
            RECORDS: {learners.length} STUDENTS
          </div>
        </div>
      </div>
    );
  }

  // REGISTRATION MODE UI
  return (
    <div className="min-h-screen bg-[#020617] text-slate-200 flex flex-col p-6 md:p-10">
      <header className="max-w-7xl mx-auto w-full flex flex-col md:flex-row justify-between items-center mb-12 gap-8">
        <div className="flex items-center gap-6">
          <div className="w-16 h-16 bg-indigo-600 rounded-[28px] flex items-center justify-center shadow-2xl shadow-indigo-600/20 rotate-3 transform hover:rotate-0 transition-transform cursor-pointer">
             <svg className="w-10 h-10 text-white -rotate-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
          </div>
          <div>
            <h1 className="text-4xl font-black text-white tracking-tighter uppercase italic leading-none">Registrar</h1>
            <div className="flex items-center gap-4 mt-2">
              <span className="flex items-center gap-2 text-indigo-400 text-[11px] font-black tracking-[0.3em] uppercase">
                <span className="w-2 h-2 bg-indigo-500 rounded-full animate-pulse" />
                Live Control Console
              </span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <button 
            onClick={() => setIsStandbyMode(true)}
            className="group px-8 py-4 bg-slate-900 border border-indigo-500/30 text-indigo-400 rounded-2xl text-[11px] font-black tracking-[0.2em] hover:bg-indigo-600 hover:text-white transition-all shadow-2xl flex items-center gap-3"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>
            LAUNCH KIOSK
          </button>

          <div className="flex items-center gap-4 bg-slate-900/60 p-3 rounded-3xl border border-slate-800 shadow-xl">
            <select 
              value={baudRate}
              onChange={(e) => setBaudRate(Number(e.target.value))}
              className="bg-slate-950 text-xs font-bold border-none rounded-xl px-4 py-2 cursor-pointer outline-none hover:bg-slate-900 transition-colors"
            >
              <option value={9600}>9600 Baud</option>
              <option value={115200}>115200 Baud</option>
            </select>
            <button
              onClick={status === 'connected' ? disconnect : () => connect({ baudRate })}
              className={`px-8 py-2.5 rounded-xl text-[11px] font-black tracking-widest transition-all ${status === 'connected' ? 'bg-rose-500/10 text-rose-500 border border-rose-500/20' : 'bg-indigo-600 text-white shadow-xl shadow-indigo-600/30'}`}
            >
              {status === 'connected' ? 'TERMINATE' : 'INITIATE'}
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto w-full grid grid-cols-1 lg:grid-cols-12 gap-10 mb-12">
        <div className="lg:col-span-4 space-y-8">
          <section className="bg-slate-900/40 rounded-[40px] border border-slate-800 p-10 shadow-2xl relative overflow-hidden backdrop-blur-xl">
            <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-500/5 blur-[50px] rounded-full" />
            <h2 className="text-xs font-black text-indigo-400 mb-10 uppercase tracking-[0.4em] flex items-center gap-3">
              <span className="w-1 h-5 bg-indigo-500 rounded-full" />
              Establish Link
            </h2>
            <div className="space-y-10">
              <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] ml-1">Active UID Capture</label>
                <div className={`p-8 rounded-3xl border-2 transition-all duration-500 ${activeRfid ? (conflictWarning ? 'bg-rose-950/20 border-rose-500/50' : 'bg-indigo-950/20 border-indigo-500/50') : 'bg-slate-950/50 border-slate-800'}`}>
                  {activeRfid ? (
                    <div className="flex flex-col">
                      <span className={`text-[10px] font-black mb-1 tracking-widest uppercase ${conflictWarning ? 'text-rose-400' : 'text-indigo-400'}`}>
                        {conflictWarning ? 'DUPLICATE DETECTED' : 'ID DETECTED'}
                      </span>
                      <code className="text-2xl font-black text-white font-mono tracking-tighter break-all">{activeRfid}</code>
                    </div>
                  ) : (
                    <div className="text-center py-2">
                      <p className="text-[11px] font-black text-slate-600 tracking-[0.2em] animate-pulse">WAITING FOR CARD...</p>
                    </div>
                  )}
                </div>
                {conflictWarning && (
                  <p className="text-[10px] font-bold text-rose-400 px-2 leading-relaxed animate-in fade-in slide-in-from-top-1">
                    {conflictWarning}
                  </p>
                )}
              </div>

              <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] ml-1">Assigned Target</label>
                <div className={`p-8 rounded-3xl border-2 transition-all duration-500 ${selectedLearnerId ? 'bg-indigo-950/20 border-indigo-500/30' : 'bg-slate-950/50 border-slate-800 border-dashed'}`}>
                  {selectedLearnerId ? (
                    <div className="flex items-center gap-5">
                      <div className="w-14 h-14 bg-indigo-500 rounded-2xl flex items-center justify-center font-black text-xl text-white shadow-xl shadow-indigo-500/20">
                        {learners.find(l => l.id === selectedLearnerId)?.lastName?.charAt(0)}
                      </div>
                      <div>
                        <div className="font-black text-white text-lg leading-none">{learners.find(l => l.id === selectedLearnerId)?.firstName} {learners.find(l => l.id === selectedLearnerId)?.lastName}</div>
                        <div className="text-[10px] text-slate-500 font-bold uppercase tracking-[0.2em] mt-2">LRN: {learners.find(l => l.id === selectedLearnerId)?.lrn}</div>
                      </div>
                    </div>
                  ) : <p className="text-[11px] font-black text-slate-600 text-center py-2 tracking-widest">SELECT FROM DIRECTORY</p>}
                </div>
              </div>

              <button
                disabled={!activeRfid || !selectedLearnerId || !!conflictWarning}
                onClick={handleLink}
                className="w-full bg-indigo-600 hover:bg-indigo-500 disabled:opacity-10 text-white font-black py-6 rounded-[32px] shadow-2xl shadow-indigo-600/20 uppercase tracking-[0.4em] text-[11px] active:scale-95 transition-all"
              >
                PAIR DEVICE & SAVE
              </button>
            </div>
          </section>

          <section className="bg-slate-900/40 rounded-[40px] border border-slate-800 p-8 overflow-hidden backdrop-blur-md">
            <h2 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] mb-6">Serial Debug</h2>
            <div className="h-44 rounded-3xl overflow-hidden border border-slate-800 bg-black/40 shadow-inner">
              <Terminal logs={logs.slice(-30)} />
            </div>
          </section>
        </div>

        <div className="lg:col-span-8 space-y-8">
          <div className="relative group">
            <div className="absolute inset-0 bg-indigo-500/5 blur-3xl rounded-full transition-opacity opacity-0 group-hover:opacity-100" />
            <svg className="w-6 h-6 absolute left-6 top-1/2 -translate-y-1/2 text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
            <input
              type="text"
              placeholder="Filter by Student Name, LRN, or Card UID..."
              value={searchQuery}
              onChange={e => setSearchQuery(e.target.value)}
              className="w-full bg-slate-900 border border-slate-800 rounded-[36px] pl-16 pr-10 py-6 text-[15px] font-medium focus:border-indigo-500/50 outline-none transition-all shadow-2xl placeholder:text-slate-700"
            />
          </div>

          <div className="bg-slate-900/40 rounded-[48px] border border-slate-800 overflow-hidden shadow-2xl backdrop-blur-xl">
            {loading && fetchedCount === 0 ? (
              <div className="p-40 text-center flex flex-col items-center gap-6">
                <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin" />
                <p className="text-[11px] font-black text-slate-600 tracking-[0.4em] uppercase">Fetching Directory...</p>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                  <thead>
                    <tr className="bg-slate-950/40 border-b border-slate-800">
                      <th className="p-8 text-[11px] font-black text-slate-500 uppercase tracking-[0.3em]">Student Profile</th>
                      <th className="p-8 text-[11px] font-black text-slate-500 uppercase tracking-[0.3em] text-center">RFID Assignment</th>
                      <th className="p-8 text-[11px] font-black text-slate-500 uppercase tracking-[0.3em] text-right">Selection</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-800/50">
                    {filteredLearners.map(learner => {
                      const isLinked = !!uidMappings[learner.id];
                      const isSelected = selectedLearnerId === learner.id;
                      return (
                        <tr key={learner.id} className={`transition-all duration-300 ${isSelected ? 'bg-indigo-600/10' : 'hover:bg-slate-800/30'}`}>
                          <td className="p-8">
                            <div className="flex items-center gap-6">
                              <div className={`w-14 h-14 rounded-2xl flex items-center justify-center font-black text-lg border transition-all ${isLinked ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' : 'bg-slate-800/50 text-slate-500 border-slate-700'}`}>
                                {learner.lastName?.charAt(0)}
                              </div>
                              <div>
                                <div className="text-[16px] font-black text-white tracking-tight">{learner.lastName}, {learner.firstName}</div>
                                <div className="text-[10px] font-bold text-slate-500 mt-2 uppercase tracking-widest">LRN: {learner.lrn}</div>
                              </div>
                            </div>
                          </td>
                          <td className="p-8 text-center">
                            {isLinked ? (
                              <div className="inline-flex flex-col gap-1">
                                <span className="px-5 py-2 rounded-full bg-emerald-500/10 text-emerald-400 text-[11px] font-black border border-emerald-500/20 shadow-sm font-mono tracking-tighter">
                                  {uidMappings[learner.id]}
                                </span>
                              </div>
                            ) : (
                              <span className="text-slate-800 text-[11px] font-black uppercase tracking-widest">UNREGISTERED</span>
                            )}
                          </td>
                          <td className="p-8 text-right">
                            <button 
                              onClick={() => {
                                setSelectedLearnerId(isSelected ? null : learner.id);
                                setConflictWarning(null);
                              }} 
                              className={`px-8 py-3 rounded-2xl text-[11px] font-black transition-all transform active:scale-90 tracking-[0.1em] ${
                                isSelected 
                                ? 'bg-indigo-500 text-white shadow-xl shadow-indigo-500/30' 
                                : 'bg-slate-800/80 text-slate-400 hover:text-white hover:bg-slate-700'
                              }`}
                            >
                              {isSelected ? 'SELECTED' : 'SELECT'}
                            </button>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      </main>

      <footer className="max-w-7xl mx-auto w-full mt-auto pt-10 border-t border-slate-900/50 flex flex-col md:flex-row justify-between items-center gap-6 text-[11px] font-black text-slate-700 uppercase tracking-[0.4em]">
        <div className="flex gap-12">
          <div className="flex items-center gap-3">
            <span className="text-slate-800">MAPPED_TAGS:</span>
            <span className="text-indigo-400/50">{Object.keys(uidMappings).length} CARDS</span>
          </div>
          <div className="flex items-center gap-3">
            <span className="text-slate-800">POOL:</span>
            <span className="text-indigo-400/50">{learners.length} LEARNERS</span>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <span className="w-2 h-2 bg-emerald-500/20 rounded-full" />
          SYSTEM_STATE: OPERATIONAL
        </div>
      </footer>

      {dbError && (
        <div className="fixed bottom-12 right-12 bg-rose-500 text-white p-6 rounded-3xl shadow-2xl flex items-center gap-4 z-[200] animate-in slide-in-from-right-10">
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
          <span className="text-xs font-black uppercase tracking-widest">{dbError}</span>
          <button onClick={() => setDbError(null)} className="p-2 hover:bg-white/10 rounded-lg">×</button>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { useSerial } from './hooks/useSerial';
import Terminal from './components/Terminal';
import { Learner } from './types';
import { supabase } from './lib/supabase';

interface AttendanceRecord {
  learnerId: string;
  type: 'IN' | 'OUT';
  timestamp: string;
}

const App: React.FC = () => {
  const { status, logs, connect, disconnect } = useSerial();
  const [baudRate, setBaudRate] = useState(9600);
  const [isStandbyMode, setIsStandbyMode] = useState(false);

  // Database State
  const [learners, setLearners] = useState<Learner[]>([]);
  const [isInitialLoading, setIsInitialLoading] = useState(true);
  const [isFetchingAll, setIsFetchingAll] = useState(false);
  const [dbError, setDbError] = useState<string | null>(null);
  const [fetchedCount, setFetchedCount] = useState(0);

  // Registration & UI State
  const [selectedLearnerId, setSelectedLearnerId] = useState<string | null>(null);
  const [activeRfid, setActiveRfid] = useState<string>('');
  const [searchQuery, setSearchQuery] = useState('');
  const [conflictWarning, setConflictWarning] = useState<string | null>(null);

  // Attendance Kiosk State
  const [lastScanResult, setLastScanResult] = useState<{
    learner: Learner;
    type: 'IN' | 'OUT';
    time: string;
    uid: string;
  } | null>(null);
  const [unknownTag, setUnknownTag] = useState<string | null>(null);

  // Local Persistence
  const [uidMappings, setUidMappings] = useState<Record<string, string>>(() => {
    const saved = localStorage.getItem('rfid_mappings');
    return saved ? JSON.parse(saved) : {};
  });

  const [attendanceLogs, setAttendanceLogs] = useState<AttendanceRecord[]>(() => {
    const saved = localStorage.getItem('attendance_logs');
    return saved ? JSON.parse(saved) : [];
  });

  // Fetch ALL learners recursively to ensure we have the full dataset locally for search
  const fetchAllLearners = useCallback(async () => {
    try {
      setIsFetchingAll(true);
      setDbError(null);
      let allData: Learner[] = [];
      let from = 0;
      const step = 1000;
      let hasMore = true;

      while (hasMore) {
        const { data, error: fetchErr } = await supabase
          .from('learners')
          .select('*')
          .range(from, from + step - 1)
          .order('lastName', { ascending: true });

        if (fetchErr) throw fetchErr;

        if (data && data.length > 0) {
          allData = [...allData, ...data];
          setLearners([...allData]); // Update UI progressively
          setFetchedCount(allData.length);
          setIsInitialLoading(false);
          hasMore = data.length === step;
          from += step;
        } else {
          hasMore = false;
        }
      }
    } catch (err: any) {
      setDbError(err.message || 'Error fetching learners.');
    } finally {
      setIsFetchingAll(false);
      setIsInitialLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchAllLearners();
  }, [fetchAllLearners]);

  // Persist local state
  useEffect(() => {
    localStorage.setItem('rfid_mappings', JSON.stringify(uidMappings));
  }, [uidMappings]);

  useEffect(() => {
    localStorage.setItem('attendance_logs', JSON.stringify(attendanceLogs));
  }, [attendanceLogs]);

  // Kiosk Auto-Reset
  useEffect(() => {
    if (lastScanResult || unknownTag) {
      const timer = setTimeout(() => {
        setLastScanResult(null);
        setUnknownTag(null);
      }, 4000);
      return () => clearTimeout(timer);
    }
  }, [lastScanResult, unknownTag]);

  // Process Serial Stream
  useEffect(() => {
    const lastLog = logs[logs.length - 1];
    if (lastLog && lastLog.type === 'in') {
      // Normalize UID: Uppercase, Trimmed, single spaces
      const scannedUid = lastLog.text.trim().toUpperCase().replace(/\s+/g, ' ');
      if (scannedUid.length < 4) return;

      if (isStandbyMode) {
        // Find mapped student
        const learnerId = Object.keys(uidMappings).find(
          id => uidMappings[id].toUpperCase() === scannedUid
        );
        const learner = learners.find(l => l.id === learnerId);

        if (learner) {
          // Calculate In/Out based on local logs
          const studentHistory = attendanceLogs.filter(log => log.learnerId === learner.id);
          const lastRecord = studentHistory[studentHistory.length - 1];
          const nextType = lastRecord?.type === 'IN' ? 'OUT' : 'IN';

          const newRecord: AttendanceRecord = {
            learnerId: learner.id,
            type: nextType,
            timestamp: new Date().toISOString()
          };

          setAttendanceLogs(prev => [...prev, newRecord]);
          setLastScanResult({
            learner,
            type: nextType,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
            uid: scannedUid
          });
          setUnknownTag(null);
        } else {
          setUnknownTag(scannedUid);
          setLastScanResult(null);
        }
      } else {
        // Registration Logic
        setActiveRfid(scannedUid);
        setConflictWarning(null);

        // Immediate check for duplication in registration view
        const existingOwnerId = Object.keys(uidMappings).find(
          id => uidMappings[id].toUpperCase() === scannedUid
        );
        if (existingOwnerId) {
          const owner = learners.find(l => l.id === existingOwnerId);
          setConflictWarning(`Conflict: Tag already assigned to ${owner ? `${owner.firstName} ${owner.lastName}` : 'ID ' + existingOwnerId}`);
        }
      }
    }
  }, [logs, isStandbyMode, uidMappings, learners, attendanceLogs]);

  const handleLink = () => {
    if (!selectedLearnerId || !activeRfid || conflictWarning) return;
    setUidMappings(prev => ({ ...prev, [selectedLearnerId]: activeRfid }));
    setActiveRfid('');
    setSelectedLearnerId(null);
    setConflictWarning(null);
  };

  const filteredLearners = useMemo(() => {
    const query = searchQuery.toLowerCase();
    return learners.filter(l => {
      const fullName = `${l.firstName} ${l.lastName} ${l.lrn}`.toLowerCase();
      const rfid = uidMappings[l.id]?.toLowerCase() || '';
      return fullName.includes(query) || rfid.includes(query);
    });
  }, [learners, searchQuery, uidMappings]);

  // FULL SCREEN STANDBY MODE
  if (isStandbyMode) {
    return (
      <div className="fixed inset-0 bg-[#020617] text-white flex flex-col items-center justify-center p-8 z-[1000] overflow-hidden">
        {/* Ambient background decoration */}
        <div className="absolute top-0 left-0 w-full h-full opacity-20 pointer-events-none">
          <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-indigo-500 rounded-full blur-[160px] animate-pulse" />
          <div className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-blue-600 rounded-full blur-[160px] animate-pulse" />
        </div>

        <button 
          onClick={() => setIsStandbyMode(false)}
          className="absolute top-12 left-12 bg-slate-900/50 border border-slate-700 text-slate-400 hover:text-white px-6 py-3 rounded-2xl font-black text-[10px] tracking-[0.3em] uppercase transition-all backdrop-blur-md"
        >
          ← Exit Kiosk Mode
        </button>

        <div className="relative z-10 w-full max-w-5xl text-center">
          {!lastScanResult && !unknownTag ? (
            <div className="space-y-16 animate-in fade-in zoom-in duration-700">
              <div className="w-56 h-56 bg-indigo-600/10 rounded-[64px] border-4 border-indigo-500/20 flex items-center justify-center mx-auto shadow-[0_0_100px_rgba(79,70,229,0.1)] relative">
                <div className="absolute inset-0 bg-indigo-500/20 rounded-[64px] animate-ping opacity-40" />
                <svg className="w-28 h-28 text-indigo-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M12 12h4.01M16 20h4M4 12h4m12 0h.01M5 8h2a1 1 0 001-1V5a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1zm12 0h2a1 1 0 001-1V5a1 1 0 00-1-1h-2a1 1 0 00-1 1v2a1 1 0 001 1zM5 17h2a1 1 0 001-1v-2a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1z" />
                </svg>
              </div>
              <div className="space-y-4">
                <h2 className="text-8xl font-black tracking-tighter uppercase italic text-white drop-shadow-2xl">Ready to Scan</h2>
                <p className="text-xl font-bold text-slate-500 tracking-[0.5em] uppercase">Please tap your RFID card</p>
              </div>
            </div>
          ) : lastScanResult ? (
            <div className="space-y-12 animate-in slide-in-from-bottom-20 duration-500">
              <div className={`text-[180px] font-black leading-none tracking-tighter uppercase italic drop-shadow-2xl ${lastScanResult.type === 'IN' ? 'text-emerald-400' : 'text-amber-400'}`}>
                {lastScanResult.type}
              </div>
              <div className="space-y-6">
                <h3 className="text-7xl font-black text-white">{lastScanResult.learner.firstName} {lastScanResult.learner.lastName}</h3>
                <div className="flex flex-col items-center gap-2">
                  <p className="text-3xl font-black text-indigo-400/80 tracking-widest">{lastScanResult.time}</p>
                  <code className="text-slate-600 font-mono text-xs uppercase tracking-[0.5em] mt-2">{lastScanResult.uid}</code>
                </div>
              </div>
              <div className={`inline-flex items-center gap-6 px-16 py-8 rounded-[40px] border-4 font-black text-4xl tracking-widest ${lastScanResult.type === 'IN' ? 'border-emerald-500/20 bg-emerald-500/5 text-emerald-400' : 'border-amber-500/20 bg-amber-500/5 text-amber-400'}`}>
                <span className="w-4 h-4 rounded-full bg-current animate-pulse" />
                CONFIRMED
              </div>
            </div>
          ) : (
            <div className="space-y-12 animate-in shake duration-500">
               <div className="text-[140px] font-black leading-none tracking-tighter uppercase italic text-rose-500">UNKNOWN</div>
              <div className="space-y-4">
                <h3 className="text-5xl font-black text-white">UID: {unknownTag}</h3>
                <p className="text-2xl font-bold text-slate-500 uppercase tracking-widest">Card not found in database</p>
              </div>
              <div className="inline-flex items-center gap-6 px-16 py-8 rounded-[40px] border-4 border-rose-500/20 bg-rose-500/5 text-rose-500 font-black text-3xl tracking-widest">
                <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                ACCESS DENIED
              </div>
            </div>
          )}
        </div>

        <div className="absolute bottom-12 flex gap-12 text-[10px] font-black text-slate-700 tracking-[0.5em] uppercase">
          <div className="flex items-center gap-3">
            <span className={`w-2 h-2 rounded-full ${status === 'connected' ? 'bg-emerald-500' : 'bg-rose-500'}`} />
            READER: {status}
          </div>
          <span>•</span>
          <div className="flex items-center gap-3">
            <span className="w-2 h-2 rounded-full bg-indigo-500" />
            POOL: {learners.length} STUDENTS
          </div>
        </div>
      </div>
    );
  }

  // REGISTRATION MODE UI
  return (
    <div className="min-h-screen bg-[#020617] text-slate-200 flex flex-col p-6 lg:p-12">
      <header className="max-w-7xl mx-auto w-full flex flex-col md:flex-row justify-between items-center mb-12 gap-8">
        <div className="flex items-center gap-6">
          <div className="w-16 h-16 bg-indigo-600 rounded-3xl flex items-center justify-center shadow-2xl shadow-indigo-600/20 rotate-3 transform hover:rotate-0 transition-transform cursor-pointer">
             <svg className="w-10 h-10 text-white -rotate-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
          </div>
          <div>
            <h1 className="text-4xl font-black text-white tracking-tighter uppercase italic leading-none">Registrar</h1>
            <div className="flex items-center gap-4 mt-2">
              <span className="flex items-center gap-2 text-indigo-400 text-[10px] font-black tracking-[0.3em] uppercase">
                <span className="w-2 h-2 bg-indigo-500 rounded-full animate-pulse" />
                Ready to Map Devices
              </span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <button 
            onClick={() => setIsStandbyMode(true)}
            className="group px-8 py-4 bg-slate-900 border border-indigo-500/30 text-indigo-400 rounded-2xl text-[10px] font-black tracking-[0.2em] hover:bg-indigo-600 hover:text-white transition-all shadow-2xl flex items-center gap-3"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>
            STANDBY KIOSK
          </button>

          <div className="flex items-center gap-4 bg-slate-900/60 p-3 rounded-[24px] border border-slate-800 shadow-xl">
            <select 
              value={baudRate}
              onChange={(e) => setBaudRate(Number(e.target.value))}
              className="bg-slate-950 text-xs font-bold border-none rounded-xl px-4 py-2 outline-none"
            >
              <option value={9600}>9600 Baud</option>
              <option value={115200}>115200 Baud</option>
            </select>
            <button
              onClick={status === 'connected' ? disconnect : () => connect({ baudRate })}
              className={`px-8 py-2.5 rounded-xl text-[10px] font-black tracking-widest transition-all ${status === 'connected' ? 'bg-rose-500/10 text-rose-500 border border-rose-500/20' : 'bg-indigo-600 text-white shadow-xl shadow-indigo-600/30'}`}
            >
              {status === 'connected' ? 'STOP' : 'CONNECT'}
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto w-full grid grid-cols-1 lg:grid-cols-12 gap-10">
        <div className="lg:col-span-4 space-y-8">
          <section className="bg-slate-900/40 rounded-[40px] border border-slate-800 p-10 shadow-2xl relative overflow-hidden backdrop-blur-xl">
            <h2 className="text-[10px] font-black text-indigo-400 mb-10 uppercase tracking-[0.4em] flex items-center gap-3">
              <span className="w-1 h-5 bg-indigo-500 rounded-full" />
              Pairing Console
            </h2>
            <div className="space-y-10">
              <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] ml-1">Live Capture</label>
                <div className={`p-8 rounded-3xl border-2 transition-all duration-500 ${activeRfid ? (conflictWarning ? 'bg-rose-950/20 border-rose-500/50' : 'bg-indigo-950/20 border-indigo-500/50 shadow-[inset_0_0_20px_rgba(99,102,241,0.1)]') : 'bg-slate-950/50 border-slate-800'}`}>
                  {activeRfid ? (
                    <div className="flex flex-col">
                      <span className={`text-[10px] font-black mb-1 tracking-widest uppercase ${conflictWarning ? 'text-rose-400' : 'text-indigo-400'}`}>
                        {conflictWarning ? 'DUPLICATE' : 'TAG DETECTED'}
                      </span>
                      <code className="text-2xl font-black text-white font-mono tracking-tighter break-all">{activeRfid}</code>
                    </div>
                  ) : (
                    <div className="text-center py-2">
                      <p className="text-[11px] font-black text-slate-700 tracking-[0.2em] animate-pulse">WAITING FOR RFID...</p>
                    </div>
                  )}
                </div>
                {conflictWarning && (
                  <p className="text-[10px] font-bold text-rose-400 px-2 leading-relaxed italic">
                    {conflictWarning}
                  </p>
                )}
              </div>

              <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] ml-1">Assigned Learner</label>
                <div className={`p-8 rounded-3xl border-2 transition-all duration-500 ${selectedLearnerId ? 'bg-indigo-950/20 border-indigo-500/30' : 'bg-slate-950/50 border-slate-800 border-dashed'}`}>
                  {selectedLearnerId ? (
                    <div className="flex items-center gap-5">
                      <div className="w-14 h-14 bg-indigo-600 text-white rounded-2xl flex items-center justify-center font-black text-xl shadow-xl shadow-indigo-500/20">
                        {learners.find(l => l.id === selectedLearnerId)?.lastName?.charAt(0)}
                      </div>
                      <div>
                        <div className="font-black text-white text-lg leading-tight">{learners.find(l => l.id === selectedLearnerId)?.firstName} {learners.find(l => l.id === selectedLearnerId)?.lastName}</div>
                        <div className="text-[10px] text-slate-500 font-bold uppercase tracking-[0.2em] mt-2">LRN: {learners.find(l => l.id === selectedLearnerId)?.lrn}</div>
                      </div>
                    </div>
                  ) : <p className="text-[11px] font-black text-slate-700 text-center py-2 tracking-widest">CHOOSE FROM DIRECTORY</p>}
                </div>
              </div>

              <button
                disabled={!activeRfid || !selectedLearnerId || !!conflictWarning}
                onClick={handleLink}
                className="w-full bg-indigo-600 hover:bg-indigo-500 disabled:opacity-10 text-white font-black py-6 rounded-[32px] shadow-2xl shadow-indigo-600/20 uppercase tracking-[0.4em] text-[10px] active:scale-95 transition-all"
              >
                SAVE ASSIGNMENT
              </button>
            </div>
          </section>

          <section className="bg-slate-900/40 rounded-[40px] border border-slate-800 p-8 overflow-hidden backdrop-blur-md shadow-2xl">
            <h2 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] mb-6">Serial Debug</h2>
            <div className="h-48 rounded-3xl overflow-hidden border border-slate-800 bg-black/40">
              <Terminal logs={logs.slice(-30)} />
            </div>
          </section>
        </div>

        <div className="lg:col-span-8 space-y-8">
          <div className="relative group">
            <svg className="w-6 h-6 absolute left-6 top-1/2 -translate-y-1/2 text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
            <input
              type="text"
              placeholder="Instant Search Learners (Name, LRN, or Card ID)..."
              value={searchQuery}
              onChange={e => setSearchQuery(e.target.value)}
              className="w-full bg-slate-900 border border-slate-800 rounded-[32px] pl-16 pr-10 py-6 text-[15px] font-medium focus:border-indigo-500/50 outline-none transition-all shadow-2xl placeholder:text-slate-700"
            />
          </div>

          <div className="bg-slate-900/40 rounded-[48px] border border-slate-800 overflow-hidden shadow-2xl backdrop-blur-xl">
            {isInitialLoading ? (
              <div className="p-40 text-center flex flex-col items-center gap-6">
                <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin" />
                <p className="text-[11px] font-black text-slate-600 tracking-[0.4em] uppercase">Initializing Database...</p>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                  <thead>
                    <tr className="bg-slate-950/40 border-b border-slate-800">
                      <th className="p-8 text-[10px] font-black text-slate-500 uppercase tracking-[0.3em]">Student Name & LRN</th>
                      <th className="p-8 text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] text-center">RFID Assignment</th>
                      <th className="p-8 text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] text-right">Selection</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-800/50">
                    {filteredLearners.map(learner => {
                      const isLinked = !!uidMappings[learner.id];
                      const isSelected = selectedLearnerId === learner.id;
                      return (
                        <tr key={learner.id} className={`transition-all duration-300 ${isSelected ? 'bg-indigo-600/10' : 'hover:bg-slate-800/30'}`}>
                          <td className="p-8">
                            <div className="text-[16px] font-black text-white tracking-tight leading-tight">{learner.lastName}, {learner.firstName}</div>
                            <div className="text-[10px] font-bold text-slate-500 mt-2 uppercase tracking-widest">LRN: {learner.lrn}</div>
                          </td>
                          <td className="p-8 text-center">
                            {isLinked ? (
                              <span className="px-5 py-2 rounded-full bg-emerald-500/10 text-emerald-400 text-[10px] font-black border border-emerald-500/20 font-mono tracking-tighter">
                                {uidMappings[learner.id]}
                              </span>
                            ) : (
                              <span className="text-slate-800 text-[10px] font-black uppercase tracking-widest">UNASSIGNED</span>
                            )}
                          </td>
                          <td className="p-8 text-right">
                            <button 
                              onClick={() => {
                                setSelectedLearnerId(isSelected ? null : learner.id);
                                setConflictWarning(null);
                              }} 
                              className={`px-8 py-3 rounded-2xl text-[10px] font-black transition-all transform active:scale-90 tracking-widest ${
                                isSelected 
                                ? 'bg-indigo-500 text-white shadow-xl shadow-indigo-500/30' 
                                : 'bg-slate-800/80 text-slate-400 hover:text-white hover:bg-slate-700'
                              }`}
                            >
                              {isSelected ? 'SELECTED' : 'SELECT'}
                            </button>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
            {isFetchingAll && (
              <div className="p-4 bg-indigo-600/10 border-t border-indigo-500/20 text-center">
                <p className="text-[9px] font-black text-indigo-400 uppercase tracking-[0.3em]">
                  Synchronizing {fetchedCount} Records...
                </p>
              </div>
            )}
          </div>
        </div>
      </main>

      <footer className="max-w-7xl mx-auto w-full mt-12 pt-10 border-t border-slate-900/50 flex flex-col md:flex-row justify-between items-center gap-6 text-[10px] font-black text-slate-700 uppercase tracking-[0.5em]">
        <div className="flex gap-12">
          <div className="flex items-center gap-3">
            <span className="text-slate-800">ASSIGNED_TAGS:</span>
            <span className="text-indigo-400/50">{Object.keys(uidMappings).length}</span>
          </div>
          <div className="flex items-center gap-3">
            <span className="text-slate-800">DATABASE_POOL:</span>
            <span className="text-indigo-400/50">{learners.length} STUDENTS</span>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <span className={`w-2 h-2 rounded-full ${status === 'connected' ? 'bg-emerald-500' : 'bg-slate-800'}`} />
          READER_STATUS: {status.toUpperCase()}
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { useSerial } from './hooks/useSerial';
import Terminal from './components/Terminal';
import { Learner } from './types';
import { supabase } from './lib/supabase';

interface AttendanceRecord {
  learnerId: string;
  type: 'IN' | 'OUT';
  timestamp: string;
}

const App: React.FC = () => {
  const { status, logs, connect, disconnect } = useSerial();
  const [baudRate, setBaudRate] = useState(9600);
  const [isStandbyMode, setIsStandbyMode] = useState(false);

  // Database State
  const [learners, setLearners] = useState<Learner[]>([]);
  const [isInitialLoading, setIsInitialLoading] = useState(true);
  const [isFetchingAll, setIsFetchingAll] = useState(false);
  const [dbError, setDbError] = useState<string | null>(null);
  const [fetchedCount, setFetchedCount] = useState(0);

  // Registration & UI State
  const [selectedLearnerId, setSelectedLearnerId] = useState<string | null>(null);
  const [activeRfid, setActiveRfid] = useState<string>('');
  const [searchQuery, setSearchQuery] = useState('');
  const [conflictWarning, setConflictWarning] = useState<string | null>(null);
  const [scanFlash, setScanFlash] = useState(false); // Used to trigger visual refresh

  // Attendance Kiosk State
  const [lastScanResult, setLastScanResult] = useState<{
    learner: Learner;
    type: 'IN' | 'OUT';
    time: string;
    uid: string;
  } | null>(null);
  const [unknownTag, setUnknownTag] = useState<string | null>(null);

  // Local Persistence
  const [uidMappings, setUidMappings] = useState<Record<string, string>>(() => {
    const saved = localStorage.getItem('rfid_mappings');
    return saved ? JSON.parse(saved) : {};
  });

  const [attendanceLogs, setAttendanceLogs] = useState<AttendanceRecord[]>(() => {
    const saved = localStorage.getItem('attendance_logs');
    return saved ? JSON.parse(saved) : [];
  });

  // Fetch ALL learners recursively to ensure we have the full dataset locally for search
  const fetchAllLearners = useCallback(async () => {
    try {
      setIsFetchingAll(true);
      setDbError(null);
      let allData: Learner[] = [];
      let from = 0;
      const step = 1000;
      let hasMore = true;

      while (hasMore) {
        const { data, error: fetchErr } = await supabase
          .from('learners')
          .select('*')
          .range(from, from + step - 1)
          .order('lastName', { ascending: true });

        if (fetchErr) throw fetchErr;

        if (data && data.length > 0) {
          allData = [...allData, ...data];
          setLearners([...allData]); // Update UI progressively
          setFetchedCount(allData.length);
          setIsInitialLoading(false);
          hasMore = data.length === step;
          from += step;
        } else {
          hasMore = false;
        }
      }
    } catch (err: any) {
      setDbError(err.message || 'Error fetching learners.');
    } finally {
      setIsFetchingAll(false);
      setIsInitialLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchAllLearners();
  }, [fetchAllLearners]);

  // Persist local state
  useEffect(() => {
    localStorage.setItem('rfid_mappings', JSON.stringify(uidMappings));
  }, [uidMappings]);

  useEffect(() => {
    localStorage.setItem('attendance_logs', JSON.stringify(attendanceLogs));
  }, [attendanceLogs]);

  // Kiosk Auto-Reset
  useEffect(() => {
    if (lastScanResult || unknownTag) {
      const timer = setTimeout(() => {
        setLastScanResult(null);
        setUnknownTag(null);
      }, 4000);
      return () => clearTimeout(timer);
    }
  }, [lastScanResult, unknownTag]);

  // Process Serial Stream
  useEffect(() => {
    const lastLog = logs[logs.length - 1];
    if (lastLog && lastLog.type === 'in') {
      // Normalize UID: Uppercase, Trimmed, single spaces
      const scannedUid = lastLog.text.trim().toUpperCase().replace(/\s+/g, ' ');
      if (scannedUid.length < 4) return;

      if (isStandbyMode) {
        // Standby Logic
        const learnerId = Object.keys(uidMappings).find(
          id => uidMappings[id].toUpperCase() === scannedUid
        );
        const learner = learners.find(l => l.id === learnerId);

        if (learner) {
          const studentHistory = attendanceLogs.filter(log => log.learnerId === learner.id);
          const lastRecord = studentHistory[studentHistory.length - 1];
          const nextType = lastRecord?.type === 'IN' ? 'OUT' : 'IN';

          setAttendanceLogs(prev => [...prev, {
            learnerId: learner.id,
            type: nextType,
            timestamp: new Date().toISOString()
          }]);

          setLastScanResult({
            learner,
            type: nextType,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
            uid: scannedUid
          });
          setUnknownTag(null);
        } else {
          setUnknownTag(scannedUid);
          setLastScanResult(null);
        }
      } else {
        // Registration Logic Refresh
        setActiveRfid(scannedUid);
        setConflictWarning(null);
        setScanFlash(true); // Trigger animation
        setTimeout(() => setScanFlash(false), 500);

        // Immediate check for duplication
        const existingOwnerId = Object.keys(uidMappings).find(
          id => uidMappings[id].toUpperCase() === scannedUid
        );
        if (existingOwnerId) {
          const owner = learners.find(l => l.id === existingOwnerId);
          setConflictWarning(`Conflict: Tag already assigned to ${owner ? `${owner.firstName} ${owner.lastName}` : 'ID ' + existingOwnerId}`);
        }
      }
    }
  }, [logs, isStandbyMode, uidMappings, learners, attendanceLogs]);

  const handleLink = () => {
    if (!selectedLearnerId || !activeRfid || conflictWarning) return;
    setUidMappings(prev => ({ ...prev, [selectedLearnerId]: activeRfid }));
    setActiveRfid('');
    setSelectedLearnerId(null);
    setConflictWarning(null);
  };

  const filteredLearners = useMemo(() => {
    const query = searchQuery.toLowerCase();
    return learners.filter(l => {
      const fullName = `${l.firstName} ${l.lastName} ${l.lrn}`.toLowerCase();
      const rfid = uidMappings[l.id]?.toLowerCase() || '';
      return fullName.includes(query) || rfid.includes(query);
    });
  }, [learners, searchQuery, uidMappings]);

  // STANDBY KIOSK MODE
  if (isStandbyMode) {
    return (
      <div className="fixed inset-0 bg-[#020617] text-white flex flex-col items-center justify-center p-8 z-[1000] overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-full opacity-20 pointer-events-none">
          <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-indigo-500 rounded-full blur-[160px] animate-pulse" />
          <div className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-blue-600 rounded-full blur-[160px] animate-pulse" />
        </div>

        <button 
          onClick={() => setIsStandbyMode(false)}
          className="absolute top-12 left-12 bg-slate-900/50 border border-slate-700 text-slate-400 hover:text-white px-6 py-3 rounded-2xl font-black text-[10px] tracking-[0.3em] uppercase transition-all backdrop-blur-md"
        >
          ← Exit Kiosk Mode
        </button>

        <div className="relative z-10 w-full max-w-5xl text-center">
          {!lastScanResult && !unknownTag ? (
            <div className="space-y-16 animate-in fade-in zoom-in duration-700">
              <div className="w-56 h-56 bg-indigo-600/10 rounded-[64px] border-4 border-indigo-500/20 flex items-center justify-center mx-auto shadow-[0_0_100px_rgba(79,70,229,0.1)] relative">
                <div className="absolute inset-0 bg-indigo-500/20 rounded-[64px] animate-ping opacity-40" />
                <svg className="w-28 h-28 text-indigo-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M12 12h4.01M16 20h4M4 12h4m12 0h.01M5 8h2a1 1 0 001-1V5a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1zm12 0h2a1 1 0 001-1V5a1 1 0 00-1-1h-2a1 1 0 00-1 1v2a1 1 0 001 1zM5 17h2a1 1 0 001-1v-2a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1z" />
                </svg>
              </div>
              <div className="space-y-4">
                <h2 className="text-8xl font-black tracking-tighter uppercase italic text-white drop-shadow-2xl">Ready to Scan</h2>
                <p className="text-xl font-bold text-slate-500 tracking-[0.5em] uppercase">Please tap your RFID card</p>
              </div>
            </div>
          ) : lastScanResult ? (
            <div className="space-y-12 animate-in slide-in-from-bottom-20 duration-500">
              <div className={`text-[180px] font-black leading-none tracking-tighter uppercase italic drop-shadow-2xl ${lastScanResult.type === 'IN' ? 'text-emerald-400' : 'text-amber-400'}`}>
                {lastScanResult.type}
              </div>
              <div className="space-y-6">
                <h3 className="text-7xl font-black text-white">{lastScanResult.learner.firstName} {lastScanResult.learner.lastName}</h3>
                <div className="flex flex-col items-center gap-2">
                  <p className="text-3xl font-black text-indigo-400/80 tracking-widest">{lastScanResult.time}</p>
                  <code className="text-slate-600 font-mono text-xs uppercase tracking-[0.5em] mt-2">{lastScanResult.uid}</code>
                </div>
              </div>
              <div className={`inline-flex items-center gap-6 px-16 py-8 rounded-[40px] border-4 font-black text-4xl tracking-widest ${lastScanResult.type === 'IN' ? 'border-emerald-500/20 bg-emerald-500/5 text-emerald-400' : 'border-amber-500/20 bg-amber-500/5 text-amber-400'}`}>
                <span className="w-4 h-4 rounded-full bg-current animate-pulse" />
                CONFIRMED
              </div>
            </div>
          ) : (
            <div className="space-y-12 animate-in shake duration-500">
               <div className="text-[140px] font-black leading-none tracking-tighter uppercase italic text-rose-500">UNKNOWN</div>
              <div className="space-y-4">
                <h3 className="text-5xl font-black text-white">UID: {unknownTag}</h3>
                <p className="text-2xl font-bold text-slate-500 uppercase tracking-widest">Card not found in database</p>
              </div>
              <div className="inline-flex items-center gap-6 px-16 py-8 rounded-[40px] border-4 border-rose-500/20 bg-rose-500/5 text-rose-500 font-black text-3xl tracking-widest">
                <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                ACCESS DENIED
              </div>
            </div>
          )}
        </div>

        <div className="absolute bottom-12 flex gap-12 text-[10px] font-black text-slate-700 tracking-[0.5em] uppercase">
          <div className="flex items-center gap-3">
            <span className={`w-2 h-2 rounded-full ${status === 'connected' ? 'bg-emerald-500' : 'bg-rose-500'}`} />
            READER: {status}
          </div>
          <span>•</span>
          <div className="flex items-center gap-3">
            <span className="w-2 h-2 rounded-full bg-indigo-500" />
            POOL: {learners.length} STUDENTS
          </div>
        </div>
      </div>
    );
  }

  // REGISTRATION MODE UI
  return (
    <div className="min-h-screen bg-[#020617] text-slate-200 flex flex-col p-6 lg:p-12">
      <header className="max-w-7xl mx-auto w-full flex flex-col md:flex-row justify-between items-center mb-12 gap-8">
        <div className="flex items-center gap-6">
          <div className="w-16 h-16 bg-indigo-600 rounded-3xl flex items-center justify-center shadow-2xl shadow-indigo-600/20 rotate-3 transform hover:rotate-0 transition-transform cursor-pointer">
             <svg className="w-10 h-10 text-white -rotate-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
          </div>
          <div>
            <h1 className="text-4xl font-black text-white tracking-tighter uppercase italic leading-none">Registrar</h1>
            <div className="flex items-center gap-4 mt-2">
              <span className="flex items-center gap-2 text-indigo-400 text-[10px] font-black tracking-[0.3em] uppercase">
                <span className="w-2 h-2 bg-indigo-500 rounded-full animate-pulse" />
                Device Management
              </span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <button 
            onClick={() => setIsStandbyMode(true)}
            className="group px-8 py-4 bg-slate-900 border border-indigo-500/30 text-indigo-400 rounded-2xl text-[10px] font-black tracking-[0.2em] hover:bg-indigo-600 hover:text-white transition-all shadow-2xl flex items-center gap-3"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>
            STANDBY KIOSK
          </button>

          <div className="flex items-center gap-4 bg-slate-900/60 p-3 rounded-[24px] border border-slate-800 shadow-xl">
            <select 
              value={baudRate}
              onChange={(e) => setBaudRate(Number(e.target.value))}
              className="bg-slate-950 text-xs font-bold border-none rounded-xl px-4 py-2 outline-none"
            >
              <option value={9600}>9600 Baud</option>
              <option value={115200}>115200 Baud</option>
            </select>
            <button
              onClick={status === 'connected' ? disconnect : () => connect({ baudRate })}
              className={`px-8 py-2.5 rounded-xl text-[10px] font-black tracking-widest transition-all ${status === 'connected' ? 'bg-rose-500/10 text-rose-500 border border-rose-500/20' : 'bg-indigo-600 text-white shadow-xl shadow-indigo-600/30'}`}
            >
              {status === 'connected' ? 'DISCONNECT' : 'CONNECT'}
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto w-full grid grid-cols-1 lg:grid-cols-12 gap-10">
        <div className="lg:col-span-4 space-y-8">
          <section className="bg-slate-900/40 rounded-[40px] border border-slate-800 p-10 shadow-2xl relative overflow-hidden backdrop-blur-xl">
            <h2 className="text-[10px] font-black text-indigo-400 mb-10 uppercase tracking-[0.4em] flex items-center gap-3">
              <span className="w-1 h-5 bg-indigo-500 rounded-full" />
              Pairing Console
            </h2>
            <div className="space-y-10">
              <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] ml-1">Live Capture</label>
                <div 
                  className={`p-8 rounded-3xl border-2 transition-all duration-300 ${scanFlash ? 'scale-[1.02] border-indigo-400' : ''} ${activeRfid ? (conflictWarning ? 'bg-rose-950/20 border-rose-500/50' : 'bg-indigo-950/20 border-indigo-500/50 shadow-[inset_0_0_20px_rgba(99,102,241,0.1)]') : 'bg-slate-950/50 border-slate-800'}`}
                >
                  {activeRfid ? (
                    <div className="flex flex-col">
                      <span className={`text-[10px] font-black mb-1 tracking-widest uppercase ${conflictWarning ? 'text-rose-400' : 'text-indigo-400'}`}>
                        {conflictWarning ? 'DUPLICATE' : 'TAG DETECTED'}
                      </span>
                      <code className="text-2xl font-black text-white font-mono tracking-tighter break-all">{activeRfid}</code>
                    </div>
                  ) : (
                    <div className="text-center py-2">
                      <p className="text-[11px] font-black text-slate-700 tracking-[0.2em] animate-pulse">WAITING FOR RFID...</p>
                    </div>
                  )}
                </div>
                {conflictWarning && (
                  <p className="text-[10px] font-bold text-rose-400 px-2 leading-relaxed italic">
                    {conflictWarning}
                  </p>
                )}
              </div>

              <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] ml-1">Assigned Learner</label>
                <div className={`p-8 rounded-3xl border-2 transition-all duration-500 ${selectedLearnerId ? 'bg-indigo-950/20 border-indigo-500/30' : 'bg-slate-950/50 border-slate-800 border-dashed'}`}>
                  {selectedLearnerId ? (
                    <div className="flex items-center gap-5">
                      <div className="w-14 h-14 bg-indigo-600 text-white rounded-2xl flex items-center justify-center font-black text-xl shadow-xl shadow-indigo-500/20">
                        {learners.find(l => l.id === selectedLearnerId)?.lastName?.charAt(0)}
                      </div>
                      <div>
                        <div className="font-black text-white text-lg leading-tight">{learners.find(l => l.id === selectedLearnerId)?.firstName} {learners.find(l => l.id === selectedLearnerId)?.lastName}</div>
                        <div className="text-[10px] text-slate-500 font-bold uppercase tracking-[0.2em] mt-2">LRN: {learners.find(l => l.id === selectedLearnerId)?.lrn}</div>
                      </div>
                    </div>
                  ) : <p className="text-[11px] font-black text-slate-700 text-center py-2 tracking-widest">CHOOSE FROM DIRECTORY</p>}
                </div>
              </div>

              <button
                disabled={!activeRfid || !selectedLearnerId || !!conflictWarning}
                onClick={handleLink}
                className="w-full bg-indigo-600 hover:bg-indigo-500 disabled:opacity-10 text-white font-black py-6 rounded-[32px] shadow-2xl shadow-indigo-600/20 uppercase tracking-[0.4em] text-[10px] active:scale-95 transition-all"
              >
                SAVE TAG TO LEARNER
              </button>
            </div>
          </section>

          <section className="bg-slate-900/40 rounded-[40px] border border-slate-800 p-8 overflow-hidden backdrop-blur-md shadow-2xl">
            <h2 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] mb-6">Serial Debug</h2>
            <div className="h-48 rounded-3xl overflow-hidden border border-slate-800 bg-black/40">
              <Terminal logs={logs.slice(-30)} />
            </div>
          </section>
        </div>

        <div className="lg:col-span-8 space-y-8">
          <div className="relative group">
            <svg className="w-6 h-6 absolute left-6 top-1/2 -translate-y-1/2 text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
            <input
              type="text"
              placeholder="Instant Search Learners (Name, LRN, or Card ID)..."
              value={searchQuery}
              onChange={e => setSearchQuery(e.target.value)}
              className="w-full bg-slate-900 border border-slate-800 rounded-[32px] pl-16 pr-10 py-6 text-[15px] font-medium focus:border-indigo-500/50 outline-none transition-all shadow-2xl placeholder:text-slate-700"
            />
          </div>

          <div className="bg-slate-900/40 rounded-[48px] border border-slate-800 overflow-hidden shadow-2xl backdrop-blur-xl">
            {isInitialLoading ? (
              <div className="p-40 text-center flex flex-col items-center gap-6">
                <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin" />
                <p className="text-[11px] font-black text-slate-600 tracking-[0.4em] uppercase">Initializing Database...</p>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                  <thead>
                    <tr className="bg-slate-950/40 border-b border-slate-800">
                      <th className="p-8 text-[10px] font-black text-slate-500 uppercase tracking-[0.3em]">Student Name & LRN</th>
                      <th className="p-8 text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] text-center">RFID Assignment</th>
                      <th className="p-8 text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] text-right">Selection</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-800/50">
                    {filteredLearners.map(learner => {
                      const isLinked = !!uidMappings[learner.id];
                      const isSelected = selectedLearnerId === learner.id;
                      return (
                        <tr key={learner.id} className={`transition-all duration-300 ${isSelected ? 'bg-indigo-600/10' : 'hover:bg-slate-800/30'}`}>
                          <td className="p-8">
                            <div className="text-[16px] font-black text-white tracking-tight leading-tight">{learner.lastName}, {learner.firstName}</div>
                            <div className="text-[10px] font-bold text-slate-500 mt-2 uppercase tracking-widest">LRN: {learner.lrn}</div>
                          </td>
                          <td className="p-8 text-center">
                            {isLinked ? (
                              <span className="px-5 py-2 rounded-full bg-emerald-500/10 text-emerald-400 text-[10px] font-black border border-emerald-500/20 font-mono tracking-tighter">
                                {uidMappings[learner.id]}
                              </span>
                            ) : (
                              <span className="text-slate-800 text-[10px] font-black uppercase tracking-widest">UNASSIGNED</span>
                            )}
                          </td>
                          <td className="p-8 text-right">
                            <button 
                              onClick={() => {
                                setSelectedLearnerId(isSelected ? null : learner.id);
                                setConflictWarning(null);
                              }} 
                              className={`px-8 py-3 rounded-2xl text-[10px] font-black transition-all transform active:scale-90 tracking-widest ${
                                isSelected 
                                ? 'bg-indigo-500 text-white shadow-xl shadow-indigo-500/30' 
                                : 'bg-slate-800/80 text-slate-400 hover:text-white hover:bg-slate-700'
                              }`}
                            >
                              {isSelected ? 'SELECTED' : 'SELECT'}
                            </button>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
            {isFetchingAll && (
              <div className="p-4 bg-indigo-600/10 border-t border-indigo-500/20 text-center">
                <p className="text-[9px] font-black text-indigo-400 uppercase tracking-[0.3em]">
                  Synchronizing {fetchedCount} Records...
                </p>
              </div>
            )}
          </div>
        </div>
      </main>

      <footer className="max-w-7xl mx-auto w-full mt-12 pt-10 border-t border-slate-900/50 flex flex-col md:flex-row justify-between items-center gap-6 text-[10px] font-black text-slate-700 uppercase tracking-[0.5em]">
        <div className="flex gap-12">
          <div className="flex items-center gap-3">
            <span className="text-slate-800">ASSIGNED_TAGS:</span>
            <span className="text-indigo-400/50">{Object.keys(uidMappings).length}</span>
          </div>
          <div className="flex items-center gap-3">
            <span className="text-slate-800">DATABASE_POOL:</span>
            <span className="text-indigo-400/50">{learners.length} STUDENTS</span>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <span className={`w-2 h-2 rounded-full ${status === 'connected' ? 'bg-emerald-500' : 'bg-slate-800'}`} />
          READER_STATUS: {status.toUpperCase()}
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { useSerial } from './hooks/useSerial';
import Terminal from './components/Terminal';
import { Learner } from './types';
import { supabase } from './lib/supabase';

interface AttendanceRecord {
  learnerId: string;
  type: 'IN' | 'OUT';
  timestamp: string;
}

const App: React.FC = () => {
  const { status, logs, connect, disconnect } = useSerial();
  const [baudRate, setBaudRate] = useState(9600);
  const [isStandbyMode, setIsStandbyMode] = useState(false);

  // Database State
  const [learners, setLearners] = useState<Learner[]>([]);
  const [isInitialLoading, setIsInitialLoading] = useState(true);
  const [isFetchingAll, setIsFetchingAll] = useState(false);
  const [dbError, setDbError] = useState<string | null>(null);
  const [fetchedCount, setFetchedCount] = useState(0);

  // Registration & UI State
  const [selectedLearnerId, setSelectedLearnerId] = useState<string | null>(null);
  const [activeRfid, setActiveRfid] = useState<string>('');
  const [searchQuery, setSearchQuery] = useState('');
  const [conflictWarning, setConflictWarning] = useState<string | null>(null);
  const [scanFlash, setScanFlash] = useState(false); // Used to trigger visual refresh

  // Attendance Kiosk State
  const [lastScanResult, setLastScanResult] = useState<{
    learner: Learner;
    type: 'IN' | 'OUT';
    time: string;
    uid: string;
  } | null>(null);
  const [unknownTag, setUnknownTag] = useState<string | null>(null);

  // Local Persistence
  const [uidMappings, setUidMappings] = useState<Record<string, string>>(() => {
    const saved = localStorage.getItem('rfid_mappings');
    return saved ? JSON.parse(saved) : {};
  });

  const [attendanceLogs, setAttendanceLogs] = useState<AttendanceRecord[]>(() => {
    const saved = localStorage.getItem('attendance_logs');
    return saved ? JSON.parse(saved) : [];
  });

  // Fetch ALL learners recursively to ensure we have the full dataset locally for search
  const fetchAllLearners = useCallback(async () => {
    try {
      setIsFetchingAll(true);
      setDbError(null);
      let allData: Learner[] = [];
      let from = 0;
      const step = 1000;
      let hasMore = true;

      while (hasMore) {
        const { data, error: fetchErr } = await supabase
          .from('learners')
          .select('*')
          .range(from, from + step - 1)
          .order('lastName', { ascending: true });

        if (fetchErr) throw fetchErr;

        if (data && data.length > 0) {
          allData = [...allData, ...data];
          setLearners([...allData]); // Update UI progressively
          setFetchedCount(allData.length);
          setIsInitialLoading(false);
          hasMore = data.length === step;
          from += step;
        } else {
          hasMore = false;
        }
      }
    } catch (err: any) {
      setDbError(err.message || 'Error fetching learners.');
    } finally {
      setIsFetchingAll(false);
      setIsInitialLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchAllLearners();
  }, [fetchAllLearners]);

  // Persist local state
  useEffect(() => {
    localStorage.setItem('rfid_mappings', JSON.stringify(uidMappings));
  }, [uidMappings]);

  useEffect(() => {
    localStorage.setItem('attendance_logs', JSON.stringify(attendanceLogs));
  }, [attendanceLogs]);

  // Kiosk Auto-Reset
  useEffect(() => {
    if (lastScanResult || unknownTag) {
      const timer = setTimeout(() => {
        setLastScanResult(null);
        setUnknownTag(null);
      }, 4000);
      return () => clearTimeout(timer);
    }
  }, [lastScanResult, unknownTag]);

  // Process Serial Stream
  useEffect(() => {
    const lastLog = logs[logs.length - 1];
    if (lastLog && lastLog.type === 'in') {
      // Normalize UID: Uppercase, Trimmed, single spaces
      const scannedUid = lastLog.text.trim().toUpperCase().replace(/\s+/g, ' ');
      if (scannedUid.length < 4) return;

      if (isStandbyMode) {
        // Standby Logic
        const learnerId = Object.keys(uidMappings).find(
          id => uidMappings[id].toUpperCase() === scannedUid
        );
        const learner = learners.find(l => l.id === learnerId);

        if (learner) {
          const studentHistory = attendanceLogs.filter(log => log.learnerId === learner.id);
          const lastRecord = studentHistory[studentHistory.length - 1];
          const nextType = lastRecord?.type === 'IN' ? 'OUT' : 'IN';

          setAttendanceLogs(prev => [...prev, {
            learnerId: learner.id,
            type: nextType,
            timestamp: new Date().toISOString()
          }]);

          setLastScanResult({
            learner,
            type: nextType,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
            uid: scannedUid
          });
          setUnknownTag(null);
        } else {
          setUnknownTag(scannedUid);
          setLastScanResult(null);
        }
      } else {
        // Registration Logic Refresh
        setActiveRfid(scannedUid);
        setConflictWarning(null);
        setScanFlash(true); // Trigger animation
        setTimeout(() => setScanFlash(false), 500);

        // Immediate check for duplication
        const existingOwnerId = Object.keys(uidMappings).find(
          id => uidMappings[id].toUpperCase() === scannedUid
        );
        if (existingOwnerId) {
          const owner = learners.find(l => l.id === existingOwnerId);
          setConflictWarning(`Conflict: Tag already assigned to ${owner ? `${owner.firstName} ${owner.lastName}` : 'ID ' + existingOwnerId}`);
        }
      }
    }
  }, [logs, isStandbyMode, uidMappings, learners, attendanceLogs]);

  const handleLink = () => {
    if (!selectedLearnerId || !activeRfid || conflictWarning) return;
    setUidMappings(prev => ({ ...prev, [selectedLearnerId]: activeRfid }));
    setActiveRfid('');
    setSelectedLearnerId(null);
    setConflictWarning(null);
  };

  /**
   * IMPROVED ACCURACY SEARCH ALGORITHM
   * Uses weighted relevance scoring to show the most relevant learners first.
   */
  const filteredLearners = useMemo(() => {
    const rawQuery = searchQuery.trim().toLowerCase();
    if (!rawQuery) return learners;

    const queryTokens = rawQuery.split(/\s+/);

    return learners
      .map(learner => {
        const firstName = (learner.firstName || '').toLowerCase();
        const lastName = (learner.lastName || '').toLowerCase();
        const lrn = (learner.lrn || '').toLowerCase();
        const rfid = (uidMappings[learner.id] || '').toLowerCase();
        const fullName = `${firstName} ${lastName}`.toLowerCase();
        const reverseFullName = `${lastName} ${firstName}`.toLowerCase();

        let score = 0;

        // 1. Exact Matches (Highest Weight)
        if (lrn === rawQuery) score += 10000;
        if (rfid === rawQuery) score += 9000;
        if (fullName === rawQuery || reverseFullName === rawQuery) score += 8000;

        // 2. Prefix Matches (High Weight)
        if (lrn.startsWith(rawQuery)) score += 5000;
        if (lastName.startsWith(rawQuery)) score += 4000;
        if (firstName.startsWith(rawQuery)) score += 3000;
        if (rfid.startsWith(rawQuery)) score += 2000;

        // 3. Token-based matching (Multi-word search like "John Doe")
        // All tokens must be present somewhere in the learner's data
        const searchableText = `${fullName} ${lrn} ${rfid}`;
        const allTokensMatch = queryTokens.every(token => searchableText.includes(token));

        if (allTokensMatch) {
          score += 500;
          // Additional points for each token matching specific field prefixes
          queryTokens.forEach(token => {
            if (lastName.startsWith(token)) score += 100;
            if (firstName.startsWith(token)) score += 50;
            if (lrn.startsWith(token)) score += 50;
          });
        }

        return { learner, score };
      })
      .filter(item => item.score > 0)
      .sort((a, b) => b.score - a.score || a.learner.lastName!.localeCompare(b.learner.lastName!))
      .map(item => item.learner);
  }, [learners, searchQuery, uidMappings]);

  // STANDBY KIOSK MODE
  if (isStandbyMode) {
    return (
      <div className="fixed inset-0 bg-[#020617] text-white flex flex-col items-center justify-center p-8 z-[1000] overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-full opacity-20 pointer-events-none">
          <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-indigo-500 rounded-full blur-[160px] animate-pulse" />
          <div className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-blue-600 rounded-full blur-[160px] animate-pulse" />
        </div>

        <button 
          onClick={() => setIsStandbyMode(false)}
          className="absolute top-12 left-12 bg-slate-900/50 border border-slate-700 text-slate-400 hover:text-white px-6 py-3 rounded-2xl font-black text-[10px] tracking-[0.3em] uppercase transition-all backdrop-blur-md"
        >
          ← Exit Kiosk Mode
        </button>

        <div className="relative z-10 w-full max-w-5xl text-center">
          {!lastScanResult && !unknownTag ? (
            <div className="space-y-16 animate-in fade-in zoom-in duration-700">
              <div className="w-56 h-56 bg-indigo-600/10 rounded-[64px] border-4 border-indigo-500/20 flex items-center justify-center mx-auto shadow-[0_0_100px_rgba(79,70,229,0.1)] relative">
                <div className="absolute inset-0 bg-indigo-500/20 rounded-[64px] animate-ping opacity-40" />
                <svg className="w-28 h-28 text-indigo-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M12 12h4.01M16 20h4M4 12h4m12 0h.01M5 8h2a1 1 0 001-1V5a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1zm12 0h2a1 1 0 001-1V5a1 1 0 00-1-1h-2a1 1 0 00-1 1v2a1 1 0 001 1zM5 17h2a1 1 0 001-1v-2a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1z" />
                </svg>
              </div>
              <div className="space-y-4">
                <h2 className="text-8xl font-black tracking-tighter uppercase italic text-white drop-shadow-2xl">Ready to Scan</h2>
                <p className="text-xl font-bold text-slate-500 tracking-[0.5em] uppercase">Please tap your RFID card</p>
              </div>
            </div>
          ) : lastScanResult ? (
            <div className="space-y-12 animate-in slide-in-from-bottom-20 duration-500">
              <div className={`text-[180px] font-black leading-none tracking-tighter uppercase italic drop-shadow-2xl ${lastScanResult.type === 'IN' ? 'text-emerald-400' : 'text-amber-400'}`}>
                {lastScanResult.type}
              </div>
              <div className="space-y-6">
                <h3 className="text-7xl font-black text-white">{lastScanResult.learner.firstName} {lastScanResult.learner.lastName}</h3>
                <div className="flex flex-col items-center gap-2">
                  <p className="text-3xl font-black text-indigo-400/80 tracking-widest">{lastScanResult.time}</p>
                  <code className="text-slate-600 font-mono text-xs uppercase tracking-[0.5em] mt-2">{lastScanResult.uid}</code>
                </div>
              </div>
              <div className={`inline-flex items-center gap-6 px-16 py-8 rounded-[40px] border-4 font-black text-4xl tracking-widest ${lastScanResult.type === 'IN' ? 'border-emerald-500/20 bg-emerald-500/5 text-emerald-400' : 'border-amber-500/20 bg-amber-500/5 text-amber-400'}`}>
                <span className="w-4 h-4 rounded-full bg-current animate-pulse" />
                CONFIRMED
              </div>
            </div>
          ) : (
            <div className="space-y-12 animate-in shake duration-500">
               <div className="text-[140px] font-black leading-none tracking-tighter uppercase italic text-rose-500">UNKNOWN</div>
              <div className="space-y-4">
                <h3 className="text-5xl font-black text-white">UID: {unknownTag}</h3>
                <p className="text-2xl font-bold text-slate-500 uppercase tracking-widest">Card not found in database</p>
              </div>
              <div className="inline-flex items-center gap-6 px-16 py-8 rounded-[40px] border-4 border-rose-500/20 bg-rose-500/5 text-rose-500 font-black text-3xl tracking-widest">
                <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                ACCESS DENIED
              </div>
            </div>
          )}
        </div>

        <div className="absolute bottom-12 flex gap-12 text-[10px] font-black text-slate-700 tracking-[0.5em] uppercase">
          <div className="flex items-center gap-3">
            <span className={`w-2 h-2 rounded-full ${status === 'connected' ? 'bg-emerald-500' : 'bg-rose-500'}`} />
            READER: {status}
          </div>
          <span>•</span>
          <div className="flex items-center gap-3">
            <span className="w-2 h-2 rounded-full bg-indigo-500" />
            POOL: {learners.length} STUDENTS
          </div>
        </div>
      </div>
    );
  }

  // REGISTRATION MODE UI
  return (
    <div className="min-h-screen bg-[#020617] text-slate-200 flex flex-col p-6 lg:p-12">
      <header className="max-w-7xl mx-auto w-full flex flex-col md:flex-row justify-between items-center mb-12 gap-8">
        <div className="flex items-center gap-6">
          <div className="w-16 h-16 bg-indigo-600 rounded-3xl flex items-center justify-center shadow-2xl shadow-indigo-600/20 rotate-3 transform hover:rotate-0 transition-transform cursor-pointer">
             <svg className="w-10 h-10 text-white -rotate-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
          </div>
          <div>
            <h1 className="text-4xl font-black text-white tracking-tighter uppercase italic leading-none">Registrar</h1>
            <div className="flex items-center gap-4 mt-2">
              <span className="flex items-center gap-2 text-indigo-400 text-[10px] font-black tracking-[0.3em] uppercase">
                <span className="w-2 h-2 bg-indigo-500 rounded-full animate-pulse" />
                Device Management
              </span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <button 
            onClick={() => setIsStandbyMode(true)}
            className="group px-8 py-4 bg-slate-900 border border-indigo-500/30 text-indigo-400 rounded-2xl text-[10px] font-black tracking-[0.2em] hover:bg-indigo-600 hover:text-white transition-all shadow-2xl flex items-center gap-3"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>
            STANDBY KIOSK
          </button>

          <div className="flex items-center gap-4 bg-slate-900/60 p-3 rounded-[24px] border border-slate-800 shadow-xl">
            <select 
              value={baudRate}
              onChange={(e) => setBaudRate(Number(e.target.value))}
              className="bg-slate-950 text-xs font-bold border-none rounded-xl px-4 py-2 outline-none"
            >
              <option value={9600}>9600 Baud</option>
              <option value={115200}>115200 Baud</option>
            </select>
            <button
              onClick={status === 'connected' ? disconnect : () => connect({ baudRate })}
              className={`px-8 py-2.5 rounded-xl text-[10px] font-black tracking-widest transition-all ${status === 'connected' ? 'bg-rose-500/10 text-rose-500 border border-rose-500/20' : 'bg-indigo-600 text-white shadow-xl shadow-indigo-600/30'}`}
            >
              {status === 'connected' ? 'DISCONNECT' : 'CONNECT'}
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto w-full grid grid-cols-1 lg:grid-cols-12 gap-10">
        <div className="lg:col-span-4 space-y-8">
          <section className="bg-slate-900/40 rounded-[40px] border border-slate-800 p-10 shadow-2xl relative overflow-hidden backdrop-blur-xl">
            <h2 className="text-[10px] font-black text-indigo-400 mb-10 uppercase tracking-[0.4em] flex items-center gap-3">
              <span className="w-1 h-5 bg-indigo-500 rounded-full" />
              Pairing Console
            </h2>
            <div className="space-y-10">
              <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] ml-1">Live Capture</label>
                <div 
                  className={`p-8 rounded-3xl border-2 transition-all duration-300 ${scanFlash ? 'scale-[1.02] border-indigo-400' : ''} ${activeRfid ? (conflictWarning ? 'bg-rose-950/20 border-rose-500/50' : 'bg-indigo-950/20 border-indigo-500/50 shadow-[inset_0_0_20px_rgba(99,102,241,0.1)]') : 'bg-slate-950/50 border-slate-800'}`}
                >
                  {activeRfid ? (
                    <div className="flex flex-col">
                      <span className={`text-[10px] font-black mb-1 tracking-widest uppercase ${conflictWarning ? 'text-rose-400' : 'text-indigo-400'}`}>
                        {conflictWarning ? 'DUPLICATE' : 'TAG DETECTED'}
                      </span>
                      <code className="text-2xl font-black text-white font-mono tracking-tighter break-all">{activeRfid}</code>
                    </div>
                  ) : (
                    <div className="text-center py-2">
                      <p className="text-[11px] font-black text-slate-700 tracking-[0.2em] animate-pulse">WAITING FOR RFID...</p>
                    </div>
                  )}
                </div>
                {conflictWarning && (
                  <p className="text-[10px] font-bold text-rose-400 px-2 leading-relaxed italic">
                    {conflictWarning}
                  </p>
                )}
              </div>

              <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] ml-1">Assigned Learner</label>
                <div className={`p-8 rounded-3xl border-2 transition-all duration-500 ${selectedLearnerId ? 'bg-indigo-950/20 border-indigo-500/30' : 'bg-slate-950/50 border-slate-800 border-dashed'}`}>
                  {selectedLearnerId ? (
                    <div className="flex items-center gap-5">
                      <div className="w-14 h-14 bg-indigo-600 text-white rounded-2xl flex items-center justify-center font-black text-xl shadow-xl shadow-indigo-500/20">
                        {learners.find(l => l.id === selectedLearnerId)?.lastName?.charAt(0)}
                      </div>
                      <div>
                        <div className="font-black text-white text-lg leading-tight">{learners.find(l => l.id === selectedLearnerId)?.firstName} {learners.find(l => l.id === selectedLearnerId)?.lastName}</div>
                        <div className="text-[10px] text-slate-500 font-bold uppercase tracking-[0.2em] mt-2">LRN: {learners.find(l => l.id === selectedLearnerId)?.lrn}</div>
                      </div>
                    </div>
                  ) : <p className="text-[11px] font-black text-slate-700 text-center py-2 tracking-widest">CHOOSE FROM DIRECTORY</p>}
                </div>
              </div>

              <button
                disabled={!activeRfid || !selectedLearnerId || !!conflictWarning}
                onClick={handleLink}
                className="w-full bg-indigo-600 hover:bg-indigo-500 disabled:opacity-10 text-white font-black py-6 rounded-[32px] shadow-2xl shadow-indigo-600/20 uppercase tracking-[0.4em] text-[10px] active:scale-95 transition-all"
              >
                SAVE TAG TO LEARNER
              </button>
            </div>
          </section>

          <section className="bg-slate-900/40 rounded-[40px] border border-slate-800 p-8 overflow-hidden backdrop-blur-md shadow-2xl">
            <h2 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] mb-6">Serial Debug</h2>
            <div className="h-48 rounded-3xl overflow-hidden border border-slate-800 bg-black/40">
              <Terminal logs={logs.slice(-30)} />
            </div>
          </section>
        </div>

        <div className="lg:col-span-8 space-y-8">
          <div className="relative group">
            <svg className="w-6 h-6 absolute left-6 top-1/2 -translate-y-1/2 text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
            <input
              type="text"
              placeholder="Search by Name, LRN, or Assigned Card..."
              value={searchQuery}
              onChange={e => setSearchQuery(e.target.value)}
              className="w-full bg-slate-900 border border-slate-800 rounded-[32px] pl-16 pr-10 py-6 text-[15px] font-medium focus:border-indigo-500/50 outline-none transition-all shadow-2xl placeholder:text-slate-700"
            />
          </div>

          <div className="bg-slate-900/40 rounded-[48px] border border-slate-800 overflow-hidden shadow-2xl backdrop-blur-xl">
            {isInitialLoading ? (
              <div className="p-40 text-center flex flex-col items-center gap-6">
                <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin" />
                <p className="text-[11px] font-black text-slate-600 tracking-[0.4em] uppercase">Initializing Database...</p>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                  <thead>
                    <tr className="bg-slate-950/40 border-b border-slate-800">
                      <th className="p-8 text-[10px] font-black text-slate-500 uppercase tracking-[0.3em]">Student Name & LRN</th>
                      <th className="p-8 text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] text-center">RFID Assignment</th>
                      <th className="p-8 text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] text-right">Selection</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-800/50">
                    {filteredLearners.map(learner => {
                      const isLinked = !!uidMappings[learner.id];
                      const isSelected = selectedLearnerId === learner.id;
                      return (
                        <tr key={learner.id} className={`transition-all duration-300 ${isSelected ? 'bg-indigo-600/10' : 'hover:bg-slate-800/30'}`}>
                          <td className="p-8">
                            <div className="text-[16px] font-black text-white tracking-tight leading-tight">{learner.lastName}, {learner.firstName}</div>
                            <div className="text-[10px] font-bold text-slate-500 mt-2 uppercase tracking-widest">LRN: {learner.lrn}</div>
                          </td>
                          <td className="p-8 text-center">
                            {isLinked ? (
                              <span className="px-5 py-2 rounded-full bg-emerald-500/10 text-emerald-400 text-[10px] font-black border border-emerald-500/20 font-mono tracking-tighter">
                                {uidMappings[learner.id]}
                              </span>
                            ) : (
                              <span className="text-slate-800 text-[10px] font-black uppercase tracking-widest">UNASSIGNED</span>
                            )}
                          </td>
                          <td className="p-8 text-right">
                            <button 
                              onClick={() => {
                                setSelectedLearnerId(isSelected ? null : learner.id);
                                setConflictWarning(null);
                              }} 
                              className={`px-8 py-3 rounded-2xl text-[10px] font-black transition-all transform active:scale-90 tracking-widest ${
                                isSelected 
                                ? 'bg-indigo-500 text-white shadow-xl shadow-indigo-500/30' 
                                : 'bg-slate-800/80 text-slate-400 hover:text-white hover:bg-slate-700'
