                              {isSelected ? 'SELECTED' : 'SELECT'}
                            </button>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
            {isFetchingAll && (
              <div className="p-4 bg-indigo-600/10 border-t border-indigo-500/20 text-center">
                <p className="text-[9px] font-black text-indigo-400 uppercase tracking-[0.3em]">
                  Synchronizing {fetchedCount} Records...
                </p>
              </div>
            )}
          </div>
        </div>
      </main>

      <footer className="max-w-7xl mx-auto w-full mt-12 pt-10 border-t border-slate-900/50 flex flex-col md:flex-row justify-between items-center gap-6 text-[10px] font-black text-slate-700 uppercase tracking-[0.5em]">
        <div className="flex gap-12">
          <div className="flex items-center gap-3">
            <span className="text-slate-800">ASSIGNED_TAGS:</span>
            <span className="text-indigo-400/50">{Object.keys(uidMappings).length}</span>
          </div>
          <div className="flex items-center gap-3">
