import { useState, useCallback, useRef, useEffect } from 'react';
import { SerialLog, ConnectionStatus, SerialOptions, SerialPort } from '../types';

export const useSerial = () => {
  const [status, setStatus] = useState<ConnectionStatus>('disconnected');
  const [logs, setLogs] = useState<SerialLog[]>([]);
  const [port, setPort] = useState<SerialPort | null>(null);
  const [error, setError] = useState<string | null>(null);

  const readerRef = useRef<ReadableStreamDefaultReader<string> | null>(null);
  const writerRef = useRef<WritableStreamDefaultWriter<string> | null>(null);
  const portRef = useRef<any>(null);

  const addLog = useCallback((text: string, type: SerialLog['type']) => {
    const newLog: SerialLog = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date(),
      type,
      text
    };
    setLogs(prev => [...prev.slice(-999), newLog]);
  }, []);

  const disconnect = useCallback(async () => {
    setStatus('disconnected');
    const p = portRef.current;
    portRef.current = null;

    try {
      if (readerRef.current) {
        // Cancel the reader to unlock the stream before closing the port
        await readerRef.current.cancel().catch(() => {});
        readerRef.current = null;
      }
      if (writerRef.current) {
        await writerRef.current.close().catch(() => {});
        writerRef.current = null;
      }
      if (p) {
        await p.close().catch(() => {});
      }
    } catch (e) {
      console.error("Cleanup error:", e);
    }

    setPort(null);
    addLog('Disconnected from port.', 'info');
  }, [addLog]);

  const startReading = useCallback(async (selectedPort: any) => {
    const textDecoder = new TextDecoderStream();
    const readableStreamClosed = selectedPort.readable.pipeTo(textDecoder.writable);
    const reader = textDecoder.readable.getReader();
    readerRef.current = reader;

    const textEncoder = new TextEncoderStream();
    textEncoder.readable.pipeTo(selectedPort.writable);
    const writer = textEncoder.writable.getWriter();
    writerRef.current = writer;

    let buffer = '';
    try {
      while (true) {
        const { value, done } = await reader.read();
        if (done) break;

        buffer += value;
        const lines = buffer.split(/\r?\n/);
        buffer = lines.pop() || ''; 

        for (const line of lines) {
          const trimmed = line.trim();
          if (trimmed) {
            addLog(trimmed, 'in');
          }
        }
      }
    } catch (err: any) {
      if (err.name !== 'AbortError') {
        console.error('Read error:', err);
        addLog(`Read error: ${err.message}`, 'error');
        setStatus('error');
      }
    } finally {
      reader.releaseLock();
    }
  }, [addLog]);

  const connect = useCallback(async (options: SerialOptions, existingPort?: any) => {
    if (!('serial' in navigator)) {
      setError('Web Serial API is not supported in this browser.');
      return;
    }

    try {
      // Ensure any existing connection is closed first to avoid "Port already open"
      if (portRef.current) {
        await disconnect();
      }

      setError(null);
      setStatus('connecting');

      const selectedPort = existingPort || await (navigator as any).serial.requestPort();

      try {
        await selectedPort.open({ baudRate: options.baudRate });
        localStorage.setItem('serial_baud', options.baudRate.toString());
      } catch (openErr: any) {
        if (openErr.name === 'NetworkError' || openErr.message.includes('busy')) {
          throw new Error('Serial Port is BUSY. Close other apps using this port.');
        }
        if (openErr.message.includes('already open')) {
           // If somehow still says open, we try to proceed or force cleanup
           console.warn('Port was already open, continuing...');
        } else {
          throw openErr;
        }
      }

      portRef.current = selectedPort;
      setPort(selectedPort);
      setStatus('connected');
      addLog(`Connected at ${options.baudRate} baud.`, 'info');

      startReading(selectedPort);

    } catch (err: any) {
      console.error('Connection failed:', err);
      const msg = err.message || 'Failed to connect to the serial port.';
      setError(msg);
      setStatus('disconnected');
      addLog(`Connection failed: ${msg}`, 'error');
    }
  }, [addLog, startReading, disconnect]);

  useEffect(() => {
    const autoReconnect = async () => {
      if ('serial' in navigator) {
        try {
          const ports = await (navigator as any).serial.getPorts();
          if (ports.length > 0) {
            const savedBaud = localStorage.getItem('serial_baud');
            const baud = savedBaud ? parseInt(savedBaud) : 9600;
            addLog(`Found authorized port. Reconnecting...`, 'info');
            connect({ baudRate: baud }, ports[0]);
          }
        } catch (err) {
          console.debug('Auto-reconnect skipped:', err);
        }
      }
    };
    autoReconnect();
  }, [connect, addLog]);

  const sendData = useCallback(async (data: string) => {
    if (!writerRef.current) return;
    try {
      await writerRef.current.write(data);
      addLog(data, 'out');
    } catch (err: any) {
      addLog(`Write error: ${err.message}`, 'error');
    }
  }, [addLog]);

  const clearLogs = useCallback(() => setLogs([]), []);
  const clearError = useCallback(() => setError(null), []);

  return {
    status,
    logs,
    connect,
    disconnect,
    sendData,
    clearLogs,
    clearError,
    error
  };
};

