  const [dbError, setDbError] = useState<string | null>(null);
  const [fetchedCount, setFetchedCount] = useState(0);

  // Registration & UI State
  const [selectedLearnerId, setSelectedLearnerId] = useState<string | null>(null);
  const [activeRfid, setActiveRfid] = useState<string>('');
  const [searchQuery, setSearchQuery] = useState('');
  const [conflictWarning, setConflictWarning] = useState<string | null>(null);
  const [scanFlash, setScanFlash] = useState(false);

  // Prevent re-processing the same serial line during state updates
  const lastProcessedLogId = useRef<string | null>(null);

  // Attendance Kiosk State
  const [lastScanResult, setLastScanResult] = useState<{
    learner: Learner;
    type: 'IN' | 'OUT';
    time: string;
    uid: string;
  } | null>(null);
  const [unknownTag, setUnknownTag] = useState<string | null>(null);

  // Local Persistence
  const [uidMappings, setUidMappings] = useState<Record<string, string>>(() => {
    const saved = localStorage.getItem('rfid_mappings');
    return saved ? JSON.parse(saved) : {};
  });

  const [attendanceLogs, setAttendanceLogs] = useState<AttendanceRecord[]>(() => {
    const saved = localStorage.getItem('attendance_logs');
    return saved ? JSON.parse(saved) : [];
  });

  // HELPER: Validate if the text is a real UID (Hex/Digits) and not a status message
  const isValidUid = (text: string) => {
    const clean = text.trim().toUpperCase();
    // Regex: Only allow Hex characters (0-9, A-F) and spaces/dashes
    const hexRegex = /^[0-9A-F\s-]+$/;
    // Blacklist common serial status words
    const statusWords = ['READY', 'RFID', 'SUCCESS', 'WAIT', 'ERROR', 'CONNECTED', 'START', 'READING'];
    const isStatusMessage = statusWords.some(word => clean.includes(word));

    return clean.length >= 4 && hexRegex.test(clean) && !isStatusMessage;
  };

  // FETCH: Stable sort + Local ID Filtering + Smooth Progress Delay
  const fetchAllLearners = useCallback(async () => {
    if (isFetchingAll) return;
    try {
      setIsFetchingAll(true);
      setDbError(null);
      let allData: Learner[] = [];
      let from = 0;
      const step = 1000;
      let hasMore = true;

      while (hasMore) {
        const { data, error: fetchErr } = await supabase
          .from('learners')
          .select('*')
          .range(from, from + step - 1)
          .order('lastName', { ascending: true })
          .order('id', { ascending: true });

        if (fetchErr) throw fetchErr;

        if (data && data.length > 0) {
          const currentIds = new Set(allData.map(l => l.id));
          const newUniqueRecords = data.filter(l => !currentIds.has(l.id));

          allData = [...allData, ...newUniqueRecords];
          setLearners([...allData]); 
          setFetchedCount(allData.length);
          setIsInitialLoading(false);
          hasMore = data.length === step;
          from += step;

          // Artificial delay to allow React to paint the progress chunks
          await new Promise(resolve => setTimeout(resolve, 80));
        } else {
          hasMore = false;
        }
      }
    } catch (err: any) {
      setDbError(err.message || 'Error fetching learners.');
    } finally {
      setIsFetchingAll(false);
      setIsInitialLoading(false);
    }
  }, [isFetchingAll]);

  useEffect(() => {
    fetchAllLearners();
  }, [fetchAllLearners]);

  useEffect(() => {
    localStorage.setItem('rfid_mappings', JSON.stringify(uidMappings));
  }, [uidMappings]);

  useEffect(() => {
    localStorage.setItem('attendance_logs', JSON.stringify(attendanceLogs));
  }, [attendanceLogs]);

  // Serial Stream Processing
  useEffect(() => {
    const lastLog = logs[logs.length - 1];

    // Safety check: Only process input, and only process each ID once
    if (!lastLog || lastLog.type !== 'in' || lastLog.id === lastProcessedLogId.current) return;

    const rawText = lastLog.text.trim();
    if (!isValidUid(rawText)) return; // Ignore status messages like "RFID READY"

    lastProcessedLogId.current = lastLog.id;
    const scannedUid = rawText.toUpperCase().replace(/\s+/g, ' ');

    if (isStandbyMode) {
      const learnerId = Object.keys(uidMappings).find(
        id => uidMappings[id]?.toUpperCase() === scannedUid
      );
      const learner = learners.find(l => l.id === learnerId);

      if (learner) {
        const studentHistory = attendanceLogs.filter(log => log.learnerId === learner.id);
        const lastRecord = studentHistory[studentHistory.length - 1];
        const nextType = lastRecord?.type === 'IN' ? 'OUT' : 'IN';

        setAttendanceLogs(prev => [...prev, {
          learnerId: learner.id,
          type: nextType,
          timestamp: new Date().toISOString()
        }]);

        setLastScanResult({
          learner,
          type: nextType,
          time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
          uid: scannedUid
        });
        setUnknownTag(null);
      } else {
        setUnknownTag(scannedUid);
        setLastScanResult(null);
      }
    } else {
      // REGISTRATION MODE: Trigger visual refresh
      setScanFlash(true);
      setActiveRfid(scannedUid);
      setConflictWarning(null);

      // Conflict Check: Check if this UID is already assigned
      const existingOwnerId = Object.keys(uidMappings).find(
        id => uidMappings[id]?.toUpperCase() === scannedUid
      );

      if (existingOwnerId) {
        const owner = learners.find(l => l.id === existingOwnerId);
        setConflictWarning(`Conflict: Tag already assigned to ${owner ? `${owner.firstName} ${owner.lastName}` : 'another student'}`);
      }

      setTimeout(() => setScanFlash(false), 500);
    }
  }, [logs, isStandbyMode, uidMappings, learners, attendanceLogs]);

  const handleLink = () => {
    if (!selectedLearnerId || !activeRfid || conflictWarning) return;

    // Save mapping
    setUidMappings(prev => ({ ...prev, [selectedLearnerId]: activeRfid }));

    // FULL REFRESH: Clear capture state and selections immediately
    setScanFlash(true);
    setActiveRfid('');
    setSelectedLearnerId(null);
    setConflictWarning(null);

    setTimeout(() => {
      setScanFlash(false);
    }, 400);
  };

  const filteredLearners = useMemo(() => {
    const rawQuery = searchQuery.trim().toLowerCase();
    if (!rawQuery) return learners;

    const queryTokens = rawQuery.split(/\s+/).filter(t => t.length > 0);
    if (queryTokens.length === 0) return learners;

    return learners
      .map(learner => {
        const firstName = (learner.firstName || '').toLowerCase();
        const lastName = (learner.lastName || '').toLowerCase();
        const lrn = (learner.lrn || '').toLowerCase();
        const rfid = (uidMappings[learner.id] || '').toLowerCase();
        const fullName = `${firstName} ${lastName}`.toLowerCase();
        const reverseFullName = `${lastName} ${firstName}`.toLowerCase();

        let score = 0;
        if (lrn === rawQuery) score += 10000;
        if (rfid === rawQuery) score += 9000;
        if (fullName === rawQuery || reverseFullName === rawQuery) score += 8000;
        if (lrn.startsWith(rawQuery)) score += 5000;
        if (lastName.startsWith(rawQuery)) score += 4000;
        if (firstName.startsWith(rawQuery)) score += 3000;

        const searchableText = `${fullName} ${reverseFullName} ${lrn} ${rfid}`;
        const allTokensFound = queryTokens.every(token => searchableText.includes(token));

        if (allTokensFound) {
          score += 500;
          queryTokens.forEach(token => {
            if (lastName.startsWith(token)) score += 100;
            if (firstName.startsWith(token)) score += 50;
          });
        }
        return { learner, score };
      })
      .filter(item => item.score > 0)
      .sort((a, b) => b.score - a.score || (a.learner.lastName || '').localeCompare(b.learner.lastName || ''))
      .map(item => item.learner);
  }, [learners, searchQuery, uidMappings]);

  if (isStandbyMode) {
    return (
      <div className="fixed inset-0 bg-[#020617] text-white flex flex-col items-center justify-center p-8 z-[1000] overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-full opacity-20 pointer-events-none">
          <div className="absolute top-1/4 left-1/4 w-96 h-96 bg-indigo-500 rounded-full blur-[160px] animate-pulse" />
          <div className="absolute bottom-1/4 right-1/4 w-96 h-96 bg-blue-600 rounded-full blur-[160px] animate-pulse" />
        </div>

        <button 
          onClick={() => setIsStandbyMode(false)}
          className="absolute top-12 left-12 bg-slate-900/50 border border-slate-700 text-slate-400 hover:text-white px-6 py-3 rounded-2xl font-black text-[10px] tracking-[0.3em] uppercase transition-all backdrop-blur-md"
        >
          ← Exit Kiosk Mode
        </button>

        <div className="relative z-10 w-full max-w-5xl text-center">
          {!lastScanResult && !unknownTag ? (
            <div className="space-y-16 animate-in fade-in zoom-in duration-700">
              <div className="w-56 h-56 bg-indigo-600/10 rounded-[64px] border-4 border-indigo-500/20 flex items-center justify-center mx-auto shadow-[0_0_100px_rgba(79,70,229,0.1)] relative">
                <div className="absolute inset-0 bg-indigo-500/20 rounded-[64px] animate-ping opacity-40" />
                <svg className="w-28 h-28 text-indigo-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3m0 0h.01M12 12h4.01M16 20h4M4 12h4m12 0h.01M5 8h2a1 1 0 001-1V5a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1zm12 0h2a1 1 0 001-1V5a1 1 0 00-1-1h-2a1 1 0 00-1 1v2a1 1 0 001 1zM5 17h2a1 1 0 001-1v-2a1 1 0 00-1-1H5a1 1 0 00-1 1v2a1 1 0 001 1z" />
                </svg>
              </div>
              <div className="space-y-4">
                <h2 className="text-8xl font-black tracking-tighter uppercase italic text-white drop-shadow-2xl">Ready to Scan</h2>
                <p className="text-xl font-bold text-slate-500 tracking-[0.5em] uppercase">Please tap your RFID card</p>
              </div>
            </div>
          ) : lastScanResult ? (
            <div className="space-y-12 animate-in slide-in-from-bottom-20 duration-500">
              <div className={`text-[180px] font-black leading-none tracking-tighter uppercase italic drop-shadow-2xl ${lastScanResult.type === 'IN' ? 'text-emerald-400' : 'text-amber-400'}`}>
                {lastScanResult.type}
              </div>
              <div className="space-y-6">
                <h3 className="text-7xl font-black text-white">{lastScanResult.learner.firstName} {lastScanResult.learner.lastName}</h3>
                <div className="flex flex-col items-center gap-2">
                  <p className="text-3xl font-black text-indigo-400/80 tracking-widest">{lastScanResult.time}</p>
                  <code className="text-slate-600 font-mono text-xs uppercase tracking-[0.5em] mt-2">{lastScanResult.uid}</code>
                </div>
              </div>
              <div className={`inline-flex items-center gap-6 px-16 py-8 rounded-[40px] border-4 font-black text-4xl tracking-widest ${lastScanResult.type === 'IN' ? 'border-emerald-500/20 bg-emerald-500/5 text-emerald-400' : 'border-amber-500/20 bg-amber-500/5 text-amber-400'}`}>
                <span className="w-4 h-4 rounded-full bg-current animate-pulse" />
                CONFIRMED
              </div>
            </div>
          ) : (
            <div className="space-y-12 animate-in shake duration-500">
               <div className="text-[140px] font-black leading-none tracking-tighter uppercase italic text-rose-500">UNKNOWN</div>
              <div className="space-y-4">
                <h3 className="text-5xl font-black text-white">UID: {unknownTag}</h3>
                <p className="text-2xl font-bold text-slate-500 uppercase tracking-widest">Card not found in database</p>
              </div>
              <div className="inline-flex items-center gap-6 px-16 py-8 rounded-[40px] border-4 border-rose-500/20 bg-rose-500/5 text-rose-500 font-black text-3xl tracking-widest">
                <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                ACCESS DENIED
              </div>
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#020617] text-slate-200 flex flex-col p-6 lg:p-12">
      <header className="max-w-7xl mx-auto w-full flex flex-col md:flex-row justify-between items-center mb-12 gap-8">
        <div className="flex items-center gap-6">
          <div className="w-16 h-16 bg-indigo-600 rounded-3xl flex items-center justify-center shadow-2xl shadow-indigo-600/20 rotate-3 transform hover:rotate-0 transition-transform cursor-pointer">
             <svg className="w-10 h-10 text-white -rotate-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
          </div>
          <div>
            <h1 className="text-4xl font-black text-white tracking-tighter uppercase italic leading-none">Registrar</h1>
            <div className="flex items-center gap-4 mt-2">
              <span className="flex items-center gap-2 text-indigo-400 text-[10px] font-black tracking-[0.3em] uppercase">
                <span className="w-2 h-2 bg-indigo-500 rounded-full animate-pulse" />
                Device Management
              </span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <button 
            onClick={() => setIsStandbyMode(true)}
            className="group px-8 py-4 bg-slate-900 border border-indigo-500/30 text-indigo-400 rounded-2xl text-[10px] font-black tracking-[0.2em] hover:bg-indigo-600 hover:text-white transition-all shadow-2xl flex items-center gap-3"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>
            STANDBY KIOSK
          </button>

          <div className="flex items-center gap-4 bg-slate-900/60 p-3 rounded-[24px] border border-slate-800 shadow-xl">
            <select 
              value={baudRate}
              onChange={(e) => {
                const b = Number(e.target.value);
                setBaudRate(b);
              }}
              className="bg-slate-950 text-xs font-bold border-none rounded-xl px-4 py-2 outline-none cursor-pointer"
            >
              <option value={9600}>9600 Baud</option>
              <option value={115200}>115200 Baud</option>
            </select>
            <button
              onClick={status === 'connected' ? disconnect : () => connect({ baudRate })}
              className={`px-8 py-2.5 rounded-xl text-[10px] font-black tracking-widest transition-all ${status === 'connected' ? 'bg-rose-500/10 text-rose-500 border border-rose-500/20' : 'bg-indigo-600 text-white shadow-xl shadow-indigo-600/30'}`}
            >
              {status === 'connected' ? 'DISCONNECT' : 'CONNECT'}
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto w-full grid grid-cols-1 lg:grid-cols-12 gap-10">
        <div className="lg:col-span-4 space-y-8">
          <section className="bg-slate-900/40 rounded-[40px] border border-slate-800 p-10 shadow-2xl relative overflow-hidden backdrop-blur-xl">
            <h2 className="text-[10px] font-black text-indigo-400 mb-10 uppercase tracking-[0.4em] flex items-center gap-3">
              <span className="w-1 h-5 bg-indigo-500 rounded-full" />
              Pairing Console
            </h2>
            <div className="space-y-10">
              <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] ml-1">Live Capture</label>
                <div 
                  className={`p-8 rounded-3xl border-2 transition-all duration-300 ${scanFlash ? 'scale-[1.02] border-indigo-400 shadow-[0_0_30px_rgba(99,102,241,0.2)]' : ''} ${activeRfid ? (conflictWarning ? 'bg-rose-950/20 border-rose-500/50' : 'bg-indigo-950/20 border-indigo-500/50 shadow-[inset_0_0_20px_rgba(99,102,241,0.1)]') : 'bg-slate-950/50 border-slate-800'}`}
                >
                  {activeRfid ? (
                    <div className="flex flex-col">
                      <span className={`text-[10px] font-black mb-1 tracking-widest uppercase ${conflictWarning ? 'text-rose-400' : 'text-indigo-400'}`}>
                        {conflictWarning ? 'DUPLICATE' : 'TAG DETECTED'}
                      </span>
                      <code className="text-2xl font-black text-white font-mono tracking-tighter break-all">{activeRfid}</code>
                    </div>
                  ) : (
                    <div className="text-center py-2">
                      <p className="text-[11px] font-black text-slate-700 tracking-[0.2em] animate-pulse">WAITING FOR RFID...</p>
                    </div>
                  )}
                </div>
                {conflictWarning && (
                  <p className="text-[10px] font-bold text-rose-400 px-2 leading-relaxed italic">
                    {conflictWarning}
                  </p>
                )}
              </div>

              <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] ml-1">Assigned Learner</label>
                <div className={`p-8 rounded-3xl border-2 transition-all duration-500 ${selectedLearnerId ? 'bg-indigo-950/20 border-indigo-500/30 shadow-[inset_0_0_15px_rgba(99,102,241,0.05)]' : 'bg-slate-950/50 border-slate-800 border-dashed'}`}>
                  {selectedLearnerId ? (
                    <div className="flex items-center gap-5">
                      <div className="w-14 h-14 bg-indigo-600 text-white rounded-2xl flex items-center justify-center font-black text-xl shadow-xl shadow-indigo-500/20">
                        {learners.find(l => l.id === selectedLearnerId)?.lastName?.charAt(0)}
                      </div>
                      <div>
                        <div className="font-black text-white text-lg leading-tight uppercase italic">{learners.find(l => l.id === selectedLearnerId)?.lastName}, {learners.find(l => l.id === selectedLearnerId)?.firstName}</div>
                        <div className="text-[10px] text-slate-500 font-bold uppercase tracking-[0.2em] mt-2">LRN: {learners.find(l => l.id === selectedLearnerId)?.lrn || 'N/A'}</div>
                      </div>
                    </div>
                  ) : <p className="text-[11px] font-black text-slate-700 text-center py-2 tracking-widest">CHOOSE FROM DIRECTORY</p>}
                </div>
              </div>

              <button
                disabled={!activeRfid || !selectedLearnerId || !!conflictWarning}
                onClick={handleLink}
                className="w-full bg-indigo-600 hover:bg-indigo-500 disabled:opacity-20 text-white font-black py-6 rounded-[32px] shadow-2xl shadow-indigo-600/20 uppercase tracking-[0.4em] text-[10px] active:scale-95 transition-all"
              >
                SAVE TAG TO LEARNER
              </button>
            </div>
          </section>

          <section className="bg-slate-900/40 rounded-[40px] border border-slate-800 p-8 overflow-hidden backdrop-blur-md shadow-2xl">
            <h2 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] mb-6">Serial Debug</h2>
            <div className="h-48 rounded-3xl overflow-hidden border border-slate-800 bg-black/40">
              <Terminal logs={logs.slice(-30)} />
            </div>
          </section>
        </div>

        <div className="lg:col-span-8 space-y-8">
          <div className="relative group">
            <svg className="w-6 h-6 absolute left-6 top-1/2 -translate-y-1/2 text-slate-600 transition-colors group-focus-within:text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
            <input
              type="text"
              placeholder="Search by Name, LRN, or Assigned Card..."
              value={searchQuery}
              onChange={e => setSearchQuery(e.target.value)}
              className="w-full bg-slate-900 border border-slate-800 rounded-[32px] pl-16 pr-10 py-6 text-[15px] font-medium focus:border-indigo-500/50 focus:ring-4 focus:ring-indigo-500/5 outline-none transition-all shadow-2xl placeholder:text-slate-700"
            />
          </div>

          <div className="bg-slate-900/40 rounded-[48px] border border-slate-800 overflow-hidden shadow-2xl backdrop-blur-xl min-h-[400px]">
            {isInitialLoading ? (
              <div className="p-40 text-center flex flex-col items-center gap-6">
                <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin" />
                <p className="text-[11px] font-black text-slate-600 tracking-[0.4em] uppercase">Syncing Database...</p>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                  <thead>
                    <tr className="bg-slate-950/40 border-b border-slate-800">
                      <th className="p-8 text-[10px] font-black text-slate-500 uppercase tracking-[0.3em]">Student Name & LRN</th>
                      <th className="p-8 text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] text-center">RFID Assignment</th>
                      <th className="p-8 text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] text-right">Selection</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-800/50">
                    {filteredLearners.length === 0 ? (
                      <tr>
                        <td colSpan={3} className="p-20 text-center text-slate-600 font-black uppercase text-[10px] tracking-widest opacity-50">
                          No matching records found
                        </td>
                      </tr>
                    ) : (
                      filteredLearners.map(learner => {
                        const isLinked = !!uidMappings[learner.id];
                        const isSelected = selectedLearnerId === learner.id;
                        return (
                          <tr key={learner.id} className={`transition-all duration-300 ${isSelected ? 'bg-indigo-600/10' : 'hover:bg-slate-800/30'}`}>
                            <td className="p-8">
                              <div className="text-[16px] font-black text-white tracking-tight leading-tight uppercase italic">{learner.lastName}, {learner.firstName}</div>
                              <div className="text-[10px] font-bold text-slate-500 mt-2 uppercase tracking-widest">LRN: {learner.lrn || 'N/A'}</div>
                            </td>
                            <td className="p-8 text-center">
                              {isLinked ? (
                                <span className="px-5 py-2 rounded-full bg-emerald-500/10 text-emerald-400 text-[10px] font-black border border-emerald-500/20 font-mono tracking-tighter">
                                  {uidMappings[learner.id]}
                                </span>
                              ) : (
                                <span className="text-slate-800 text-[10px] font-black uppercase tracking-widest">UNASSIGNED</span>
                              )}
                            </td>
                            <td className="p-8 text-right">
                              <button 
                                onClick={() => {
                                  setSelectedLearnerId(isSelected ? null : learner.id);
                                  setConflictWarning(null);
                                }} 
                                className={`px-8 py-3 rounded-2xl text-[10px] font-black transition-all transform active:scale-90 tracking-widest ${
                                  isSelected 
                                  ? 'bg-indigo-50 text-white shadow-xl shadow-indigo-500/30' 
                                  : 'bg-slate-800/80 text-slate-400 hover:text-white hover:bg-slate-700'
                                }`}
                              >
                                {isSelected ? 'SELECTED' : 'SELECT'}
                              </button>
                            </td>
                          </tr>
                        );
                      })
                    )}
                  </tbody>
                </table>
              </div>
            )}
            {isFetchingAll && (
              <div className="p-4 bg-indigo-600/10 border-t border-indigo-500/20 text-center">
                <p className="text-[9px] font-black text-indigo-400 uppercase tracking-[0.3em] animate-pulse">
                  Streaming {fetchedCount} Records from Cloud...
                </p>
              </div>
            )}
          </div>
        </div>
      </main>

      <footer className="max-w-7xl mx-auto w-full mt-12 pt-10 border-t border-slate-900/50 flex flex-col md:flex-row justify-between items-center gap-6 text-[10px] font-black text-slate-700 uppercase tracking-[0.5em]">
        <div className="flex gap-12">
          <div className="flex items-center gap-3">
            <span className="text-slate-800">ASSIGNED_TAGS:</span>
            <span className="text-indigo-400/50">{Object.keys(uidMappings).length}</span>
          </div>
          <div className="flex items-center gap-3">
            <span className="text-slate-800">POOL_CAPACITY:</span>
            <span className="text-indigo-400/50">{learners.length} STUDENTS</span>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <span className={`w-2 h-2 rounded-full ${status === 'connected' ? 'bg-emerald-500 animate-pulse' : 'bg-slate-800'}`} />
          READER: {status.toUpperCase()} @ {baudRate} BAUD
        </div>
      </footer>
    </div>
  );
};

