export interface SerialLog {
  id: string;
  timestamp: Date;
  type: 'in' | 'out' | 'info' | 'error';
  text: string;
}

export type ConnectionStatus = 'disconnected' | 'connecting' | 'connected' | 'error';

export interface SerialOptions {
  baudRate: number;
  bufferSize?: number;
}

export interface Learner {
  id: string;
  lrn: string | null;
  firstName: string | null;
  lastName: string | null;
  middleName: string | null;
  birthDate: string | null;
  gender: string | null;
  address: string | null;
  sectionId: string | null;
  rfid?: string;
}

export interface AttendanceRecord {
  learnerId: string;
  type: 'IN' | 'OUT';
  timestamp: string;
}

export interface ScanResult {
  learner: Learner;
  type: 'IN' | 'OUT';
  time: string;
  uid: string;
}

export interface SerialPort {
  open(options: { baudRate: number }): Promise<void>;
  close(): Promise<void>;
  readable: any;
  writable: any;
}

import { useState, useCallback, useRef, useEffect } from 'react';
import { SerialLog, ConnectionStatus, SerialOptions, SerialPort } from '../types';

export const useSerial = () => {
  const [status, setStatus] = useState<ConnectionStatus>('disconnected');
  const [logs, setLogs] = useState<SerialLog[]>([]);
  const [error, setError] = useState<string | null>(null);

  const readerRef = useRef<ReadableStreamDefaultReader<string> | null>(null);
  const writerRef = useRef<WritableStreamDefaultWriter<string> | null>(null);
  const portRef = useRef<any>(null);

  const addLog = useCallback((text: string, type: SerialLog['type']) => {
    const newLog: SerialLog = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date(),
      type,
      text
    };
    setLogs(prev => [...prev.slice(-499), newLog]);
  }, []);

  const disconnect = useCallback(async () => {
    const p = portRef.current;

    try {
      if (readerRef.current) {
        // Critical: Cancel and release lock to prevent "Locked Stream"
        await readerRef.current.cancel().catch(() => {});
        readerRef.current.releaseLock();
        readerRef.current = null;
      }
      if (writerRef.current) {
        await writerRef.current.close().catch(() => {});
        writerRef.current = null;
      }
      if (p) {
        await p.close().catch(() => {});
      }
    } catch (e) {
      console.error("Serial Cleanup error:", e);
    }

    portRef.current = null;
    setStatus('disconnected');
    addLog('Disconnected.', 'info');
  }, [addLog]);

  const startReading = useCallback(async (selectedPort: any) => {
    const textDecoder = new TextDecoderStream();
    const readableStreamClosed = selectedPort.readable.pipeTo(textDecoder.writable);
    const reader = textDecoder.readable.getReader();
    readerRef.current = reader;

    const textEncoder = new TextEncoderStream();
    textEncoder.readable.pipeTo(selectedPort.writable);
    const writer = textEncoder.writable.getWriter();
    writerRef.current = writer;

    let buffer = '';
    try {
      while (true) {
        const { value, done } = await reader.read();
        if (done) break;

        buffer += value;
        const lines = buffer.split(/\r?\n/);
        buffer = lines.pop() || ''; 

        for (const line of lines) {
          const trimmed = line.trim();
          if (trimmed) {
            addLog(trimmed, 'in');
          }
        }
      }
    } catch (err: any) {
      if (err.name !== 'AbortError') {
        console.error('Serial read error:', err);
        addLog(`Read error: ${err.message}`, 'error');
        setStatus('error');
      }
    } finally {
      if (readerRef.current === reader) {
        reader.releaseLock();
        readerRef.current = null;
      }
    }
  }, [addLog]);

  const connect = useCallback(async (options: SerialOptions, existingPort?: any) => {
    if (!('serial' in navigator)) {
      setError('Web Serial not supported.');
      return;
    }

    try {
      // Guard: Always disconnect existing port to prevent "Port already open"
      if (portRef.current) {
        await disconnect();
      }

      setError(null);
      setStatus('connecting');

      const selectedPort = existingPort || await (navigator as any).serial.requestPort();

      try {
        await selectedPort.open({ baudRate: options.baudRate });
      } catch (openErr: any) {
        if (openErr.message.includes('already open')) {
           // If somehow still says open, attempt to reuse or error
           console.warn('Port was reported as open.');
        } else {
          throw openErr;
        }
      }

      portRef.current = selectedPort;
      setStatus('connected');
      addLog(`Connected @ ${options.baudRate}.`, 'info');
      startReading(selectedPort);
    } catch (err: any) {
      setError(err.message || 'Connection failed.');
      setStatus('disconnected');
      addLog(`Failed: ${err.message}`, 'error');
    }
  }, [addLog, startReading, disconnect]);

  return { status, logs, connect, disconnect, error };
};

import { useState, useEffect, useMemo, useCallback } from 'react';
import { Learner } from '../types';
import { supabase } from '../lib/supabase';

export const useLearners = () => {
  const [learners, setLearners] = useState<Learner[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [fetchedCount, setFetchedCount] = useState(0);

  const fetchAll = useCallback(async () => {
    if (isSyncing) return;
    try {
      setIsSyncing(true);
      let allData: Learner[] = [];
      let from = 0;
      const step = 1000;
      let hasMore = true;

      while (hasMore) {
        const { data, error } = await supabase
          .from('learners')
          .select('*')
          .range(from, from + step - 1)
          .order('lastName', { ascending: true })
          .order('id', { ascending: true });

        if (error) throw error;

        if (data && data.length > 0) {
          const currentIds = new Set(allData.map(l => l.id));
          const unique = data.filter(l => !currentIds.has(l.id));

          allData = [...allData, ...unique];
          setLearners([...allData]); 
          setFetchedCount(allData.length);
          setIsLoading(false);
          hasMore = data.length === step;
          from += step;

          // Artificial delay for smooth UI progress (0 -> 1000 -> 2000 -> 2287)
          await new Promise(resolve => setTimeout(resolve, 60));
        } else {
          hasMore = false;
        }
      }
    } catch (err) {
      console.error('Fetch error:', err);
    } finally {
      setIsSyncing(false);
      setIsLoading(false);
    }
  }, [isSyncing]);

  useEffect(() => { fetchAll(); }, []);

  const getFiltered = useCallback((query: string, uidMappings: Record<string, string>) => {
    const raw = query.trim().toLowerCase();
    if (!raw) return learners;

    const tokens = raw.split(/\s+/).filter(t => t.length > 0);

    return learners
      .map(l => {
        const first = (l.firstName || '').toLowerCase();
        const last = (l.lastName || '').toLowerCase();
        const lrn = (l.lrn || '').toLowerCase();
        const rfid = (uidMappings[l.id] || '').toLowerCase();
        const full = `${first} ${last}`.toLowerCase();
        const rev = `${last} ${first}`.toLowerCase();

        let score = 0;
        if (lrn === raw) score += 10000;
        if (rfid === raw) score += 9000;
        if (full === raw || rev === raw) score += 8000;
        if (lrn.startsWith(raw)) score += 5000;
        if (last.startsWith(raw)) score += 4000;

        const searchArea = `${full} ${rev} ${lrn} ${rfid}`;
        if (tokens.every(t => searchArea.includes(t))) {
          score += 500;
        }
        return { learner: l, score };
      })
      .filter(i => i.score > 0)
      .sort((a, b) => b.score - a.score || (a.learner.lastName || '').localeCompare(b.learner.lastName || ''))
      .map(i => i.learner);
  }, [learners]);

  return { learners, isLoading, isSyncing, fetchedCount, getFiltered };
};

import { useState, useEffect } from 'react';
import { AttendanceRecord } from '../types';

export const useAttendance = () => {
  const [uidMappings, setUidMappings] = useState<Record<string, string>>(() => {
    const saved = localStorage.getItem('rfid_mappings');
    return saved ? JSON.parse(saved) : {};
  });

  const [attendanceLogs, setAttendanceLogs] = useState<AttendanceRecord[]>(() => {
    const saved = localStorage.getItem('attendance_logs');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('rfid_mappings', JSON.stringify(uidMappings));
  }, [uidMappings]);

  useEffect(() => {
    localStorage.setItem('attendance_logs', JSON.stringify(attendanceLogs));
  }, [attendanceLogs]);

  const addMapping = (learnerId: string, uid: string) => {
    setUidMappings(prev => ({ ...prev, [learnerId]: uid }));
  };

  const logAttendance = (learnerId: string, type: 'IN' | 'OUT') => {
    setAttendanceLogs(prev => [...prev, {
      learnerId,
      type,
      timestamp: new Date().toISOString()
    }]);
  };

  return { uidMappings, attendanceLogs, addMapping, logAttendance };
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { useSerial } from './hooks/useSerial';
import { useLearners } from './hooks/useLearners';
import { useAttendance } from './hooks/useAttendance';
import { ScanResult } from './types';
import Terminal from './components/Terminal';

// HELPER: Strict validation to ignore status messages like "RFID READY"
const isValidUid = (text: string) => {
  const clean = text.trim().toUpperCase();
  const hexRegex = /^[0-9A-F\s-]+$/;
  const statusWords = ['READY', 'RFID', 'SUCCESS', 'WAIT', 'ERROR', 'CONNECTED', 'START', 'READING'];
  return clean.length >= 4 && hexRegex.test(clean) && !statusWords.some(w => clean.includes(w));
};

const App: React.FC = () => {
  const { status, logs, connect, disconnect } = useSerial();
  const { learners, isLoading, isSyncing, fetchedCount, getFiltered } = useLearners();
  const { uidMappings, attendanceLogs, addMapping, logAttendance } = useAttendance();

  const [isStandbyMode, setIsStandbyMode] = useState(false);
  const [baudRate, setBaudRate] = useState(9600);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedLearnerId, setSelectedLearnerId] = useState<string | null>(null);
  const [activeRfid, setActiveRfid] = useState('');
  const [conflictWarning, setConflictWarning] = useState<string | null>(null);
  const [scanFlash, setScanFlash] = useState(false);

  const [lastScanResult, setLastScanResult] = useState<ScanResult | null>(null);
  const [unknownTag, setUnknownTag] = useState<string | null>(null);

  const lastProcessedId = useRef<string | null>(null);

  // Serial Processing Loop
  useEffect(() => {
    const lastLog = logs[logs.length - 1];
    if (!lastLog || lastLog.type !== 'in' || lastLog.id === lastProcessedId.current) return;

    const raw = lastLog.text.trim();
    if (!isValidUid(raw)) return;

    lastProcessedId.current = lastLog.id;
    const scannedUid = raw.toUpperCase().replace(/\s+/g, ' ');

    if (isStandbyMode) {
      const learnerId = Object.keys(uidMappings).find(id => uidMappings[id]?.toUpperCase() === scannedUid);
      const learner = learners.find(l => l.id === learnerId);
      if (learner) {
        const history = attendanceLogs.filter(log => log.learnerId === learner.id);
        const type = history[history.length - 1]?.type === 'IN' ? 'OUT' : 'IN';
        logAttendance(learner.id, type);
        setLastScanResult({
          learner, type, uid: scannedUid,
          time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        });
        setUnknownTag(null);
      } else {
        setUnknownTag(scannedUid);
        setLastScanResult(null);
      }
    } else {
      setScanFlash(true);
      setActiveRfid(scannedUid);
      setConflictWarning(null);

      const ownerId = Object.keys(uidMappings).find(id => uidMappings[id]?.toUpperCase() === scannedUid);
      if (ownerId) {
        const owner = learners.find(l => l.id === ownerId);
        setConflictWarning(`Conflict: Assigned to ${owner ? `${owner.lastName}` : 'ID ' + ownerId}`);
      }
      setTimeout(() => setScanFlash(false), 500);
    }
  }, [logs, isStandbyMode, uidMappings, learners]);

  useEffect(() => {
    if (lastScanResult || unknownTag) {
      const t = setTimeout(() => { setLastScanResult(null); setUnknownTag(null); }, 4000);
      return () => clearTimeout(t);
    }
  }, [lastScanResult, unknownTag]);

  const handleSave = () => {
    if (!selectedLearnerId || !activeRfid || conflictWarning) return;
    addMapping(selectedLearnerId, activeRfid);
    setScanFlash(true);
    setActiveRfid('');
    setSelectedLearnerId(null);
    setConflictWarning(null);
    setTimeout(() => setScanFlash(false), 400);
  };

  const filtered = useMemo(() => getFiltered(searchQuery, uidMappings), [searchQuery, learners, uidMappings]);

  if (isStandbyMode) {
    return (
      <div className="fixed inset-0 bg-[#020617] text-white flex flex-col items-center justify-center z-[1000]">
        <button onClick={() => setIsStandbyMode(false)} className="absolute top-12 left-12 px-6 py-3 bg-slate-900 border border-slate-700 rounded-2xl text-[10px] font-black uppercase tracking-widest">← Exit Kiosk</button>
        <div className="text-center space-y-12">
          {!lastScanResult && !unknownTag ? (
            <div className="space-y-8 animate-pulse">
              <div className="w-48 h-48 bg-indigo-500/10 border-2 border-indigo-500/30 rounded-[48px] flex items-center justify-center mx-auto">
                <svg className="w-24 h-24 text-indigo-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M12 4v1m6 11h2m-6 0h-2v4m0-11v3" strokeWidth={1} /></svg>
              </div>
              <h2 className="text-6xl font-black uppercase italic">Ready to Scan</h2>
            </div>
          ) : lastScanResult ? (
            <div className="space-y-6 animate-in slide-in-from-bottom-10">
              <div className={`text-9xl font-black italic ${lastScanResult.type === 'IN' ? 'text-emerald-400' : 'text-amber-400'}`}>{lastScanResult.type}</div>
              <h3 className="text-5xl font-black">{lastScanResult.learner.firstName} {lastScanResult.learner.lastName}</h3>
              <p className="text-2xl text-indigo-400 font-bold">{lastScanResult.time}</p>
            </div>
          ) : (
            <div className="space-y-6 text-rose-500 animate-bounce">
              <div className="text-8xl font-black italic">UNKNOWN</div>
              <p className="text-xl font-bold">UID: {unknownTag}</p>
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#020617] text-slate-200 p-6 lg:p-12 flex flex-col">
      <header className="max-w-7xl mx-auto w-full flex flex-col md:flex-row justify-between items-center mb-12 gap-8">
        <div className="flex items-center gap-6">
          <div className="w-16 h-16 bg-indigo-600 rounded-3xl flex items-center justify-center shadow-2xl rotate-3">
             <svg className="w-10 h-10 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1z" /></svg>
          </div>
          <div>
            <h1 className="text-4xl font-black uppercase italic leading-none">Registrar</h1>
            <p className="text-indigo-400 text-[10px] font-black tracking-widest uppercase mt-2">Local Sync Enabled</p>
          </div>
        </div>
        <div className="flex gap-4">
          <button onClick={() => setIsStandbyMode(true)} className="px-6 py-3 bg-slate-900 border border-indigo-500/20 text-indigo-400 rounded-2xl text-[10px] font-black tracking-widest hover:bg-indigo-600 hover:text-white transition-all">STANDBY KIOSK</button>
          <div className="flex gap-2 bg-slate-900 p-2 rounded-2xl border border-slate-800">
            <select value={baudRate} onChange={e => setBaudRate(Number(e.target.value))} className="bg-transparent text-xs font-bold outline-none px-2 cursor-pointer">
              <option value={9600}>9600</option>
              <option value={115200}>115200</option>
            </select>
            <button onClick={status === 'connected' ? disconnect : () => connect({ baudRate })} className={`px-6 py-2 rounded-xl text-[10px] font-black ${status === 'connected' ? 'bg-rose-500/10 text-rose-500' : 'bg-indigo-600 text-white'}`}>
              {status === 'connected' ? 'DISCONNECT' : 'CONNECT'}
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto w-full grid grid-cols-1 lg:grid-cols-12 gap-10">
        <div className="lg:col-span-4 space-y-8">
          <section className="bg-slate-900/40 rounded-[40px] border border-slate-800 p-8 shadow-2xl backdrop-blur-xl">
            <h2 className="text-[10px] font-black text-indigo-400 mb-8 uppercase tracking-widest">Pairing Console</h2>
            <div className="space-y-8">
              <div className="space-y-3">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Live Capture</label>
                <div className={`p-6 rounded-3xl border-2 transition-all ${scanFlash ? 'scale-105 border-indigo-400 shadow-indigo-500/20 shadow-lg' : 'border-slate-800 bg-slate-950/50'}`}>
                  {activeRfid ? (
                    <div>
                      <p className={`text-[10px] font-black uppercase ${conflictWarning ? 'text-rose-500' : 'text-indigo-400'}`}>{conflictWarning ? 'CONFLICT' : 'DETECTED'}</p>
