                    </div>
                  ) : <p className="text-[10px] text-slate-700 font-black py-2 tracking-widest animate-pulse">WAITING FOR SCAN...</p>}
                </div>
                {conflictWarning && <p className="text-[9px] font-bold text-rose-500 italic px-1">{conflictWarning}</p>}
              </div>

              <div className="space-y-3">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Target Student</label>
                <div className={`p-6 rounded-3xl border-2 ${selectedLearnerId ? 'bg-indigo-950/20 border-indigo-500/30' : 'bg-slate-950/50 border-slate-800 border-dashed'}`}>
                  {selectedLearnerId ? (
                    <div className="font-black text-white uppercase italic text-lg">
