import React, { useState, useEffect, useMemo, useRef } from 'react';
import { useSerial } from './hooks/useSerial';
import { useLearners } from './hooks/useLearners';
import { useAttendance } from './hooks/useAttendance';
import { ScanResult } from './types';

import Header from './components/Header';
import Footer from './components/Footer';
import KioskMode from './components/KioskMode';
import PairingConsole from './components/PairingConsole';
import LearnerDirectory from './components/LearnerDirectory';
import Terminal from './components/Terminal';

// HELPER: Strict validation to ensure "RFID READY" or status messages aren't saved as UIDs
const isValidUid = (text: string) => {
  const clean = text.trim().toUpperCase();
  const hexRegex = /^[0-9A-F\s-]+$/;
  const statusWords = ['READY', 'RFID', 'SUCCESS', 'WAIT', 'ERROR', 'CONNECTED', 'START', 'READING'];
  return clean.length >= 4 && hexRegex.test(clean) && !statusWords.some(w => clean.includes(w));
};

const App: React.FC = () => {
  const { status, logs, connect, disconnect } = useSerial();
  const { learners, isLoading, isSyncing, fetchedCount, getFiltered } = useLearners();
  const { uidMappings, attendanceLogs, addMapping, logAttendance } = useAttendance();

  // Local UI State
  const [isStandbyMode, setIsStandbyMode] = useState(false);
  const [baudRate, setBaudRate] = useState(9600);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedLearnerId, setSelectedLearnerId] = useState<string | null>(null);
  const [activeRfid, setActiveRfid] = useState('');
  const [conflictWarning, setConflictWarning] = useState<string | null>(null);
  const [scanFlash, setScanFlash] = useState(false);

  // Transient Status for Kiosk
  const [lastScanResult, setLastScanResult] = useState<ScanResult | null>(null);
  const [unknownTag, setUnknownTag] = useState<string | null>(null);

  // Reference to prevent processing the same serial line during React re-renders
  const lastProcessedId = useRef<string | null>(null);

  // MAIN SERIAL LOOP: Core business logic for processing scanned RFID tags
  useEffect(() => {
    const lastLog = logs[logs.length - 1];

    // Safety check: only process input messages, and only process each ID once
    if (!lastLog || lastLog.type !== 'in' || lastLog.id === lastProcessedId.current) return;

    const raw = lastLog.text.trim();
    if (!isValidUid(raw)) return; // Ignore status strings like "RFID READY"

    lastProcessedId.current = lastLog.id;
    const scannedUid = raw.toUpperCase().replace(/\s+/g, ' ');

    if (isStandbyMode) {
      // Kiosk Mode: Match scanned tag with a student
      const learnerId = Object.keys(uidMappings).find(id => uidMappings[id]?.toUpperCase() === scannedUid);
      const learner = learners.find(l => l.id === learnerId);

      if (learner) {
        const history = attendanceLogs.filter(log => log.learnerId === learner.id);
        const type = history[history.length - 1]?.type === 'IN' ? 'OUT' : 'IN';
        logAttendance(learner.id, type);
        setLastScanResult({
          learner, type, uid: scannedUid,
          time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        });
        setUnknownTag(null);
      } else {
        setUnknownTag(scannedUid);
        setLastScanResult(null);
      }
    } else {
      // Registration Mode: Capture tag for assignment
      setScanFlash(true);
      setActiveRfid(scannedUid);
      setConflictWarning(null);

      // Check for duplicates/conflicts immediately
      const ownerId = Object.keys(uidMappings).find(id => uidMappings[id]?.toUpperCase() === scannedUid);
      if (ownerId) {
        const owner = learners.find(l => l.id === ownerId);
        setConflictWarning(`Conflict: Tag already assigned to ${owner ? `${owner.lastName}` : 'another student'}`);
      }
      setTimeout(() => setScanFlash(false), 500);
    }
  }, [logs, isStandbyMode, uidMappings, learners, attendanceLogs, logAttendance]);

  // AUTO-RESET: Clear Kiosk messages after delay
  useEffect(() => {
    if (lastScanResult || unknownTag) {
      const t = setTimeout(() => { 
        setLastScanResult(null); 
        setUnknownTag(null); 
      }, 4000);
      return () => clearTimeout(t);
    }
  }, [lastScanResult, unknownTag]);

  const handleSaveMapping = () => {
    if (!selectedLearnerId || !activeRfid || conflictWarning) return;

    addMapping(selectedLearnerId, activeRfid);

    // UI REFRESH: Immediate cleanup for next capture
    setScanFlash(true);
    setActiveRfid('');
    setSelectedLearnerId(null);
    setConflictWarning(null);
    setTimeout(() => setScanFlash(false), 400);
  };

  const filteredLearners = useMemo(() => 
    getFiltered(searchQuery, uidMappings), 
    [searchQuery, learners, uidMappings, getFiltered]
  );

  const selectedLearner = learners.find(l => l.id === selectedLearnerId) || null;

  if (isStandbyMode) {
    return (
      <KioskMode 
        onExit={() => setIsStandbyMode(false)} 
        lastScanResult={lastScanResult} 
        unknownTag={unknownTag} 
      />
    );
  }

  return (
    <div className="min-h-screen bg-[#020617] text-slate-200 p-6 lg:p-12 flex flex-col">
      <Header 
        status={status} 
        baudRate={baudRate} 
        onBaudRateChange={setBaudRate} 
        onConnect={() => connect({ baudRate })} 
        onDisconnect={disconnect} 
        onEnterKiosk={() => setIsStandbyMode(true)} 
      />

      <main className="max-w-7xl mx-auto w-full grid grid-cols-1 lg:grid-cols-12 gap-10">
        <div className="lg:col-span-4 space-y-8">
          <PairingConsole 
            activeRfid={activeRfid} 
            selectedLearner={selectedLearner} 
            conflictWarning={conflictWarning} 
            scanFlash={scanFlash} 
            onSave={handleSaveMapping} 
          />

          <section className="bg-slate-900/40 rounded-[40px] border border-slate-800 p-8 shadow-2xl overflow-hidden">
            <h2 className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-6">Serial Debug</h2>
            <div className="h-48 rounded-[32px] overflow-hidden border border-slate-800 bg-black/40">
              <Terminal logs={logs.slice(-30)} />
            </div>
          </section>
        </div>

        <div className="lg:col-span-8 space-y-8">
          <div className="relative">
            <svg className="w-6 h-6 absolute left-6 top-1/2 -translate-y-1/2 text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
            </svg>
            <input 
              type="text" 
              placeholder="Search by Name, LRN, or RFID..." 
              value={searchQuery} 
              onChange={e => setSearchQuery(e.target.value)} 
              className="w-full bg-slate-900 border border-slate-800 rounded-[32px] pl-16 pr-8 py-6 text-sm focus:border-indigo-500/50 outline-none shadow-2xl transition-all" 
            />
          </div>

          <LearnerDirectory 
            learners={filteredLearners} 
            uidMappings={uidMappings} 
            selectedId={selectedLearnerId} 
            onSelect={setSelectedLearnerId} 
            isLoading={isLoading} 
            isSyncing={isSyncing} 
            fetchedCount={fetchedCount} 
          />
        </div>
      </main>

      <Footer 
        status={status} 
        baudRate={baudRate} 
        assignedCount={Object.keys(uidMappings).length} 
        totalCount={learners.length} 
      />
    </div>
  );
};

export default App;

import { useState, useCallback, useRef, useEffect } from 'react';
import { SerialLog, ConnectionStatus, SerialOptions, SerialPort } from '../types';

export const useSerial = () => {
  const [status, setStatus] = useState<ConnectionStatus>('disconnected');
  const [logs, setLogs] = useState<SerialLog[]>([]);
  const [error, setError] = useState<string | null>(null);

  const readerRef = useRef<ReadableStreamDefaultReader<string> | null>(null);
  const writerRef = useRef<WritableStreamDefaultWriter<string> | null>(null);
  const portRef = useRef<any>(null);

  const addLog = useCallback((text: string, type: SerialLog['type']) => {
    const newLog: SerialLog = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date(),
      type,
      text
    };
    setLogs(prev => [...prev.slice(-499), newLog]);
  }, []);

  const disconnect = useCallback(async () => {
    const p = portRef.current;

    try {
      if (readerRef.current) {
        // Must cancel and release lock in order to close the port safely
        await readerRef.current.cancel().catch(() => {});
        readerRef.current.releaseLock();
        readerRef.current = null;
      }
      if (writerRef.current) {
        await writerRef.current.close().catch(() => {});
        writerRef.current = null;
      }
      if (p) {
        await p.close().catch(() => {});
      }
    } catch (e) {
      console.error("Serial Cleanup error:", e);
    }

    portRef.current = null;
    setStatus('disconnected');
    addLog('Disconnected.', 'info');
  }, [addLog]);

  const startReading = useCallback(async (selectedPort: any) => {
    const textDecoder = new TextDecoderStream();
    selectedPort.readable.pipeTo(textDecoder.writable);
    const reader = textDecoder.readable.getReader();
    readerRef.current = reader;

    const textEncoder = new TextEncoderStream();
    textEncoder.readable.pipeTo(selectedPort.writable);
    const writer = textEncoder.writable.getWriter();
    writerRef.current = writer;

    let buffer = '';
    try {
      while (true) {
        const { value, done } = await reader.read();
        if (done) break;

        buffer += value;
        const lines = buffer.split(/\r?\n/);
        buffer = lines.pop() || ''; 

        for (const line of lines) {
          const trimmed = line.trim();
          if (trimmed) {
            addLog(trimmed, 'in');
          }
        }
      }
    } catch (err: any) {
      if (err.name !== 'AbortError') {
        console.error('Serial read error:', err);
        addLog(`Read error: ${err.message}`, 'error');
        setStatus('error');
      }
    } finally {
      if (readerRef.current === reader) {
        reader.releaseLock();
        readerRef.current = null;
      }
    }
  }, [addLog]);

  const connect = useCallback(async (options: SerialOptions, existingPort?: any) => {
    if (!('serial' in navigator)) {
      setError('Web Serial not supported.');
      return;
    }

    try {
      // Guard: Always disconnect existing port to prevent "Port already open"
      if (portRef.current) {
        await disconnect();
      }

      setError(null);
      setStatus('connecting');

      const selectedPort = existingPort || await (navigator as any).serial.requestPort();

      try {
        await selectedPort.open({ baudRate: options.baudRate });
        // Save the last successful baud rate
        localStorage.setItem('last_baud_rate', options.baudRate.toString());
      } catch (openErr: any) {
        if (openErr.message.includes('already open')) {
           console.warn('Port was reported as open, attempting to proceed.');
        } else {
          throw openErr;
        }
      }

      portRef.current = selectedPort;
      setStatus('connected');
      addLog(`Connected @ ${options.baudRate}.`, 'info');
      startReading(selectedPort);
    } catch (err: any) {
      setError(err.message || 'Connection failed.');
      setStatus('disconnected');
      addLog(`Failed: ${err.message}`, 'error');
    }
  }, [addLog, startReading, disconnect]);

  // AUTO-RECONNECT ON REFRESH
  useEffect(() => {
    const tryAutoConnect = async () => {
      if ('serial' in navigator) {
        try {
          const ports = await (navigator as any).serial.getPorts();
          if (ports.length > 0) {
            const savedBaud = localStorage.getItem('last_baud_rate');
            const baud = savedBaud ? parseInt(savedBaud) : 9600;
            addLog(`Detected authorized port. Auto-connecting...`, 'info');
            connect({ baudRate: baud }, ports[0]);
          }
        } catch (err) {
          console.debug('Auto-connect skipped:', err);
        }
      }
    };
    tryAutoConnect();
  }, [connect, addLog]);

  return { status, logs, connect, disconnect, error };
};

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { useSerial } from './hooks/useSerial';
import { useLearners } from './hooks/useLearners';
import { useAttendance } from './hooks/useAttendance';
import { ScanResult } from './types';

import Header from './components/Header';
import Footer from './components/Footer';
import KioskMode from './components/KioskMode';
import PairingConsole from './components/PairingConsole';
import LearnerDirectory from './components/LearnerDirectory';
import Terminal from './components/Terminal';

// HELPER: Strict validation to ensure "RFID READY" or status messages aren't saved as UIDs
const isValidUid = (text: string) => {
  const clean = text.trim().toUpperCase();
  // Regex: Only Hex characters (0-9, A-F) allowed, minimum length of 4
  const hexRegex = /^[0-9A-F\s-]+$/;
  const statusWords = ['READY', 'RFID', 'SUCCESS', 'WAIT', 'ERROR', 'CONNECTED', 'START', 'READING'];
  return clean.length >= 4 && hexRegex.test(clean) && !statusWords.some(w => clean.includes(w));
};

const App: React.FC = () => {
  const { status, logs, connect, disconnect } = useSerial();
  const { learners, isLoading, isSyncing, fetchedCount, getFiltered } = useLearners();
  const { uidMappings, attendanceLogs, addMapping, logAttendance } = useAttendance();

  // Local UI State
  const [isStandbyMode, setIsStandbyMode] = useState(false);
  const [baudRate, setBaudRate] = useState(() => {
    const saved = localStorage.getItem('last_baud_rate');
    return saved ? parseInt(saved) : 9600;
  });
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedLearnerId, setSelectedLearnerId] = useState<string | null>(null);
  const [activeRfid, setActiveRfid] = useState('');
  const [conflictWarning, setConflictWarning] = useState<string | null>(null);
  const [scanFlash, setScanFlash] = useState(false);

  // Transient Status for Kiosk
  const [lastScanResult, setLastScanResult] = useState<ScanResult | null>(null);
  const [unknownTag, setUnknownTag] = useState<string | null>(null);

  // Reference to prevent processing the same serial line during React re-renders
  const lastProcessedId = useRef<string | null>(null);

  // MAIN SERIAL LOOP: Core business logic for processing scanned RFID tags
  useEffect(() => {
    const lastLog = logs[logs.length - 1];

    // Safety check: only process input messages, and only process each ID once
    if (!lastLog || lastLog.type !== 'in' || lastLog.id === lastProcessedId.current) return;

    const raw = lastLog.text.trim();
    if (!isValidUid(raw)) return; // Ignore status strings like "RFID READY"

    lastProcessedId.current = lastLog.id;
    const scannedUid = raw.toUpperCase().replace(/\s+/g, ' ');

    if (isStandbyMode) {
      // Kiosk Mode: Match scanned tag with a student
      const learnerId = Object.keys(uidMappings).find(id => uidMappings[id]?.toUpperCase() === scannedUid);
      const learner = learners.find(l => l.id === learnerId);

      if (learner) {
        const history = attendanceLogs.filter(log => log.learnerId === learner.id);
        const type = history[history.length - 1]?.type === 'IN' ? 'OUT' : 'IN';
        logAttendance(learner.id, type);
        setLastScanResult({
          learner, type, uid: scannedUid,
          time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        });
        setUnknownTag(null);
      } else {
        setUnknownTag(scannedUid);
        setLastScanResult(null);
      }
    } else {
      // Registration Mode: Capture tag for assignment
      setScanFlash(true);
      setActiveRfid(scannedUid);
      setConflictWarning(null);

      // Check for duplicates/conflicts immediately
      const ownerId = Object.keys(uidMappings).find(id => uidMappings[id]?.toUpperCase() === scannedUid);
      if (ownerId) {
        const owner = learners.find(l => l.id === ownerId);
        setConflictWarning(`Conflict: Tag already assigned to ${owner ? `${owner.lastName}` : 'another student'}`);
      }
      setTimeout(() => setScanFlash(false), 500);
    }
  }, [logs, isStandbyMode, uidMappings, learners, attendanceLogs, logAttendance]);

  // AUTO-RESET: Clear Kiosk messages after delay
  useEffect(() => {
    if (lastScanResult || unknownTag) {
      const t = setTimeout(() => { 
        setLastScanResult(null); 
        setUnknownTag(null); 
      }, 4000);
      return () => clearTimeout(t);
    }
  }, [lastScanResult, unknownTag]);

  const handleSaveMapping = () => {
    if (!selectedLearnerId || !activeRfid || conflictWarning) return;

    addMapping(selectedLearnerId, activeRfid);

    // UI REFRESH: Immediate cleanup for next capture
    setScanFlash(true);
    setActiveRfid('');
    setSelectedLearnerId(null);
    setConflictWarning(null);
    setTimeout(() => setScanFlash(false), 400);
  };

  const filteredLearners = useMemo(() => 
    getFiltered(searchQuery, uidMappings), 
    [searchQuery, learners, uidMappings, getFiltered]
  );

  const selectedLearner = learners.find(l => l.id === selectedLearnerId) || null;

  if (isStandbyMode) {
    return (
      <KioskMode 
        onExit={() => setIsStandbyMode(false)} 
        lastScanResult={lastScanResult} 
        unknownTag={unknownTag} 
      />
    );
  }

  return (
    <div className="min-h-screen bg-[#020617] text-slate-200 p-6 lg:p-12 flex flex-col">
      <Header 
        status={status} 
        baudRate={baudRate} 
        onBaudRateChange={(b) => {
          setBaudRate(b);
          localStorage.setItem('last_baud_rate', b.toString());
        }} 
        onConnect={() => connect({ baudRate })} 
        onDisconnect={disconnect} 
        onEnterKiosk={() => setIsStandbyMode(true)} 
      />

      <main className="max-w-7xl mx-auto w-full grid grid-cols-1 lg:grid-cols-12 gap-10">
        <div className="lg:col-span-4 space-y-8">
          <PairingConsole 
            activeRfid={activeRfid} 
            selectedLearner={selectedLearner} 
            conflictWarning={conflictWarning} 
            scanFlash={scanFlash} 
            onSave={handleSaveMapping} 
          />

          <section className="bg-slate-900/40 rounded-[40px] border border-slate-800 p-8 shadow-2xl overflow-hidden backdrop-blur-md">
            <h2 className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-6 flex items-center gap-2">
              <span className={`w-1.5 h-1.5 rounded-full ${status === 'connected' ? 'bg-emerald-500 animate-pulse' : 'bg-slate-700'}`} />
              Live Terminal
            </h2>
            <div className="h-48 rounded-[32px] overflow-hidden border border-slate-800 bg-black/40">
              <Terminal logs={logs.slice(-30)} />
            </div>
          </section>
        </div>

        <div className="lg:col-span-8 space-y-8">
          <div className="relative group">
            <svg className="w-6 h-6 absolute left-6 top-1/2 -translate-y-1/2 text-slate-600 transition-colors group-focus-within:text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
            </svg>
            <input 
              type="text" 
              placeholder="Search by Name, LRN, or RFID UID..." 
              value={searchQuery} 
              onChange={e => setSearchQuery(e.target.value)} 
              className="w-full bg-slate-900 border border-slate-800 rounded-[32px] pl-16 pr-8 py-6 text-sm focus:border-indigo-500/50 outline-none shadow-2xl transition-all placeholder:text-slate-700" 
            />
          </div>

          <LearnerDirectory 
            learners={filteredLearners} 
            uidMappings={uidMappings} 
            selectedId={selectedLearnerId} 
            onSelect={setSelectedLearnerId} 
            isLoading={isLoading} 
            isSyncing={isSyncing} 
            fetchedCount={fetchedCount} 
          />
        </div>
      </main>

      <Footer 
        status={status} 
        baudRate={baudRate} 
        assignedCount={Object.keys(uidMappings).length} 
        totalCount={learners.length} 
      />
    </div>
  );
};

export default App;

import { useState, useCallback, useRef, useEffect } from 'react';
import { SerialLog, ConnectionStatus, SerialOptions } from '../types';

export const useSerial = () => {
  const [status, setStatus] = useState<ConnectionStatus>('disconnected');
  const [logs, setLogs] = useState<SerialLog[]>([]);
  const [error, setError] = useState<string | null>(null);

  const readerRef = useRef<ReadableStreamDefaultReader<Uint8Array> | null>(null);
  const writerRef = useRef<WritableStreamDefaultWriter<Uint8Array> | null>(null);
  const portRef = useRef<any>(null);
  const isAutoConnecting = useRef(false);

  const addLog = useCallback((text: string, type: SerialLog['type']) => {
    const newLog: SerialLog = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date(),
      type,
      text
    };
    setLogs(prev => [...prev.slice(-499), newLog]);
  }, []);

  const disconnect = useCallback(async () => {
    const reader = readerRef.current;
    const writer = writerRef.current;
    const port = portRef.current;

    try {
      if (reader) {
        // Cancel the reader to break the read loop
        await reader.cancel().catch(() => {});
        // releaseLock will be called in the finally block of startReading
        readerRef.current = null;
      }
      if (writer) {
        await writer.close().catch(() => {});
        writerRef.current = null;
      }
      if (port) {
        // Give a small delay to ensure locks are released by the browser
        await new Promise(resolve => setTimeout(resolve, 50));
        await port.close().catch((e: any) => console.warn("Port close warning:", e));
        portRef.current = null;
      }
    } catch (e) {
      console.error("Serial Cleanup error:", e);
    }

    setStatus('disconnected');
    addLog('Disconnected.', 'info');
  }, [addLog]);

  const startReading = useCallback(async (selectedPort: any) => {
    if (!selectedPort.readable) return;

    // Direct reader access is more robust than pipeTo for reconnect scenarios
    const reader = selectedPort.readable.getReader();
    readerRef.current = reader;

    const decoder = new TextDecoder();
    let buffer = '';

    try {
      while (true) {
        const { value, done } = await reader.read();
        if (done) break;

        if (value) {
          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split(/\r?\n/);
          buffer = lines.pop() || ''; 

          for (const line of lines) {
            const trimmed = line.trim();
            if (trimmed) {
              addLog(trimmed, 'in');
            }
          }
        }
      }
    } catch (err: any) {
      if (err.name !== 'AbortError') {
        console.error('Serial read error:', err);
        addLog(`Read error: ${err.message}`, 'error');
        setStatus('error');
      }
    } finally {
      // Ensure lock is released so port can be closed later
      if (reader) {
        reader.releaseLock();
      }
      if (readerRef.current === reader) {
        readerRef.current = null;
      }
    }
  }, [addLog]);

  const connect = useCallback(async (options: SerialOptions, existingPort?: any) => {
    if (!('serial' in navigator)) {
      setError('Web Serial not supported.');
      return;
    }

    try {
      // Always cleanup previous session before starting a new one
      if (portRef.current) {
        await disconnect();
      }

      setError(null);
      setStatus('connecting');

      const selectedPort = existingPort || await (navigator as any).serial.requestPort();

      try {
        await selectedPort.open({ baudRate: options.baudRate });
        localStorage.setItem('last_baud_rate', options.baudRate.toString());
      } catch (openErr: any) {
        if (!openErr.message.includes('already open')) {
          throw openErr;
        }
      }

      portRef.current = selectedPort;
      setStatus('connected');
      addLog(`Connected @ ${options.baudRate}.`, 'info');
      startReading(selectedPort);
    } catch (err: any) {
      setError(err.message || 'Connection failed.');
      setStatus('disconnected');
      addLog(`Failed: ${err.message}`, 'error');
    }
  }, [addLog, startReading, disconnect]);

  // AUTO-RECONNECT ON REFRESH
  useEffect(() => {
    const tryAutoConnect = async () => {
      if (isAutoConnecting.current) return;
      if ('serial' in navigator) {
        try {
          const ports = await (navigator as any).serial.getPorts();
          if (ports.length > 0) {
            isAutoConnecting.current = true;
            const savedBaud = localStorage.getItem('last_baud_rate');
            const baud = savedBaud ? parseInt(savedBaud) : 9600;
            // Delay auto-connect slightly to ensure UI is ready
            setTimeout(() => {
              connect({ baudRate: baud }, ports[0]);
            }, 500);
          }
        } catch (err) {
          console.debug('Auto-connect skipped:', err);
        }
      }
    };
    tryAutoConnect();
  }, [connect]);

  return { status, logs, connect, disconnect, error };
};

