import PairingConsole from './components/PairingConsole';
import LearnerDirectory from './components/LearnerDirectory';
import Terminal from './components/Terminal';

/**
 * Validates if a string contains an RFID UID pattern.
 * Looks for sequences of 4-10 bytes in hexadecimal format.
 */
const extractUid = (text: string): string | null => {
  const clean = text.trim().toUpperCase();

  // Status words to ignore for processing (but still show in terminal)
  const statusWords = [
    'READY', 'SUCCESS', 'WAIT', 'ERROR', 'CONNECTED', 
    'START', 'READING', 'BAUD', 'INITIALIZING', 'MFRC522'
  ];

  // If it's a short status message, ignore it
  if (statusWords.some(w => clean === w)) return null;

  // Regex: Find a sequence of 2-char hex values (at least 4 groups)
  // allowing optional spaces, colons, or dashes as separators.
  // Pattern: XX[sep]XX[sep]XX[sep]XX...
  const hexPattern = /[0-9A-F]{2}(?:[\s:-]?[0-9A-F]{2}){3,15}/;
  const match = clean.match(hexPattern);

  if (match) {
    // Return the cleaned UID without separators
    return match[0].replace(/[\s:-]+/g, '');
  }

  return null;
};

