  const [unknownTag, setUnknownTag] = useState<string | null>(null);

  // Reference to prevent processing the same serial line during React re-renders
  const lastProcessedId = useRef<string | null>(null);

  // Core logic to detect and process RFID scans from the serial logs
  useEffect(() => {
    if (logs.length === 0) return;

    const lastLog = logs[logs.length - 1];
    if (!lastLog || lastLog.type !== 'in' || lastLog.id === lastProcessedId.current) return;

    const scannedUid = extractUid(lastLog.text);
    if (!scannedUid) return;

    lastProcessedId.current = lastLog.id;

    if (isStandbyMode) {
      // KIOSK MODE: Match tag to student record
      const learnerId = Object.keys(uidMappings).find(id => {
        const storedUid = uidMappings[id]?.toUpperCase().replace(/[\s:-]+/g, '').trim();
        return storedUid === scannedUid;
      });

      const learner = learners.find(l => l.id === learnerId);

