import React from 'react';
import { Learner } from '../types';

interface LearnerDirectoryProps {
  learners: Learner[];
  uidMappings: Record<string, string>;
  selectedId: string | null;
  onSelect: (id: string | null) => void;
  isLoading: boolean;
  isSyncing: boolean;
  fetchedCount: number;
}

const LearnerDirectory: React.FC<LearnerDirectoryProps> = ({
  learners, uidMappings, selectedId, onSelect, isLoading, isSyncing, fetchedCount
}) => {
  return (
    <div className="bg-slate-900/40 rounded-[48px] border border-slate-800 overflow-hidden shadow-2xl backdrop-blur-xl min-h-[500px]">
      {isLoading ? (
        <div className="p-40 text-center flex flex-col items-center gap-6">
          <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin" />
          <p className="text-[11px] font-black text-slate-600 tracking-[0.4em] uppercase">Connecting to Database...</p>
        </div>
      ) : (
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-slate-950/40 border-b border-slate-800">
                <th className="p-8 text-[10px] font-black text-slate-500 uppercase tracking-[0.3em]">Student Name</th>
                <th className="p-8 text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] text-center">RFID Tag</th>
                <th className="p-8 text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] text-right">Selection</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800/50">
              {learners.length === 0 ? (
                <tr>
                  <td colSpan={3} className="p-20 text-center text-slate-600 font-black uppercase text-[10px] tracking-widest opacity-50">
                    No results found
                  </td>
                </tr>
              ) : (
                learners.map(learner => {
                  // Prioritize database-provided RFID, fall back to local mappings
                  const tag = learner.rfid || uidMappings[learner.id];
                  const isLinked = !!tag;
                  const isSelected = selectedId === learner.id;

                  return (
                    <tr key={learner.id} className={`transition-all duration-300 ${isSelected ? 'bg-indigo-600/10' : 'hover:bg-slate-800/30'}`}>
                      <td className="p-8">
                        <div className="text-[16px] font-black text-white tracking-tight leading-tight uppercase italic">{learner.lastName}, {learner.firstName}</div>
                        <div className="text-[10px] font-bold text-slate-500 mt-2 uppercase tracking-widest">LRN: {learner.lrn || 'N/A'}</div>
                      </td>
                      <td className="p-8 text-center">
                        {isLinked ? (
                          <span className={`px-5 py-2 rounded-full text-[10px] font-black border font-mono tracking-tighter ${learner.rfid ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' : 'bg-indigo-500/10 text-indigo-400 border-indigo-500/20'}`}>
                            {tag}
                          </span>
                        ) : (
                          <span className="text-slate-800 text-[10px] font-black uppercase tracking-widest">NONE</span>
                        )}
                      </td>
                      <td className="p-8 text-right">
                        <button 
                          onClick={() => onSelect(isSelected ? null : learner.id)} 
                          className={`px-8 py-3 rounded-2xl text-[10px] font-black transition-all transform active:scale-90 tracking-widest ${
                            isSelected 
                            ? 'bg-indigo-500 text-white shadow-xl shadow-indigo-500/30' 
                            : 'bg-slate-800/80 text-slate-400 hover:text-white hover:bg-slate-700'
                          }`}
                        >
                          {isSelected ? 'SELECTED' : 'SELECT'}
                        </button>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      )}
      {isSyncing && (
        <div className="p-4 bg-indigo-600/10 border-t border-indigo-500/20 text-center">
          <p className="text-[9px] font-black text-indigo-400 uppercase tracking-[0.3em] animate-pulse">
            Syncing {fetchedCount} Records...
          </p>
        </div>
      )}
    </div>
  );
};

