import { useState, useEffect, useCallback } from 'react';
import { Learner, Section } from '../types';
import { supabase } from '../lib/supabase';

export const useLearners = () => {
  const [learners, setLearners] = useState<Learner[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [fetchedCount, setFetchedCount] = useState(0);

  const fetchAll = useCallback(async () => {
    if (isSyncing) return;
    try {
      setIsSyncing(true);

      // 1. Fetch Sections first for mapping
      const { data: sectionsData, error: sectionsError } = await supabase
        .from('sections')
        .select('*');

      if (sectionsError) throw sectionsError;
      const sectionsMap = (sectionsData as Section[]).reduce((acc, s) => {
        acc[s.id] = s;
        return acc;
      }, {} as Record<string, Section>);

      // 2. Fetch Learners in chunks
      let allData: Learner[] = [];
      let from = 0;
      const step = 1000;
      let hasMore = true;

      while (hasMore) {
        const { data, error } = await supabase
          .from('learners')
          .select('*')
          .range(from, from + step - 1)
          .order('lastName', { ascending: true });

        if (error) throw error;

        if (data && data.length > 0) {
          const enriched = data.map(l => ({
            ...l,
            section_name: l.sectionId ? sectionsMap[l.sectionId]?.name : 'Unassigned',
            grade_level: l.sectionId ? sectionsMap[l.sectionId]?.grade_level : 'Other'
          }));

          const currentIds = new Set(allData.map(l => l.id));
          const unique = enriched.filter(l => !currentIds.has(l.id));

          allData = [...allData, ...unique];
          setLearners([...allData]); 
          setFetchedCount(allData.length);
          setIsLoading(false);
          hasMore = data.length === step;
          from += step;

          await new Promise(resolve => setTimeout(resolve, 50));
        } else {
          hasMore = false;
        }
      }
    } catch (err) {
      console.error('Fetch error:', err);
    } finally {
      setIsSyncing(false);
      setIsLoading(false);
    }
  }, [isSyncing]);

  useEffect(() => { fetchAll(); }, []);

  const getFiltered = useCallback((query: string, uidMappings: Record<string, string>) => {
    const raw = query.trim().toLowerCase();
    if (!raw) return learners;

    const tokens = raw.split(/\s+/).filter(t => t.length > 0);

    return learners
      .map(l => {
        const first = (l.firstName || '').toLowerCase();
        const last = (l.lastName || '').toLowerCase();
        const lrn = (l.lrn || '').toLowerCase();
        const rfid = (uidMappings[l.id] || '').toLowerCase();
        const section = (l.section_name || '').toLowerCase();
        const grade = (l.grade_level || '').toLowerCase();
        const full = `${first} ${last}`.toLowerCase();

        let score = 0;
        if (lrn === raw) score += 10000;
        if (rfid === raw) score += 9000;
        if (full.includes(raw)) score += 5000;

        const searchArea = `${full} ${lrn} ${rfid} ${section} ${grade}`;
        if (tokens.every(t => searchArea.includes(t))) {
          score += 500;
        }
        return { learner: l, score };
      })
      .filter(i => i.score > 0)
      .sort((a, b) => b.score - a.score)
      .map(i => i.learner);
  }, [learners]);

  return { learners, isLoading, isSyncing, fetchedCount, getFiltered };
};

import React, { useState, useMemo } from 'react';
import { Learner } from '../types';

interface LearnerDirectoryProps {
  learners: Learner[];
  uidMappings: Record<string, string>;
  selectedId: string | null;
  onSelect: (id: string | null) => void;
  isLoading: boolean;
  isSyncing: boolean;
  fetchedCount: number;
}

const LearnerDirectory: React.FC<LearnerDirectoryProps> = ({
  learners, uidMappings, selectedId, onSelect, isLoading, isSyncing, fetchedCount
}) => {
  // State for collapsible sections
  const [expandedGrades, setExpandedGrades] = useState<Set<string>>(new Set());
  const [expandedSections, setExpandedSections] = useState<Set<string>>(new Set());

  // Group learners: Grade -> Section -> Learners
  const groupedData = useMemo(() => {
    const groups: Record<string, Record<string, Learner[]>> = {};

    learners.forEach(learner => {
      const grade = learner.grade_level || 'Other';
      const section = learner.section_name || 'Unassigned';

      if (!groups[grade]) groups[grade] = {};
      if (!groups[grade][section]) groups[grade][section] = [];

      groups[grade][section].push(learner);
    });

    // Sort grades and sections
    return Object.keys(groups)
      .sort((a, b) => a.localeCompare(b, undefined, { numeric: true }))
      .reduce((acc, grade) => {
        acc[grade] = Object.keys(groups[grade])
          .sort()
          .reduce((secAcc, sec) => {
            secAcc[sec] = groups[grade][sec];
            return secAcc;
          }, {} as Record<string, Learner[]>);
        return acc;
      }, {} as Record<string, Record<string, Learner[]>>);
  }, [learners]);

  const toggleGrade = (grade: string) => {
    const next = new Set(expandedGrades);
    if (next.has(grade)) next.delete(grade);
    else next.add(grade);
    setExpandedGrades(next);
  };

  const toggleSection = (sectionKey: string) => {
    const next = new Set(expandedSections);
    if (next.has(sectionKey)) next.delete(sectionKey);
    else next.add(sectionKey);
    setExpandedSections(next);
  };

  return (
    <div className="bg-slate-900/40 rounded-[48px] border border-slate-800 overflow-hidden shadow-2xl backdrop-blur-xl min-h-[500px]">
      {isLoading ? (
        <div className="p-40 text-center flex flex-col items-center gap-6">
          <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin" />
          <p className="text-[11px] font-black text-slate-600 tracking-[0.4em] uppercase">Building Directory...</p>
        </div>
      ) : (
        <div className="p-4 space-y-4">
          {Object.entries(groupedData).length === 0 ? (
            <div className="p-20 text-center text-slate-600 font-black uppercase text-[10px] tracking-widest opacity-50">
              No results found
            </div>
          ) : (
            Object.entries(groupedData).map(([grade, sections]) => (
              <div key={grade} className="bg-slate-950/30 rounded-[32px] border border-slate-800/50 overflow-hidden transition-all">
                {/* Grade Header */}
                <button 
                  onClick={() => toggleGrade(grade)}
                  className="w-full flex items-center justify-between p-6 hover:bg-slate-800/20 transition-colors group"
                >
                  <div className="flex items-center gap-4">
                    <div className={`w-2 h-2 rounded-full transition-all duration-500 ${expandedGrades.has(grade) ? 'bg-indigo-500 shadow-[0_0_10px_rgba(99,102,241,0.5)]' : 'bg-slate-700'}`} />
                    <h3 className="text-sm font-black text-white uppercase tracking-[0.2em] italic">
                      {grade}
                    </h3>
                    <span className="text-[9px] font-bold text-slate-600 bg-slate-900/50 px-3 py-1 rounded-full border border-slate-800">
                      {Object.values(sections).flat().length} STUDENTS
                    </span>
                  </div>
                  <svg 
                    className={`w-5 h-5 text-slate-500 transition-transform duration-300 ${expandedGrades.has(grade) ? 'rotate-180' : ''}`} 
                    fill="none" stroke="currentColor" viewBox="0 0 24 24"
                  >
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" />
                  </svg>
                </button>

                {/* Sections List */}
                {expandedGrades.has(grade) && (
                  <div className="p-2 space-y-2 border-t border-slate-800/30 animate-in fade-in slide-in-from-top-2 duration-300">
                    {Object.entries(sections).map(([sectionName, sectionLearners]) => {
                      const sectionKey = `${grade}-${sectionName}`;
                      const isExpanded = expandedSections.has(sectionKey);

                      return (
                        <div key={sectionKey} className="bg-black/20 rounded-[24px] border border-slate-800/30 overflow-hidden">
                          <button 
                            onClick={() => toggleSection(sectionKey)}
                            className="w-full flex items-center justify-between p-4 hover:bg-slate-800/10 transition-colors"
                          >
                            <div className="flex items-center gap-3">
                              <span className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">SECTION:</span>
                              <span className="text-[11px] font-black text-white uppercase tracking-tight italic">{sectionName}</span>
                              <span className="text-[9px] text-slate-500 font-bold ml-2">({sectionLearners.length})</span>
                            </div>
                            <svg 
                              className={`w-4 h-4 text-slate-600 transition-transform duration-300 ${isExpanded ? 'rotate-180' : ''}`} 
