                          </button>

                          {/* Learners Table */}
                          {isExpanded && (
                            <div className="overflow-x-auto border-t border-slate-800/20 animate-in fade-in slide-in-from-top-1 duration-200">
                              <table className="w-full text-left border-collapse">
                                <tbody className="divide-y divide-slate-800/30">
                                  {sectionLearners.map(learner => {
