                                        <td className="p-5 text-center">
                                          {isLinked ? (
                                            <span className={`px-4 py-1.5 rounded-full text-[9px] font-black border font-mono tracking-tighter ${learner.rfid ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20' : 'bg-indigo-500/10 text-indigo-400 border-indigo-500/20'}`}>
