import { useState, useEffect } from 'react';
import { TimeSlotSettings } from '../types';

const DEFAULT_SETTINGS: TimeSlotSettings = {
  amIn: { start: '06:00', end: '10:00' },
  amOut: { start: '10:01', end: '12:30' },
  pmIn: { start: '12:31', end: '15:00' },
  pmOut: { start: '15:01', end: '19:00' },
};

export const useSettings = () => {
  const [settings, setSettings] = useState<TimeSlotSettings>(() => {
    const saved = localStorage.getItem('time_slot_settings');
    return saved ? JSON.parse(saved) : DEFAULT_SETTINGS;
  });

  useEffect(() => {
    localStorage.setItem('time_slot_settings', JSON.stringify(settings));
  }, [settings]);

  const updateSettings = (newSettings: TimeSlotSettings) => {
    setSettings(newSettings);
  };

  return { settings, updateSettings };
};

import { useState, useEffect } from 'react';
import { AttendanceRecord, AttendanceType } from '../types';

export const useAttendance = () => {
  const [uidMappings, setUidMappings] = useState<Record<string, string>>(() => {
    const saved = localStorage.getItem('rfid_mappings');
    return saved ? JSON.parse(saved) : {};
  });

  const [attendanceLogs, setAttendanceLogs] = useState<AttendanceRecord[]>(() => {
    const saved = localStorage.getItem('attendance_logs');
    return saved ? JSON.parse(saved) : [];
  });

  useEffect(() => {
    localStorage.setItem('rfid_mappings', JSON.stringify(uidMappings));
  }, [uidMappings]);

  useEffect(() => {
    localStorage.setItem('attendance_logs', JSON.stringify(attendanceLogs));
  }, [attendanceLogs]);

  const addMapping = (learnerId: string, uid: string) => {
    setUidMappings(prev => ({ ...prev, [learnerId]: uid }));
  };

  const logAttendance = (learnerId: string, type: AttendanceType) => {
    setAttendanceLogs(prev => [...prev, {
      learnerId,
      type,
      timestamp: new Date().toISOString()
    }]);
  };

  return { uidMappings, attendanceLogs, addMapping, logAttendance };
};

