import { useState, useEffect, useCallback } from 'react';
import { Learner, Section } from '../types';
import { supabase } from '../lib/supabase';

export const useLearners = () => {
  const [learners, setLearners] = useState<Learner[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [fetchedCount, setFetchedCount] = useState(0);

  const fetchAll = useCallback(async () => {
    if (isSyncing) return;
    try {
      setIsSyncing(true);

      // 1. Fetch ALL Sections (usually a small table)
      const { data: sectionsData, error: sectionsError } = await supabase
        .from('sections')
        .select('*');

      if (sectionsError) throw sectionsError;
      const sectionsMap = (sectionsData as Section[]).reduce((acc, s) => {
        acc[s.id] = s;
        return acc;
      }, {} as Record<string, Section>);

      // 2. Fetch Learners in chunks to handle large datasets
      let allData: Learner[] = [];
      let from = 0;
      const step = 1000;
      let hasMore = true;

      while (hasMore) {
        const { data, error } = await supabase
          .from('learners')
          .select('*')
          .range(from, from + step - 1)
          .order('lastName', { ascending: true });

        if (error) throw error;

        if (data && data.length > 0) {
          const enriched = data.map(l => {
            const section = l.sectionId ? sectionsMap[l.sectionId] : null;
            return {
              ...l,
              section_name: section ? section.name : 'Unassigned Learners',
              grade_level: section ? section.grade_level : 'UNASSIGNED RECORDS'
            };
          });

          const currentIds = new Set(allData.map(l => l.id));
          const unique = enriched.filter(l => !currentIds.has(l.id));

          allData = [...allData, ...unique];
          setLearners([...allData]); 
          setFetchedCount(allData.length);
          setIsLoading(false);
          hasMore = data.length === step;
          from += step;

          // Brief delay to prevent UI thread locking during massive fetches
          await new Promise(resolve => setTimeout(resolve, 50));
        } else {
          hasMore = false;
        }
      }
    } catch (err) {
      console.error('Fetch error:', err);
    } finally {
      setIsSyncing(false);
      setIsLoading(false);
    }
  }, [isSyncing]);

  useEffect(() => { fetchAll(); }, []);

  const getFiltered = useCallback((query: string, uidMappings: Record<string, string>) => {
    const raw = query.trim().toLowerCase();
    if (!raw) return learners;

    const tokens = raw.split(/\s+/).filter(t => t.length > 0);

    return learners
      .map(l => {
        const first = (l.firstName || '').toLowerCase();
        const last = (l.lastName || '').toLowerCase();
        const lrn = (l.lrn || '').toLowerCase();
        const rfid = (uidMappings[l.id] || '').toLowerCase();
        const section = (l.section_name || '').toLowerCase();
        const grade = (l.grade_level || '').toLowerCase();
        const full = `${first} ${last}`.toLowerCase();

        let score = 0;
        if (lrn === raw) score += 10000;
        if (rfid === raw) score += 9000;
        if (full.includes(raw)) score += 5000;

        const searchArea = `${full} ${lrn} ${rfid} ${section} ${grade}`;
        if (tokens.every(t => searchArea.includes(t))) {
          score += 500;
        }
        return { learner: l, score };
      })
      .filter(i => i.score > 0)
      .sort((a, b) => b.score - a.score)
      .map(i => i.learner);
  }, [learners]);

  return { learners, isLoading, isSyncing, fetchedCount, getFiltered };
};

import React, { useState, useMemo } from 'react';
import { Learner } from '../types';

interface LearnerDirectoryProps {
  learners: Learner[];
  uidMappings: Record<string, string>;
  selectedId: string | null;
  onSelect: (id: string | null) => void;
  isLoading: boolean;
  isSyncing: boolean;
  fetchedCount: number;
}

/**
 * Natural sort helper to handle "Grade 2" vs "Grade 10" correctly.
 */
const naturalSort = (a: string, b: string) => {
  return a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
};

const LearnerDirectory: React.FC<LearnerDirectoryProps> = ({
  learners, uidMappings, selectedId, onSelect, isLoading, isSyncing, fetchedCount
}) => {
  const [expandedGrades, setExpandedGrades] = useState<Set<string>>(new Set());
  const [expandedSections, setExpandedSections] = useState<Set<string>>(new Set());

  // Group and sort data hierarchically
  const groupedData = useMemo(() => {
    const groups: Record<string, Record<string, Learner[]>> = {};

    learners.forEach(learner => {
      const grade = learner.grade_level || 'UNASSIGNED RECORDS';
      const section = learner.section_name || 'Unlinked Learners';

      if (!groups[grade]) groups[grade] = {};
      if (!groups[grade][section]) groups[grade][section] = [];

      groups[grade][section].push(learner);
    });

    // Sort Grade Levels (Natural Sort)
    const sortedGrades = Object.keys(groups).sort((a, b) => {
      // Keep "UNASSIGNED" at the bottom
      if (a === 'UNASSIGNED RECORDS') return 1;
      if (b === 'UNASSIGNED RECORDS') return -1;
      return naturalSort(a, b);
    });

    return sortedGrades.reduce((acc, grade) => {
      const sections = groups[grade];
      // Sort Sections alphabetically within the grade
      acc[grade] = Object.keys(sections)
        .sort(naturalSort)
        .reduce((secAcc, sec) => {
          secAcc[sec] = sections[sec].sort((a, b) => 
            (a.lastName || '').localeCompare(b.lastName || '')
          );
          return secAcc;
        }, {} as Record<string, Learner[]>);
      return acc;
    }, {} as Record<string, Record<string, Learner[]>>);
  }, [learners]);

  const toggleGrade = (grade: string) => {
    const next = new Set(expandedGrades);
    if (next.has(grade)) next.delete(grade);
    else next.add(grade);
    setExpandedGrades(next);
  };

  const toggleSection = (sectionKey: string) => {
    const next = new Set(expandedSections);
    if (next.has(sectionKey)) next.delete(sectionKey);
    else next.add(sectionKey);
    setExpandedSections(next);
  };

  return (
    <div className="bg-slate-900/40 rounded-[48px] border border-slate-800 overflow-hidden shadow-2xl backdrop-blur-xl min-h-[500px]">
      {isLoading ? (
        <div className="p-40 text-center flex flex-col items-center gap-6">
          <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin" />
          <p className="text-[11px] font-black text-slate-600 tracking-[0.4em] uppercase">Synchronizing Student Data...</p>
        </div>
      ) : (
        <div className="p-4 space-y-4">
          {Object.entries(groupedData).length === 0 ? (
            <div className="p-20 text-center text-slate-600 font-black uppercase text-[10px] tracking-widest opacity-50">
              Zero records matching your query
            </div>
          ) : (
            Object.entries(groupedData).map(([grade, sections]) => {
              const isUnassignedGroup = grade === 'UNASSIGNED RECORDS';
              const gradeStudentCount = Object.values(sections).flat().length;

              return (
                <div 
                  key={grade} 
                  className={`rounded-[32px] border overflow-hidden transition-all duration-300 ${
                    isUnassignedGroup 
                    ? 'bg-rose-950/5 border-rose-500/10' 
                    : 'bg-slate-950/30 border-slate-800/50'
                  }`}
                >
                  {/* Grade Level Header */}
                  <button 
                    onClick={() => toggleGrade(grade)}
                    className="w-full flex items-center justify-between p-6 hover:bg-white/5 transition-colors group"
                  >
                    <div className="flex items-center gap-4">
                      <div className={`w-2 h-2 rounded-full transition-all duration-500 ${
                        expandedGrades.has(grade) 
                        ? (isUnassignedGroup ? 'bg-rose-500 shadow-[0_0_10px_rgba(244,63,94,0.5)]' : 'bg-indigo-500 shadow-[0_0_10px_rgba(99,102,241,0.5)]') 
                        : 'bg-slate-700'
                      }`} />
                      <h3 className={`text-sm font-black uppercase tracking-[0.2em] italic ${
                        isUnassignedGroup ? 'text-rose-400' : 'text-white'
                      }`}>
                        {grade}
                      </h3>
                      <span className="text-[9px] font-bold text-slate-500 bg-black/40 px-3 py-1 rounded-full border border-white/5">
                        {gradeStudentCount} {gradeStudentCount === 1 ? 'STUDENT' : 'STUDENTS'}
                      </span>
                    </div>
                    <svg 
                      className={`w-5 h-5 text-slate-500 transition-transform duration-300 ${expandedGrades.has(grade) ? 'rotate-180' : ''}`} 
                      fill="none" stroke="currentColor" viewBox="0 0 24 24"
                    >
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" />
                    </svg>
                  </button>

                  {/* Sections List */}
                  {expandedGrades.has(grade) && (
                    <div className="p-2 space-y-2 border-t border-white/5 animate-in fade-in slide-in-from-top-2 duration-300">
                      {Object.entries(sections).map(([sectionName, sectionLearners]) => {
                        const sectionKey = `${grade}-${sectionName}`;
                        const isExpanded = expandedSections.has(sectionKey);
                        const isUnassignedSection = sectionName === 'Unlinked Learners';

                        return (
                          <div key={sectionKey} className="bg-black/20 rounded-[24px] border border-white/5 overflow-hidden">
                            <button 
                              onClick={() => toggleSection(sectionKey)}
                              className="w-full flex items-center justify-between p-4 hover:bg-white/5 transition-colors"
                            >
                              <div className="flex items-center gap-3">
                                <span className={`text-[10px] font-black uppercase tracking-widest ${isUnassignedSection ? 'text-rose-500/50' : 'text-indigo-400/80'}`}>
                                  {isUnassignedSection ? 'STATUS:' : 'SECTION:'}
                                </span>
                                <span className="text-[11px] font-black text-white uppercase tracking-tight italic">{sectionName}</span>
                                <span className="text-[9px] text-slate-600 font-bold ml-2">({sectionLearners.length})</span>
                              </div>
                              <svg 
                                className={`w-4 h-4 text-slate-600 transition-transform duration-300 ${isExpanded ? 'rotate-180' : ''}`} 
                                fill="none" stroke="currentColor" viewBox="0 0 24 24"
                              >
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 9l-7 7-7-7" />
                              </svg>
                            </button>

                            {/* Learners Table */}
                            {isExpanded && (
                              <div className="overflow-x-auto border-t border-white/5 animate-in fade-in slide-in-from-top-1 duration-200">
                                <table className="w-full text-left border-collapse">
                                  <tbody className="divide-y divide-white/5">
                                    {sectionLearners.map(learner => {
                                      const tag = learner.rfid || uidMappings[learner.id];
                                      const isLinked = !!tag;
                                      const isSelected = selectedId === learner.id;

                                      return (
                                        <tr key={learner.id} className={`transition-all duration-300 ${isSelected ? 'bg-indigo-600/10' : 'hover:bg-white/5'}`}>
                                          <td className="p-5 pl-10">
                                            <div className="text-[14px] font-black text-white tracking-tight uppercase italic group-hover:text-indigo-400">
                                              {learner.lastName}, {learner.firstName}
                                            </div>
                                            <div className="text-[9px] font-bold text-slate-500 mt-1 uppercase tracking-widest">
                                              LRN: {learner.lrn || 'N/A'}
                                            </div>
                                          </td>
                                          <td className="p-5 text-center">
                                            {isLinked ? (
                                              <span className={`px-4 py-1.5 rounded-full text-[9px] font-black border font-mono tracking-tighter ${learner.rfid ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20 shadow-[0_0_15px_rgba(16,185,129,0.05)]' : 'bg-indigo-500/10 text-indigo-400 border-indigo-500/20'}`}>
                                                {tag}
                                              </span>
                                            ) : (
                                              <span className="text-slate-800 text-[9px] font-black uppercase tracking-widest">UNLINKED</span>
                                            )}
                                          </td>
                                          <td className="p-5 text-right pr-8">
                                            <button 
                                              onClick={() => onSelect(isSelected ? null : learner.id)} 
                                              className={`px-6 py-2 rounded-xl text-[9px] font-black transition-all transform active:scale-95 tracking-widest ${
                                                isSelected 
                                                ? 'bg-indigo-500 text-white shadow-lg shadow-indigo-500/30' 
                                                : 'bg-slate-800/80 text-slate-400 hover:text-white hover:bg-slate-700'
                                              }`}
                                            >
                                              {isSelected ? 'SELECTED' : 'SELECT'}
                                            </button>
                                          </td>
                                        </tr>
                                      );
                                    })}
                                  </tbody>
                                </table>
                              </div>
                            )}
                          </div>
                        );
                      })}
                    </div>
                  )}
                </div>
              );
            })
          )}
        </div>
      )}
      {isSyncing && (
        <div className="p-4 bg-indigo-600/10 border-t border-indigo-500/20 text-center overflow-hidden">
          <p className="text-[9px] font-black text-indigo-400 uppercase tracking-[0.3em] animate-pulse">
            Deep Fetch in progress: {fetchedCount} Records Loaded...
          </p>
        </div>
      )}
    </div>
  );
};

