import React from 'react';
import { ScanResult, AttendanceType } from '../types';

interface KioskModeProps {
  onExit: () => void;
  lastScanResult: ScanResult | null;
  unknownTag: string | null;
}

const KioskMode: React.FC<KioskModeProps> = ({ onExit, lastScanResult, unknownTag }) => {
  const getSessionLabel = (type: AttendanceType) => {
    switch (type) {
      case 'AM_IN': return 'AM Entry';
      case 'AM_OUT': return 'AM Exit';
      case 'PM_IN': return 'PM Entry';
      case 'PM_OUT': return 'PM Exit';
      default: return 'Logged';
    }
  };

  const getSessionBg = (type: AttendanceType) => {
    switch (type) {
      case 'AM_IN': return 'bg-emerald-600';
      case 'AM_OUT': return 'bg-amber-600';
      case 'PM_IN': return 'bg-primary';
      case 'PM_OUT': return 'bg-accent';
      default: return 'bg-slate-700';
    }
  };

  return (
    <div className="fixed inset-0 bg-[#000511] text-white flex flex-col items-center justify-center p-6 z-[2000] overflow-hidden">
      {/* Dynamic Background Blobs */}
      <div className="absolute inset-0 opacity-20 pointer-events-none overflow-hidden">
        <div className="absolute -top-20 -left-20 w-[600px] h-[600px] bg-primary rounded-full blur-[200px] animate-pulse" />
        <div className="absolute -bottom-20 -right-20 w-[600px] h-[600px] bg-accent rounded-full blur-[200px] animate-pulse" />
      </div>

      <button 
        onClick={onExit}
        className="absolute top-8 left-8 bg-white/5 border border-white/10 text-slate-400 hover:text-white px-6 py-2.5 rounded-full font-bold text-[11px] tracking-widest uppercase transition-all flex items-center gap-2 z-50"
      >
        <span className="material-symbols-outlined text-sm">close</span>
        Exit Terminal
      </button>

      <div className="relative z-10 w-full max-w-4xl text-center">
        {!lastScanResult && !unknownTag ? (
          <div className="space-y-12 animate-in fade-in zoom-in duration-1000">
            <div className="w-48 h-48 bg-primary/10 rounded-full border border-primary/20 flex items-center justify-center mx-auto relative">
              <div className="absolute inset-0 bg-primary/20 rounded-full animate-ping opacity-20" />
              <span className="material-symbols-outlined text-[80px] text-primary">nfc</span>
            </div>
            <div className="space-y-3">
