          <div className="space-y-10 animate-in slide-in-from-bottom-20 duration-500">
            <div className={`inline-flex items-center gap-4 px-10 py-5 rounded-full ${getSessionBg(lastScanResult.type)} text-white shadow-2xl`}>
              <span className="material-symbols-outlined text-4xl">verified</span>
              <span className="text-5xl font-black uppercase italic tracking-tight">
                {getSessionLabel(lastScanResult.type)}
              </span>
            </div>
            <div className="space-y-4">
              <h3 className="text-8xl font-black text-white leading-tight">
                {lastScanResult.learner.firstName}<br/>{lastScanResult.learner.lastName}
