import { useState, useEffect, useCallback } from 'react';
import { Learner, Section } from '../types';
import { supabase } from '../lib/supabase';

export const useLearners = () => {
  const [learners, setLearners] = useState<Learner[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [fetchedCount, setFetchedCount] = useState(0);

  const fetchAll = useCallback(async () => {
    if (isSyncing) return;
    try {
      setIsSyncing(true);

      // 1. Fetch ALL Sections
      const { data: sectionsData, error: sectionsError } = await supabase
        .from('sections')
        .select('*');

      if (sectionsError) throw sectionsError;

      const sectionsMap = (sectionsData as any[]).reduce((acc, s) => {
        acc[s.id] = s;
        return acc;
      }, {} as Record<string, any>);

      // 2. Fetch Learners in chunks
      let allData: Learner[] = [];
      let from = 0;
      const step = 1000;
      let hasMore = true;

      while (hasMore) {
        const { data, error } = await supabase
          .from('learners')
          .select('*')
          .range(from, from + step - 1)
          .order('lastName', { ascending: true });

        if (error) throw error;

        if (data && data.length > 0) {
          const enriched = data.map(l => {
            // Handle both section_id (DB) and sectionId (Interface)
            const sId = l.section_id || l.sectionId;
            const section = sId ? sectionsMap[sId] : null;

            return {
              ...l,
              section_name: section ? section.name : 'No Section Assigned',
              grade_level: section ? (section.grade_level || 'General Education') : 'UNASSIGNED RECORDS'
            };
          });

          const currentIds = new Set(allData.map(l => l.id));
          const unique = enriched.filter(l => !currentIds.has(l.id));

          allData = [...allData, ...unique];
          setLearners([...allData]); 
          setFetchedCount(allData.length);
          setIsLoading(false);
          hasMore = data.length === step;
          from += step;

          await new Promise(resolve => setTimeout(resolve, 50));
        } else {
          hasMore = false;
        }
      }
    } catch (err) {
      console.error('Fetch error:', err);
    } finally {
      setIsSyncing(false);
      setIsLoading(false);
    }
  }, [isSyncing]);

  useEffect(() => { fetchAll(); }, []);

  const getFiltered = useCallback((query: string, uidMappings: Record<string, string>) => {
    const raw = query.trim().toLowerCase();
    if (!raw) return learners;

    const tokens = raw.split(/\s+/).filter(t => t.length > 0);

    return learners
      .map(l => {
        const first = (l.firstName || '').toLowerCase();
        const last = (l.lastName || '').toLowerCase();
        const lrn = (l.lrn || '').toLowerCase();
        const rfid = (uidMappings[l.id] || '').toLowerCase();
        const section = (l.section_name || '').toLowerCase();
        const grade = (l.grade_level || '').toLowerCase();
        const full = `${first} ${last}`.toLowerCase();

        let score = 0;
        if (lrn === raw) score += 10000;
        if (rfid === raw) score += 9000;
        if (full.includes(raw)) score += 5000;

        const searchArea = `${full} ${lrn} ${rfid} ${section} ${grade}`;
        if (tokens.every(t => searchArea.includes(t))) {
          score += 500;
        }
        return { learner: l, score };
      })
      .filter(i => i.score > 0)
      .sort((a, b) => b.score - a.score)
      .map(i => i.learner);
  }, [learners]);

  return { learners, isLoading, isSyncing, fetchedCount, getFiltered };
};

import React, { useState, useMemo } from 'react';
import { Learner } from '../types';

interface LearnerDirectoryProps {
  learners: Learner[];
  uidMappings: Record<string, string>;
  selectedId: string | null;
  onSelect: (id: string | null) => void;
  isLoading: boolean;
  isSyncing: boolean;
  fetchedCount: number;
}

const naturalSort = (a: string, b: string) => {
  return a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
};

const LearnerDirectory: React.FC<LearnerDirectoryProps> = ({
  learners, uidMappings, selectedId, onSelect, isLoading, isSyncing, fetchedCount
}) => {
  const [expandedGrades, setExpandedGrades] = useState<Set<string>>(new Set());
  const [expandedSections, setExpandedSections] = useState<Set<string>>(new Set());

  const groupedData = useMemo(() => {
    const groups: Record<string, Record<string, Learner[]>> = {};

    learners.forEach(learner => {
      const grade = learner.grade_level || 'UNASSIGNED RECORDS';
      const section = learner.section_name || 'Unlinked Learners';

      if (!groups[grade]) groups[grade] = {};
      if (!groups[grade][section]) groups[grade][section] = [];

      groups[grade][section].push(learner);
    });

    const sortedGrades = Object.keys(groups).sort((a, b) => {
      if (a === 'UNASSIGNED RECORDS') return 1;
      if (b === 'UNASSIGNED RECORDS') return -1;
      return naturalSort(a, b);
    });

    return sortedGrades.reduce((acc, grade) => {
      const sections = groups[grade];
      acc[grade] = Object.keys(sections)
        .sort(naturalSort)
        .reduce((secAcc, sec) => {
          secAcc[sec] = sections[sec].sort((a, b) => 
            (a.lastName || '').localeCompare(b.lastName || '')
          );
          return secAcc;
        }, {} as Record<string, Learner[]>);
      return acc;
    }, {} as Record<string, Record<string, Learner[]>>);
  }, [learners]);

  const toggleGrade = (grade: string) => {
    const next = new Set(expandedGrades);
    if (next.has(grade)) next.delete(grade);
    else next.add(grade);
    setExpandedGrades(next);
  };

  const toggleSection = (sectionKey: string) => {
    const next = new Set(expandedSections);
    if (next.has(sectionKey)) next.delete(sectionKey);
    else next.add(sectionKey);
    setExpandedSections(next);
  };

  return (
    <div className="bg-surface-variant/20 rounded-m3-xl border border-white/5 overflow-hidden shadow-sm min-h-[500px]">
      {isLoading ? (
        <div className="p-40 text-center flex flex-col items-center gap-4">
          <div className="w-10 h-10 border-4 border-primary border-t-accent rounded-full animate-spin" />
          <p className="text-xs font-bold text-slate-500 uppercase tracking-widest">Loading Database...</p>
        </div>
      ) : (
        <div className="p-4 space-y-3">
          {Object.entries(groupedData).length === 0 ? (
            <div className="p-20 text-center text-slate-600 font-bold uppercase text-xs tracking-widest">
              No matching records
            </div>
          ) : (
            Object.entries(groupedData).map(([grade, sections]) => {
              const isUnassignedGroup = grade === 'UNASSIGNED RECORDS';
              const gradeStudentCount = Object.values(sections).flat().length;

              return (
                <div key={grade} className={`rounded-m3-lg overflow-hidden border border-white/5 ${isUnassignedGroup ? 'bg-accent/5' : 'bg-surface-variant/20'}`}>
                  <button 
                    onClick={() => toggleGrade(grade)}
                    className="w-full flex items-center justify-between p-5 hover:bg-white/5 transition-colors"
                  >
                    <div className="flex items-center gap-4">
                      <span className={`material-symbols-outlined text-xl ${isUnassignedGroup ? 'text-accent' : 'text-primary'}`}>
                        {expandedGrades.has(grade) ? 'folder_open' : 'folder'}
                      </span>
                      <h3 className={`text-sm font-bold tracking-tight uppercase italic ${isUnassignedGroup ? 'text-accent' : 'text-white'}`}>
                        {grade}
                      </h3>
                      <span className="text-[10px] font-bold text-slate-500 bg-black/20 px-3 py-1 rounded-full border border-white/5">
                        {gradeStudentCount} STUDENTS
                      </span>
                    </div>
                    <span className={`material-symbols-outlined text-slate-500 transition-transform ${expandedGrades.has(grade) ? 'rotate-180' : ''}`}>
                      expand_more
                    </span>
                  </button>

                  {expandedGrades.has(grade) && (
                    <div className="px-3 pb-3 space-y-2 animate-in slide-in-from-top-2 duration-300">
                      {Object.entries(sections).map(([sectionName, sectionLearners]) => {
                        const sectionKey = `${grade}-${sectionName}`;
                        const isExpanded = expandedSections.has(sectionKey);

                        return (
                          <div key={sectionKey} className="bg-surface-variant/40 rounded-m3-md border border-white/5 overflow-hidden">
                            <button 
                              onClick={() => toggleSection(sectionKey)}
                              className="w-full flex items-center justify-between p-3.5 hover:bg-white/5 transition-colors"
                            >
                              <div className="flex items-center gap-3">
                                <span className="text-[10px] font-bold text-primary uppercase tracking-wider">SECTION:</span>
                                <span className="text-xs font-bold text-white uppercase italic tracking-tight">{sectionName}</span>
                                <span className="text-[10px] text-slate-500 font-bold ml-1">({sectionLearners.length})</span>
                              </div>
                              <span className={`material-symbols-outlined text-slate-600 text-sm transition-transform ${isExpanded ? 'rotate-180' : ''}`}>
                                arrow_drop_down
                              </span>
                            </button>

                            {isExpanded && (
                              <div className="divide-y divide-white/5 border-t border-white/5">
                                {sectionLearners.map(learner => {
                                  const tag = learner.rfid || uidMappings[learner.id];
                                  const isSelected = selectedId === learner.id;

                                  return (
                                    <div 
                                      key={learner.id} 
                                      className={`flex items-center justify-between p-4 pl-8 transition-colors ${isSelected ? 'bg-primary/20' : 'hover:bg-white/5'}`}
                                    >
                                      <div>
                                        <div className="text-sm font-bold text-white tracking-tight uppercase">
                                          {learner.lastName}, {learner.firstName}
                                        </div>
                                        <div className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mt-0.5">
                                          LRN: {learner.lrn || 'N/A'}
                                        </div>
                                      </div>
                                      <div className="flex items-center gap-6">
                                        {tag ? (
                                          <div className="flex items-center gap-2 px-3 py-1 bg-primary/10 border border-primary/20 rounded-full">
                                            <span className="material-symbols-outlined text-[12px] text-primary">tag</span>
                                            <span className="text-[10px] font-mono font-bold text-primary">{tag}</span>
                                          </div>
                                        ) : (
                                          <span className="text-[10px] font-bold text-slate-800 uppercase tracking-widest">UNLINKED</span>
                                        )}
