const LearnerDirectory: React.FC<LearnerDirectoryProps> = ({
  learners, uidMappings, selectedId, onSelect, isLoading, isSearching, isSyncing, fetchedCount
}) => {
  const [expandedGrades, setExpandedGrades] = useState<Set<string>>(new Set());
  const [expandedSections, setExpandedSections] = useState<Set<string>>(new Set());

  const groupedData = useMemo(() => {
    if (isSearching) return {}; // No grouping needed during search

    const groups: Record<string, Record<string, Learner[]>> = {};

    learners.forEach(learner => {
      const grade = learner.grade_level || 'NO GRADE ASSIGNED';
      const section = learner.section_name || 'Unassigned';

      if (!groups[grade]) groups[grade] = {};
      if (!groups[grade][section]) groups[grade][section] = [];

      groups[grade][section].push(learner);
    });

    const sortedGrades = Object.keys(groups).sort((a, b) => {
      if (a === 'NO GRADE ASSIGNED') return 1;
      if (b === 'NO GRADE ASSIGNED') return -1;
      return naturalSort(a, b);
    });

    return sortedGrades.reduce((acc, grade) => {
      const sections = groups[grade];
      acc[grade] = Object.keys(sections)
        .sort(naturalSort)
        .reduce((secAcc, sec) => {
          secAcc[sec] = sections[sec].sort((a, b) => 
            (a.lastName || '').localeCompare(b.lastName || '')
          );
          return secAcc;
        }, {} as Record<string, Learner[]>);
      return acc;
    }, {} as Record<string, Record<string, Learner[]>>);
  }, [learners, isSearching]);

  const toggleGrade = (grade: string) => {
    const next = new Set(expandedGrades);
    if (next.has(grade)) next.delete(grade);
    else next.add(grade);
    setExpandedGrades(next);
  };

  const toggleSection = (sectionKey: string) => {
    const next = new Set(expandedSections);
    if (next.has(sectionKey)) next.delete(sectionKey);
    else next.add(sectionKey);
    setExpandedSections(next);
  };

  return (
    <div className="bg-surface-variant rounded-m3-xl border border-white/5 overflow-hidden shadow-sm min-h-[500px]">
      {isLoading ? (
        <div className="p-40 text-center flex flex-col items-center gap-4">
          <div className="w-10 h-10 border-4 border-primary border-t-accent rounded-full animate-spin" />
          <p className="text-xs font-bold text-on-surface-variant uppercase tracking-widest">Accessing Student Registry...</p>
        </div>
      ) : (
        <div className="p-4 space-y-3">
          {isSearching ? (
            <div className="space-y-1 animate-in fade-in duration-300">
              <div className="px-4 py-2 border-b border-white/5 flex items-center justify-between">
                <h3 className="text-[10px] font-black text-primary uppercase tracking-[0.3em]">Search Results</h3>
                <span className="text-[10px] font-bold text-slate-500">{learners.length} Matches</span>
              </div>
              <div className="max-h-[700px] overflow-y-auto no-scrollbar">
                {learners.length === 0 ? (
                  <div className="p-20 text-center text-slate-600 font-bold uppercase text-xs tracking-widest">
                    No students found matching your query
                  </div>
                ) : (
                  learners.map(learner => (
                    <LearnerItem 
                      key={learner.id}
                      learner={learner}
                      uidMappings={uidMappings}
                      isSelected={selectedId === learner.id}
                      onSelect={onSelect}
                    />
                  ))
                )}
              </div>
            </div>
          ) : (
            Object.entries(groupedData).length === 0 ? (
              <div className="p-20 text-center text-slate-600 font-bold uppercase text-xs tracking-widest">
                Database is currently empty
              </div>
            ) : (
              Object.entries(groupedData).map(([grade, sections]) => {
                const isUnassignedGroup = grade === 'NO GRADE ASSIGNED';
                const gradeStudentCount = Object.values(sections).flat().length;

                return (
                  <div key={grade} className={`rounded-m3-lg overflow-hidden border border-white/5 ${isUnassignedGroup ? 'bg-accent/5' : 'bg-black/20'}`}>
                    <button 
                      onClick={() => toggleGrade(grade)}
                      className="w-full flex items-center justify-between p-5 hover:bg-white/5 transition-colors"
                    >
                      <div className="flex items-center gap-4">
                        <span className={`material-symbols-outlined text-xl ${isUnassignedGroup ? 'text-accent' : 'text-primary'}`}>
                          {expandedGrades.has(grade) ? 'folder_open' : 'folder'}
                        </span>
                        <h3 className={`text-sm font-black tracking-tight uppercase italic ${isUnassignedGroup ? 'text-accent' : 'text-white'}`}>
                          {grade}
                        </h3>
                        <span className="text-[10px] font-bold text-slate-500 bg-black/40 px-3 py-1 rounded-full border border-white/5">
                          {gradeStudentCount} RECORDS
                        </span>
                      </div>
