import React, { useState, useMemo } from 'react';
import { Learner } from '../types';

interface LearnerDirectoryProps {
  learners: Learner[];
  uidMappings: Record<string, string>;
  selectedId: string | null;
  onSelect: (id: string | null) => void;
  isLoading: boolean;
  isSearching: boolean;
  isSyncing: boolean;
  fetchedCount: number;
}

const naturalSort = (a: string, b: string) => {
  return a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
};

const LearnerItem: React.FC<{
  learner: Learner;
  uidMappings: Record<string, string>;
  isSelected: boolean;
  onSelect: (id: string | null) => void;
}> = ({ learner, uidMappings, isSelected, onSelect }) => {
  const tag = learner.rfid || uidMappings[learner.id];

  return (
    <div 
      className={`flex items-center justify-between p-4 pl-6 transition-colors border-b border-white/5 last:border-none ${isSelected ? 'bg-primary/20' : 'hover:bg-white/5'}`}
    >
      <div className="flex-grow min-w-0 pr-4">
        <div className="text-sm font-black text-white tracking-tight uppercase truncate">
          {learner.lastName}, {learner.firstName}
        </div>
        <div className="flex items-center gap-3 mt-1">
          <div className="text-[10px] font-bold text-slate-500 uppercase tracking-widest whitespace-nowrap">
            REF: {learner.lrn || 'N/A'}
          </div>
          <div className="text-[10px] font-bold text-primary/60 uppercase tracking-widest truncate">
            {learner.grade_level} • {learner.section_name}
          </div>
        </div>
      </div>
      <div className="flex items-center gap-6 flex-shrink-0">
        <div className="hidden sm:block">
          {tag ? (
            <div className="flex items-center gap-2 px-3 py-1 bg-primary/10 border border-primary/20 rounded-full shadow-[0_0_10px_rgba(1,14,91,0.2)]">
              <span className="material-symbols-outlined text-[12px] text-primary">tag</span>
              <span className="text-[10px] font-mono font-black text-primary">{tag}</span>
            </div>
          ) : (
            <span className="text-[10px] font-bold text-accent/40 uppercase tracking-widest italic">UNLINKED</span>
          )}
        </div>
        <div className="w-10 flex justify-center items-center">
          <button 
            onClick={() => onSelect(isSelected ? null : learner.id)} 
            className={`flex items-center justify-center w-8 h-8 rounded-full transition-all active:scale-90 ${
              isSelected 
              ? 'bg-primary text-white shadow-lg shadow-primary/40' 
              : 'bg-black/40 text-slate-400 hover:text-white'
            }`}
            title={isSelected ? "Deselect student" : "Select student"}
          >
            <span className="material-symbols-outlined text-lg leading-none">
              {isSelected ? 'check_circle' : 'radio_button_unchecked'}
            </span>
          </button>
        </div>
      </div>
    </div>
  );
};

const LearnerDirectory: React.FC<LearnerDirectoryProps> = ({
  learners, uidMappings, selectedId, onSelect, isLoading, isSearching, isSyncing, fetchedCount
}) => {
  const [expandedGrades, setExpandedGrades] = useState<Set<string>>(new Set());
  const [expandedSections, setExpandedSections] = useState<Set<string>>(new Set());

  const groupedData = useMemo(() => {
    if (isSearching) return {}; 

    const groups: Record<string, Record<string, Learner[]>> = {};

    learners.forEach(learner => {
      const grade = learner.grade_level || 'NO GRADE ASSIGNED';
      const section = learner.section_name || 'Unassigned';

      if (!groups[grade]) groups[grade] = {};
      if (!groups[grade][section]) groups[grade][section] = [];

      groups[grade][section].push(learner);
    });

    const sortedGrades = Object.keys(groups).sort((a, b) => {
      if (a === 'NO GRADE ASSIGNED') return 1;
      if (b === 'NO GRADE ASSIGNED') return -1;
      return naturalSort(a, b);
    });

    return sortedGrades.reduce((acc, grade) => {
      const sections = groups[grade];
      acc[grade] = Object.keys(sections)
        .sort(naturalSort)
        .reduce((secAcc, sec) => {
          secAcc[sec] = sections[sec].sort((a, b) => 
            (a.lastName || '').localeCompare(b.lastName || '')
          );
          return secAcc;
        }, {} as Record<string, Learner[]>);
      return acc;
    }, {} as Record<string, Record<string, Learner[]>>);
  }, [learners, isSearching]);

  const toggleGrade = (grade: string) => {
    const next = new Set(expandedGrades);
    if (next.has(grade)) next.delete(grade);
    else next.add(grade);
    setExpandedGrades(next);
  };

  const toggleSection = (sectionKey: string) => {
    const next = new Set(expandedSections);
    if (next.has(sectionKey)) next.delete(sectionKey);
    else next.add(sectionKey);
    setExpandedSections(next);
  };

  return (
    <div className="bg-surface-variant rounded-m3-xl border border-white/5 overflow-hidden shadow-sm min-h-[500px]">
      {isLoading ? (
        <div className="p-40 text-center flex flex-col items-center gap-4">
          <div className="w-10 h-10 border-4 border-primary border-t-accent rounded-full animate-spin" />
          <p className="text-xs font-bold text-on-surface-variant uppercase tracking-widest">Accessing Student Registry...</p>
        </div>
      ) : (
        <div className="p-4 space-y-3">
          {isSearching ? (
            <div className="space-y-1 animate-in fade-in duration-300">
              <div className="px-4 py-2 border-b border-white/5 flex items-center justify-between">
                <h3 className="text-[10px] font-black text-primary uppercase tracking-[0.3em]">
                  {learners.length === 1 ? 'Search Result' : 'Search Results'}
                </h3>
                <span className="text-[10px] font-bold text-slate-500">
                  {learners.length} {learners.length === 1 ? 'Match' : 'Matches'}
                </span>
              </div>
              <div className="max-h-[700px] overflow-y-auto no-scrollbar">
                {learners.length === 0 ? (
                  <div className="p-20 text-center text-slate-600 font-bold uppercase text-xs tracking-widest">
                    No students found matching your query
                  </div>
                ) : (
                  learners.map(learner => (
                    <LearnerItem 
                      key={learner.id}
                      learner={learner}
                      uidMappings={uidMappings}
                      isSelected={selectedId === learner.id}
                      onSelect={onSelect}
                    />
                  ))
                )}
              </div>
            </div>
          ) : (
            Object.entries(groupedData).length === 0 ? (
              <div className="p-20 text-center text-slate-600 font-bold uppercase text-xs tracking-widest">
                Database is currently empty
              </div>
            ) : (
              Object.entries(groupedData).map(([grade, sections]) => {
                const isUnassignedGroup = grade === 'NO GRADE ASSIGNED';
                const gradeStudentCount = Object.values(sections).flat().length;

                return (
                  <div key={grade} className={`rounded-m3-lg overflow-hidden border border-white/5 ${isUnassignedGroup ? 'bg-accent/5' : 'bg-black/20'}`}>
                    <button 
                      onClick={() => toggleGrade(grade)}
                      className="w-full flex items-center justify-between p-5 hover:bg-white/5 transition-colors"
                    >
                      <div className="flex items-center gap-4">
                        <span className={`material-symbols-outlined text-xl ${isUnassignedGroup ? 'text-accent' : 'text-primary'}`}>
                          {expandedGrades.has(grade) ? 'folder_open' : 'folder'}
                        </span>
                        <h3 className={`text-sm font-black tracking-tight uppercase italic ${isUnassignedGroup ? 'text-accent' : 'text-white'}`}>
                          {grade}
                        </h3>
                        <span className="text-[10px] font-bold text-slate-500 bg-black/40 px-3 py-1 rounded-full border border-white/5">
                          {gradeStudentCount} {gradeStudentCount === 1 ? 'RECORD' : 'RECORDS'}
                        </span>
                      </div>
                      <span className={`material-symbols-outlined text-slate-500 transition-transform ${expandedGrades.has(grade) ? 'rotate-180' : ''}`}>
                        expand_more
                      </span>
                    </button>

                    {expandedGrades.has(grade) && (
                      <div className="px-3 pb-3 space-y-2 animate-in slide-in-from-top-2 duration-300">
                        {Object.entries(sections).map(([sectionName, sectionLearners]) => {
                          const sectionKey = `${grade}-${sectionName}`;
                          const isExpanded = expandedSections.has(sectionKey);
                          const isOrphaned = sectionName === 'Orphaned Section';

                          return (
                            <div key={sectionKey} className="bg-surface-variant/60 rounded-m3-md border border-white/5 overflow-hidden">
                              <button 
                                onClick={() => toggleSection(sectionKey)}
                                className="w-full flex items-center justify-between p-3.5 hover:bg-white/5 transition-colors"
                              >
                                <div className="flex items-center gap-3">
                                  <span className={`text-[10px] font-bold uppercase tracking-wider ${isOrphaned ? 'text-accent' : 'text-primary'}`}>
                                    {isOrphaned ? 'SYSTEM ERROR:' : 'SECTION:'}
                                  </span>
                                  <span className="text-xs font-black text-white uppercase italic tracking-tight">{sectionName}</span>
                                  <span className="text-[10px] text-slate-500 font-bold ml-1">
                                    ({sectionLearners.length})
                                  </span>
                                </div>
                                <span className={`material-symbols-outlined text-slate-600 text-sm transition-transform ${isExpanded ? 'rotate-180' : ''}`}>
                                  arrow_drop_down
                                </span>
                              </button>

                              {isExpanded && (
                                <div className="divide-y divide-white/5 border-t border-white/5 max-h-96 overflow-y-auto no-scrollbar">
                                  {sectionLearners.map(learner => (
                                    <LearnerItem 
                                      key={learner.id}
                                      learner={learner}
                                      uidMappings={uidMappings}
                                      isSelected={selectedId === learner.id}
                                      onSelect={onSelect}
                                    />
                                  ))}
                                </div>
                              )}
                            </div>
                          );
                        })}
                      </div>
                    )}
                  </div>
                );
              })
            )
          )}
        </div>
      )}
      {isSyncing && (
        <div className="p-3 bg-primary/20 border-t border-primary/40 flex items-center justify-center gap-3">
          <div className="w-3 h-3 border-2 border-primary border-t-transparent rounded-full animate-spin" />
