    if (result.isDuplicate) return 'ALREADY LOGGED';

    switch (result.type) {
      case 'AM_IN': return 'Morning Entry';
      case 'AM_OUT': return 'Morning Exit';
      case 'PM_IN': return 'Afternoon Entry';
      case 'PM_OUT': return 'Afternoon Exit';
      default: return 'Logged';
    }
  };

  const getStatusColor = (result: ScanResult) => {
    if (result.isDuplicate) return 'text-amber-600 bg-amber-50';

    switch (result.type) {
      case 'AM_IN': return 'text-emerald-600 bg-emerald-50';
      case 'AM_OUT': return 'text-amber-600 bg-amber-50';
      case 'PM_IN': return 'text-primary bg-primary/5';
      case 'PM_OUT': return 'text-accent bg-accent/5';
      default: return 'text-slate-600 bg-slate-50';
