        onClick={onExit}
        className="absolute top-10 left-10 bg-white shadow-sm border border-black/5 text-slate-500 hover:text-primary px-8 py-3 rounded-full font-bold text-[11px] tracking-widest uppercase transition-all flex items-center gap-3 z-50 group"
