      </button>

      <div className="relative z-10 w-full max-w-2xl">
        {!lastScanResult && !unknownTag ? (
          <div className="bg-white rounded-[40px] shadow-[0_32px_64px_-16px_rgba(0,0,0,0.1)] p-20 text-center space-y-12 animate-in fade-in zoom-in duration-700">
