              <div className="absolute inset-0 bg-primary/5 rounded-full animate-ping opacity-20" />
              <span className="material-symbols-outlined text-[100px] text-primary/30">contactless</span>
            </div>
            <div className="space-y-6">
              <h2 className="text-5xl font-black tracking-tighter text-primary uppercase italic">Ready to Verify</h2>
              <div className="flex flex-col items-center gap-4">
