                <p className="text-sm font-bold text-slate-400 tracking-[0.6em] uppercase">Present card to sensor</p>
              </div>
            </div>
          </div>
        ) : lastScanResult ? (
          <div className="bg-white rounded-[40px] shadow-[0_32px_64px_-16px_rgba(0,0,0,0.1)] p-20 text-center space-y-10 animate-in slide-in-from-bottom-20 duration-500">
            <div className={`inline-flex items-center gap-4 px-10 py-4 rounded-full ${getStatusColor(lastScanResult)} font-bold shadow-sm border border-black/5`}>
              <span className="material-symbols-outlined text-2xl">
                {lastScanResult.isDuplicate ? 'history' : 'check_circle'}
