const LearnerDirectory: React.FC<LearnerDirectoryProps> = ({
  learners, uidMappings, selectedId, onSelect, isLoading, isSearching, isSyncing, fetchedCount
}) => {
  const [expandedGrades, setExpandedGrades] = useState<Set<string>>(new Set());
  const [expandedSections, setExpandedSections] = useState<Set<string>>(new Set());

  const groupedData = useMemo(() => {
    if (isSearching) return {}; 

    const groups: Record<string, Record<string, Learner[]>> = {};

    learners.forEach(learner => {
      const grade = learner.grade_level || 'NO GRADE ASSIGNED';
      const section = learner.section_name || 'Unassigned';

      if (!groups[grade]) groups[grade] = {};
      if (!groups[grade][section]) groups[grade][section] = [];

      groups[grade][section].push(learner);
    });

    const sortedGrades = Object.keys(groups).sort((a, b) => {
      if (a === 'NO GRADE ASSIGNED') return 1;
      if (b === 'NO GRADE ASSIGNED') return -1;
      return naturalSort(a, b);
    });

    return sortedGrades.reduce((acc, grade) => {
      const sections = groups[grade];
      acc[grade] = Object.keys(sections)
        .sort(naturalSort)
        .reduce((secAcc, sec) => {
          secAcc[sec] = sections[sec].sort((a, b) => 
            (a.lastName || '').localeCompare(b.lastName || '')
          );
          return secAcc;
        }, {} as Record<string, Learner[]>);
      return acc;
    }, {} as Record<string, Record<string, Learner[]>>);
  }, [learners, isSearching]);

  const toggleGrade = (grade: string) => {
    const next = new Set(expandedGrades);
    if (next.has(grade)) next.delete(grade);
    else next.add(grade);
    setExpandedGrades(next);
  };

  const toggleSection = (sectionKey: string) => {
    const next = new Set(expandedSections);
    if (next.has(sectionKey)) next.delete(sectionKey);
    else next.add(sectionKey);
    setExpandedSections(next);
  };

  return (
    <div className="bg-white rounded-m3-xl border border-black/5 overflow-hidden shadow-sm min-h-[500px]">
      {isLoading ? (
        <div className="p-40 text-center flex flex-col items-center gap-6">
          <div className="w-12 h-12 border-4 border-slate-100 border-t-primary rounded-full animate-spin" />
          <p className="text-xs font-black text-slate-400 uppercase tracking-widest">Querying Registry...</p>
        </div>
      ) : (
        <div className="p-4 space-y-4">
          {isSearching ? (
            <div className="space-y-1 animate-in fade-in duration-300">
              <div className="px-6 py-4 border-b border-black/5 flex items-center justify-between bg-slate-50 rounded-t-2xl">
                <h3 className="text-[11px] font-black text-primary uppercase tracking-[0.3em]">
                  {learners.length === 1 ? 'Search Result' : 'Search Results'}
                </h3>
                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                  {learners.length} {learners.length === 1 ? 'Match' : 'Matches'}
                </span>
              </div>
              <div className="max-h-[700px] overflow-y-auto no-scrollbar">
                {learners.length === 0 ? (
                  <div className="p-20 text-center text-slate-300 font-bold uppercase text-xs tracking-widest">
                    No matching records found
                  </div>
                ) : (
                  learners.map(learner => (
                    <LearnerItem 
                      key={learner.id}
                      learner={learner}
                      uidMappings={uidMappings}
                      isSelected={selectedId === learner.id}
                      onSelect={onSelect}
                    />
                  ))
                )}
              </div>
            </div>
          ) : (
            Object.entries(groupedData).map(([grade, sections]) => {
              const isUnassignedGroup = grade === 'NO GRADE ASSIGNED';
              const gradeStudentCount = Object.values(sections).flat().length;

              return (
                <div key={grade} className={`rounded-m3-lg overflow-hidden border border-black/5 ${isUnassignedGroup ? 'bg-slate-50' : 'bg-white shadow-sm'}`}>
                  <button 
                    onClick={() => toggleGrade(grade)}
                    className="w-full flex items-center justify-between p-6 hover:bg-slate-50 transition-colors"
                  >
                    <div className="flex items-center gap-5">
                      <span className={`material-symbols-outlined text-2xl ${isUnassignedGroup ? 'text-slate-400' : 'text-primary'}`}>
                        {expandedGrades.has(grade) ? 'expand_more' : 'chevron_right'}
                      </span>
                      <h3 className="text-sm font-black tracking-tight text-primary uppercase italic">
                        {grade}
                      </h3>
                      <span className="text-[10px] font-black text-slate-400 bg-slate-100 px-4 py-1.5 rounded-full border border-black/5">
                        {gradeStudentCount} {gradeStudentCount === 1 ? 'RECORD' : 'RECORDS'}
                      </span>
                    </div>
                  </button>

                  {expandedGrades.has(grade) && (
                    <div className="px-4 pb-4 space-y-3 animate-in slide-in-from-top-2 duration-300">
                      {Object.entries(sections).map(([sectionName, sectionLearners]) => {
                        const sectionKey = `${grade}-${sectionName}`;
                        const isExpanded = expandedSections.has(sectionKey);

                        return (
                          <div key={sectionKey} className="bg-slate-50/50 rounded-2xl border border-black/5 overflow-hidden">
                            <button 
                              onClick={() => toggleSection(sectionKey)}
                              className="w-full flex items-center justify-between p-4 hover:bg-white transition-colors"
                            >
                              <div className="flex items-center gap-4">
                                <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Section:</span>
                                <span className="text-xs font-black text-primary uppercase italic">{sectionName}</span>
                                <span className="text-[10px] text-slate-400 font-bold bg-white px-2 py-0.5 rounded border border-black/5">
                                  {sectionLearners.length}
                                </span>
                              </div>
                            </button>

                            {isExpanded && (
                              <div className="divide-y divide-black/5 border-t border-black/5 bg-white">
                                {sectionLearners.map(learner => (
                                  <LearnerItem 
                                    key={learner.id}
                                    learner={learner}
                                    uidMappings={uidMappings}
                                    isSelected={selectedId === learner.id}
                                    onSelect={onSelect}
                                  />
                                ))}
                              </div>
                            )}
                          </div>
                        );
                      })}
                    </div>
                  )}
                </div>
              );
            })
          )}
        </div>
      )}
      {isSyncing && (
        <div className="p-4 bg-primary text-white flex items-center justify-center gap-4">
          <div className="w-4 h-4 border-2 border-white/20 border-t-white rounded-full animate-spin" />
          <p className="text-[10px] font-black uppercase tracking-[0.4em] animate-pulse">
            Syncing Master Registry... ({fetchedCount})
          </p>
        </div>
      )}
    </div>
  );
};

