import React, { useEffect, useRef } from 'react';
import { SerialLog } from '../types';

interface TerminalProps {
  logs: SerialLog[];
}

const Terminal: React.FC<TerminalProps> = ({ logs }) => {
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [logs]);

  const getLogStyle = (type: SerialLog['type']) => {
    switch (type) {
      case 'in': return 'text-primary font-bold';
      case 'out': return 'text-accent';
      case 'error': return 'text-accent font-black underline';
      case 'info': return 'text-slate-400 italic';
      default: return 'text-slate-500';
    }
  };

  const formatTimestamp = (date: Date) => {
    return date.toLocaleTimeString([], { 
      hour12: false, 
      hour: '2-digit', 
      minute: '2-digit', 
      second: '2-digit'
    });
  };

  return (
    <div 
      ref={scrollRef}
      className="h-full w-full p-6 overflow-y-auto font-mono text-[12px] leading-relaxed no-scrollbar"
    >
      {logs.length === 0 ? (
        <div className="h-full flex flex-col items-center justify-center text-slate-300 gap-3">
