import { useState, useCallback, useRef, useEffect } from 'react';
import { SerialLog, ConnectionStatus, SerialOptions } from '../types';

export const useSerial = () => {
  const [status, setStatus] = useState<ConnectionStatus>('disconnected');
  const [logs, setLogs] = useState<SerialLog[]>([]);
  const [error, setError] = useState<string | null>(null);

  const readerRef = useRef<ReadableStreamDefaultReader<Uint8Array> | null>(null);
  const portRef = useRef<any>(null);
  const isAutoConnecting = useRef(false);
  const readLoopActive = useRef(false);
  const bufferRef = useRef('');
  const flushTimeoutRef = useRef<number | null>(null);

  const addLog = useCallback((text: string, type: SerialLog['type']) => {
    const newLog: SerialLog = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date(),
      type,
      text
    };
    setLogs(prev => [...prev.slice(-499), newLog]);
  }, []);

  const flushBuffer = useCallback(() => {
    if (bufferRef.current.trim()) {
      addLog(bufferRef.current.trim(), 'in');
      bufferRef.current = '';
    }
    if (flushTimeoutRef.current) {
      window.clearTimeout(flushTimeoutRef.current);
      flushTimeoutRef.current = null;
    }
  }, [addLog]);

  const disconnect = useCallback(async (isHardwareLoss = false) => {
    try {
      flushBuffer();

      if (readerRef.current) {
        await readerRef.current.cancel().catch(() => {});
        readerRef.current = null;
      }

      let timeout = 0;
      while (readLoopActive.current && timeout < 20) {
        await new Promise(r => setTimeout(r, 50));
        timeout++;
      }

      if (portRef.current) {
        try {
          await portRef.current.close().catch(() => {});
        } catch (e) {}
        portRef.current = null;
      }

      setStatus('disconnected');
      if (isHardwareLoss) {
        addLog('Hardware Disconnected: Device link lost.', 'error');
      } else {
        addLog('Disconnected safely.', 'info');
      }
    } catch (e) {
      console.error("Cleanup error:", e);
      setStatus('disconnected');
    }
  }, [addLog, flushBuffer]);

  const startReading = useCallback(async (selectedPort: any) => {
    if (!selectedPort || !selectedPort.readable) return;

    readLoopActive.current = true;
    const reader = selectedPort.readable.getReader();
    readerRef.current = reader;

    const decoder = new TextDecoder();

    try {
      while (true) {
        const { value, done } = await reader.read();
        if (done) break;

        if (value) {
          bufferRef.current += decoder.decode(value, { stream: true });

          if (flushTimeoutRef.current) window.clearTimeout(flushTimeoutRef.current);

          if (bufferRef.current.includes('\n') || bufferRef.current.includes('\r')) {
            const lines = bufferRef.current.split(/\r?\n|\r/);
            bufferRef.current = lines.pop() || ''; 

            for (const line of lines) {
              const trimmed = line.trim();
              if (trimmed) {
                addLog(trimmed, 'in');
              }
            }
          }

          flushTimeoutRef.current = window.setTimeout(() => {
            flushBuffer();
          }, 200);
        }
      }
    } catch (err: any) {
      if (err.name === 'NetworkError' || err.message?.toLowerCase().includes('device has been lost')) {
        disconnect(true);
      } else if (err.name !== 'AbortError') {
        addLog(`Serial Error: ${err.message}`, 'error');
      }
    } finally {
      try {
        reader.releaseLock();
      } catch (e) {}
      readerRef.current = null;
      readLoopActive.current = false;
    }
  }, [addLog, flushBuffer, disconnect]);

  const connect = useCallback(async (options: SerialOptions, existingPort?: any) => {
    if (!('serial' in navigator)) {
      setError('Web Serial API is not supported.');
      return;
    }

    try {
      if (portRef.current) await disconnect();

      setError(null);
      setStatus('connecting');

      const selectedPort = existingPort || await (navigator as any).serial.requestPort();
      await selectedPort.open({ baudRate: options.baudRate });

      localStorage.setItem('last_baud_rate', options.baudRate.toString());
      portRef.current = selectedPort;
      setStatus('connected');
      addLog(`Online: ${options.baudRate} baud.`, 'info');

      startReading(selectedPort);
    } catch (err: any) {
      setError(err.message || 'Connection failed.');
      setStatus('disconnected');
    }
  }, [addLog, startReading, disconnect]);

  useEffect(() => {
    const handleDisconnect = (event: any) => {
      if (portRef.current && event.port === portRef.current) {
        disconnect(true);
      }
    };

    if ('serial' in navigator) {
      (navigator as any).serial.addEventListener('disconnect', handleDisconnect);
    }

    return () => {
      if ('serial' in navigator) {
        (navigator as any).serial.removeEventListener('disconnect', handleDisconnect);
      }
    };
  }, [disconnect]);

  return { status, logs, connect, disconnect: () => disconnect(false), error };
};

import React, { useState, useEffect } from 'react';
import { ScanResult, AttendanceType, TimeSlotSettings } from '../types';

interface KioskModeProps {
  onExit: () => void;
  lastScanResult: ScanResult | null;
  unknownTag: string | null;
  settings: TimeSlotSettings;
}

const KioskMode: React.FC<KioskModeProps> = ({ onExit, lastScanResult, unknownTag, settings }) => {
  const [currentTime, setCurrentTime] = useState(new Date());

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const getSessionInfo = () => {
    const timeStr = currentTime.getHours().toString().padStart(2, '0') + ':' + currentTime.getMinutes().toString().padStart(2, '0');

    if (timeStr >= settings.amIn.start && timeStr <= settings.amIn.end) 
      return { label: 'Morning Entry', range: `${settings.amIn.start} — ${settings.amIn.end}` };
    if (timeStr >= settings.amOut.start && timeStr <= settings.amOut.end) 
      return { label: 'Morning Exit', range: `${settings.amOut.start} — ${settings.amOut.end}` };
    if (timeStr >= settings.pmIn.start && timeStr <= settings.pmIn.end) 
      return { label: 'Afternoon Entry', range: `${settings.pmIn.start} — ${settings.pmIn.end}` };
    if (timeStr >= settings.pmOut.start && timeStr <= settings.pmOut.end) 
      return { label: 'Afternoon Exit', range: `${settings.pmOut.start} — ${settings.pmOut.end}` };

    return { label: 'Out of Session', range: 'Archiving as Unscheduled' };
  };

  const session = getSessionInfo();

  const getStatusColor = (result: ScanResult) => {
    if (result.isDuplicate) return 'text-amber-600 bg-amber-50 border-amber-100';

    switch (result.type) {
      case 'AM_IN': return 'text-emerald-600 bg-emerald-50 border-emerald-100';
      case 'AM_OUT': return 'text-amber-600 bg-amber-50 border-amber-100';
      case 'PM_IN': return 'text-primary bg-primary/5 border-primary/10';
      case 'PM_OUT': return 'text-accent bg-accent/5 border-accent/10';
      default: return 'text-slate-600 bg-slate-50 border-slate-100';
    }
  };

  return (
    <div className="fixed inset-0 bg-app-bg text-on-surface flex flex-col items-center justify-between py-8 px-4 sm:py-12 sm:px-6 z-[2000] overflow-hidden">
      {/* Subtle Background Decorative Blur */}
      <div className="absolute inset-0 pointer-events-none opacity-40">
        <div className="absolute top-0 right-0 w-[300px] h-[300px] sm:w-[400px] sm:h-[400px] bg-white rounded-full blur-[80px] sm:blur-[100px] -translate-y-1/2 translate-x-1/2" />
        <div className="absolute bottom-0 left-0 w-[300px] h-[300px] sm:w-[400px] sm:h-[400px] bg-primary/10 rounded-full blur-[80px] sm:blur-[100px] translate-y-1/2 -translate-x-1/2" />
      </div>

      {/* Exit Button */}
      <button 
        onClick={onExit}
        className="absolute top-6 left-6 sm:top-8 sm:left-8 bg-white/80 backdrop-blur-sm shadow-sm border border-black/5 text-slate-400 hover:text-primary px-4 py-2 sm:px-5 sm:py-2.5 rounded-full font-bold text-[9px] sm:text-[10px] tracking-widest uppercase transition-all flex items-center gap-2 z-50 group"
      >
        <span className="material-symbols-outlined text-sm sm:text-base group-hover:-translate-x-1 transition-transform">arrow_back</span>
        Return
      </button>

      {/* Top Section: Clock & Session Identifier - Keeps content flow to avoid overlap */}
      <div className="w-full flex flex-col items-center gap-2 sm:gap-4 z-10 flex-shrink-0">
        <div className="text-4xl sm:text-6xl md:text-7xl font-black text-primary font-mono tracking-tighter tabular-nums leading-none">
          {currentTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false })}
        </div>
        <div className="flex items-center justify-center gap-1.5 sm:gap-2 px-4 sm:px-6 py-1.5 sm:py-2 bg-white/60 backdrop-blur-md rounded-full border border-black/5 shadow-sm max-w-full overflow-hidden">
          <div className="flex items-center justify-center">
            <span className="material-symbols-outlined text-slate-400 text-sm sm:text-lg leading-none">schedule</span>
          </div>
          <span className="text-[8px] sm:text-[10px] font-black text-slate-600 uppercase tracking-widest whitespace-nowrap">{session.label}</span>
          <span className="w-0.5 h-0.5 sm:w-1 sm:h-1 bg-slate-300 rounded-full flex-shrink-0" />
          <span className="text-[8px] sm:text-[10px] font-black text-primary/60 uppercase tracking-widest whitespace-nowrap">{session.range}</span>
        </div>
      </div>

      {/* Center Dynamic content */}
      <div className="relative z-10 w-full max-w-2xl flex flex-col items-center justify-center flex-grow py-4 sm:py-8 overflow-y-auto no-scrollbar">
        {!lastScanResult && !unknownTag ? (
          <div className="flex flex-col items-center justify-center space-y-6 sm:space-y-8 animate-in fade-in zoom-in duration-700">
            <div className="w-40 h-40 sm:w-64 sm:h-64 bg-white/40 rounded-full flex items-center justify-center relative border border-white/20 shadow-xl backdrop-blur-sm">
              <div className="absolute inset-0 bg-primary/10 rounded-full animate-ping opacity-20" />
              <div className="flex items-center justify-center">
                <span className="material-symbols-outlined text-[80px] sm:text-[140px] text-primary/30 leading-none">contactless</span>
              </div>
            </div>
            <div className="text-center space-y-2 sm:space-y-4">
              <h2 className="text-3xl sm:text-5xl md:text-6xl font-black tracking-tighter text-primary uppercase italic leading-none">TAP YOUR CARD</h2>
              <p className="text-[9px] sm:text-[11px] font-black text-slate-400 tracking-[0.5em] sm:tracking-[0.8em] uppercase opacity-50">Awaiting Signal</p>
            </div>
          </div>
        ) : lastScanResult ? (
          <div className="bg-white rounded-[32px] sm:rounded-[48px] shadow-[0_32px_80px_-16px_rgba(0,0,0,0.15)] p-8 sm:p-16 md:p-20 w-full text-center space-y-6 sm:space-y-10 animate-in slide-in-from-bottom-20 duration-500 max-h-full overflow-y-auto no-scrollbar border-t-[8px] sm:border-t-[12px] border-emerald-500">
            <div className={`inline-flex items-center gap-3 sm:gap-4 px-6 sm:px-10 py-2 sm:py-4 rounded-full ${getStatusColor(lastScanResult)} font-bold shadow-sm border`}>
              <span className="material-symbols-outlined text-lg sm:text-2xl leading-none">
                {lastScanResult.isDuplicate ? 'history' : 'check_circle'}
              </span>
              <span className="text-sm sm:text-xl font-black uppercase italic tracking-wide">
                {lastScanResult.isDuplicate ? 'ALREADY LOGGED' : 'Verified'}
              </span>
            </div>
            <div className="space-y-4 sm:space-y-6">
              <div className="space-y-1 sm:space-y-2">
                <h3 className="text-3xl sm:text-5xl md:text-7xl font-black text-primary leading-[1] uppercase tracking-tighter break-words">
                  {lastScanResult.learner.firstName}<br/>{lastScanResult.learner.lastName}
                </h3>
                <div className="flex flex-col items-center gap-1 sm:gap-2">
                  <div className="text-[10px] sm:text-sm font-black text-slate-400 uppercase tracking-[0.2em] sm:tracking-[0.3em] bg-slate-50 px-4 py-1 sm:px-6 sm:py-1.5 rounded-full border border-black/5">
                    {lastScanResult.learner.grade_level} • {lastScanResult.learner.section_name}
                  </div>
                </div>
              </div>
              <div className="flex items-center justify-center gap-2 sm:gap-3 text-slate-300 font-bold tracking-[0.1em] sm:tracking-[0.2em] text-sm sm:text-lg">
                <span className="material-symbols-outlined text-base sm:text-xl leading-none">schedule</span>
                {lastScanResult.time}
              </div>
              {lastScanResult.isDuplicate && (
                <div className="bg-amber-50 rounded-xl sm:rounded-2xl py-3 px-6 sm:py-4 sm:px-8 inline-block mt-2 sm:mt-4 border border-amber-100">
                  <p className="text-amber-700 text-[8px] sm:text-[10px] font-black uppercase tracking-widest">Duplicate Entry Ignored</p>
                </div>
              )}
            </div>
          </div>
        ) : (
          <div className="bg-white rounded-[32px] sm:rounded-[48px] shadow-[0_32px_80px_-16px_rgba(0,0,0,0.15)] p-8 sm:p-16 md:p-20 w-full text-center space-y-6 sm:space-y-10 animate-in shake duration-500 border-b-[8px] sm:border-b-[12px] border-accent max-h-full overflow-y-auto no-scrollbar">
            <div className="w-20 h-20 sm:w-32 sm:h-32 bg-accent/5 rounded-full flex items-center justify-center mx-auto mb-2 sm:mb-4 border border-accent/10">
              <span className="material-symbols-outlined text-4xl sm:text-7xl text-accent leading-none">warning</span>
            </div>
            <div className="space-y-4 sm:space-y-6">
              <h3 className="text-2xl sm:text-4xl font-black text-primary uppercase italic leading-tight">Access Restricted</h3>
              <p className="text-[10px] sm:text-sm font-bold text-slate-400 uppercase tracking-widest font-mono">UID: {unknownTag}</p>
              <div className="h-0.5 sm:h-1 w-16 sm:w-20 bg-accent/10 rounded-full mx-auto" />
              <p className="text-[9px] sm:text-[11px] font-black text-accent uppercase tracking-[0.2em] sm:tracking-[0.3em]">Unknown ID: Registration Required</p>
            </div>
          </div>
        )}
      </div>

      {/* Bottom Spacer Section */}
      <div className="h-8 sm:h-12 w-full flex-shrink-0" />
    </div>
  );
};

export default KioskMode;
